      assert.deepEqual(_[methodName](largeStr), methodName == 'toNumber' ? NaN : 0);

      var endTime = lodashStable.now(),
          timeSpent = endTime - startTime;

      assert.ok(timeSpent < maxMs, 'operation took ' + timeSpent + 'ms');
    });
