// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *

FBL.DomplateLoop.prototype = copyObject(FBL.DomplateTag.prototype,
/** @lends FBL.DomplateLoop.prototype */
{
