/** @class */
function ArrayIterator(array)
{
    var index = -1;

    this.next = function()
    {
        if (++index >= array.length)
            throw StopIteration;

        return array[index];
    };
}

/** @class */
function StopIteration() {}

FBL.$break = function()
{
    throw StopIteration;
};

