    assert.expect(1);
    var Model = Backbone.Model.extend({
      url: '/test/',
      sync: function(method, m, options){ options.success(); },
      validate: function(){ return 'invalid'; }
    });
    var model = new Model({id: 1});
    model.on('invalid', function(){ assert.ok(true); });
    model.save();
  });

