import configparser
import os

import click


class Config:
    """The config in this example only holds aliases."""

    def __init__(self):
        self.path = os.getcwd()
        self.aliases = {}

    def add_alias(self, alias, cmd):
        self.aliases.update({alias: cmd})

    def read_config(self, filename):
        parser = configparser.RawConfigParser()
        parser.read([filename])
        try:
            self.aliases.update(parser.items("aliases"))
        except configparser.NoSectionError:
            pass

    def write_config(self, filename):
        parser = configparser.RawConfigParser()
        parser.add_section("aliases")
        for key, value in self.aliases.items():
            parser.set("aliases", key, value)
        with open(filename, "wb") as file:
            parser.write(file)


pass_config = click.make_pass_decorator(Config, ensure=True)


class AliasedGroup(click.Group):
    """This subclass of a group supports looking up aliases in a config
    file and with a bit of magic.
    """

    def get_command(self, ctx, cmd_name):
        # Step one: built-in commands as normal
        rv = click.Group.get_command(self, ctx, cmd_name)
        if rv is not None:
            return rv

        # Step two: find the config object and ensure it's there.  This
        # will create the config object is missing.
        cfg = ctx.ensure_object(Config)

        # Step three: look up an explicit command alias in the config
        if cmd_name in cfg.aliases:
            actual_cmd = cfg.aliases[cmd_name]
            return click.Group.get_command(self, ctx, actual_cmd)

        # Alternative option: if we did not find an explicit alias we
        # allow automatic abbreviation of the command.  "status" for
        # instance will match "st".  We only allow that however if
        # there is only one command.
        matches = [
            x for x in self.list_commands(ctx) if x.lower().startswith(cmd_name.lower())
        ]
        if not matches:
            return None
        elif len(matches) == 1:
            return click.Group.get_command(self, ctx, matches[0])
        ctx.fail(f"Too many matches: {', '.join(sorted(matches))}")

    def resolve_command(self, ctx, args):
        # always return the command's name, not the alias
        _, cmd, args = super().resolve_command(ctx, args)
        return cmd.name, cmd, args


def read_config(ctx, param, value):
    """Callback that is used whenever --config is passed.  We use this to
    always load the correct config.  This means that the config is loaded
    even if the group itself never executes so our aliases stay always
    available.
    """
    cfg = ctx.ensure_object(Config)
    if value is None:
        value = os.path.join(os.path.dirname(__file__), "aliases.ini")
    cfg.read_config(value)
    return value


@click.command(cls=AliasedGroup)
@click.option(
    "--config",
    type=click.Path(exists=True, dir_okay=False),
    callback=read_config,
    expose_value=False,
    help="The config file to use instead of the default.",
)
def cli():
    """An example application that supports aliases."""


@cli.command()
def push():
    """Pushes changes."""
    click.echo("Push")


@cli.command()
def pull():
    """Pulls changes."""
    click.echo("Pull")


@cli.command()
def clone():
    """Clones a repository."""
    click.echo("Clone")


@cli.command()
def commit():
    """Commits pending changes."""
    click.echo("Commit")


@cli.command()
@pass_config
def status(config):
    """Shows the status."""
    click.echo(f"Status for {config.path}")


@cli.command()
@pass_config
@click.argument("alias_", metavar="ALIAS", type=click.STRING)
@click.argument("cmd", type=click.STRING)
@click.option(
    "--config_file", type=click.Path(exists=True, dir_okay=False), default="aliases.ini"
)
def alias(config, alias_, cmd, config_file):
    """Adds an alias to the specified configuration file."""
    config.add_alias(alias_, cmd)
    config.write_config(config_file)
    click.echo(f"Added '{alias_}' as alias for '{cmd}'")

import os
import posixpath
import sys

import click


class Repo:
    def __init__(self, home):
        self.home = home
        self.config = {}
        self.verbose = False

    def set_config(self, key, value):
        self.config[key] = value
        if self.verbose:
            click.echo(f"  config[{key}] = {value}", file=sys.stderr)

    def __repr__(self):
        return f"<Repo {self.home}>"


pass_repo = click.make_pass_decorator(Repo)


@click.group()
@click.option(
    "--repo-home",
    envvar="REPO_HOME",
    default=".repo",
    metavar="PATH",
    help="Changes the repository folder location.",
)
@click.option(
    "--config",
    nargs=2,
    multiple=True,
    metavar="KEY VALUE",
    help="Overrides a config key/value pair.",
)
@click.option("--verbose", "-v", is_flag=True, help="Enables verbose mode.")
@click.version_option("1.0")
@click.pass_context
def cli(ctx, repo_home, config, verbose):
    """Repo is a command line tool that showcases how to build complex
    command line interfaces with Click.

    This tool is supposed to look like a distributed version control
    system to show how something like this can be structured.
    """
    # Create a repo object and remember it as the context object.  From
    # this point onwards other commands can refer to it by using the
    # @pass_repo decorator.
    ctx.obj = Repo(os.path.abspath(repo_home))
    ctx.obj.verbose = verbose
    for key, value in config:
        ctx.obj.set_config(key, value)


@cli.command()
@click.argument("src")
@click.argument("dest", required=False)
@click.option(
    "--shallow/--deep",
    default=False,
    help="Makes a checkout shallow or deep.  Deep by default.",
)
@click.option(
    "--rev", "-r", default="HEAD", help="Clone a specific revision instead of HEAD."
)
@pass_repo
def clone(repo, src, dest, shallow, rev):
    """Clones a repository.

    This will clone the repository at SRC into the folder DEST.  If DEST
    is not provided this will automatically use the last path component
    of SRC and create that folder.
    """
    if dest is None:
        dest = posixpath.split(src)[-1] or "."
    click.echo(f"Cloning repo {src} to {os.path.basename(dest)}")
    repo.home = dest
    if shallow:
        click.echo("Making shallow checkout")
    click.echo(f"Checking out revision {rev}")


@cli.command()
@click.confirmation_option()
@pass_repo
def delete(repo):
    """Deletes a repository.

    This will throw away the current repository.
    """
    click.echo(f"Destroying repo {repo.home}")
    click.echo("Deleted!")


@cli.command()
@click.option("--username", prompt=True, help="The developer's shown username.")
@click.option("--email", prompt="E-Mail", help="The developer's email address")
@click.password_option(help="The login password.")
@pass_repo
def setuser(repo, username, email, password):
    """Sets the user credentials.

    This will override the current user config.
    """
    repo.set_config("username", username)
    repo.set_config("email", email)
    repo.set_config("password", "*" * len(password))
    click.echo("Changed credentials.")


@cli.command()
@click.option(
    "--message",
    "-m",
    multiple=True,
    help="The commit message.  If provided multiple times each"
    " argument gets converted into a new line.",
)
@click.argument("files", nargs=-1, type=click.Path())
@pass_repo
def commit(repo, files, message):
    """Commits outstanding changes.

    Commit changes to the given files into the repository.  You will need to
    "repo push" to push up your changes to other repositories.

    If a list of files is omitted, all changes reported by "repo status"
    will be committed.
    """
    if not message:
        marker = "# Files to be committed:"
        hint = ["", "", marker, "#"]
        for file in files:
            hint.append(f"#   U {file}")
        message = click.edit("\n".join(hint))
        if message is None:
            click.echo("Aborted!")
            return
        msg = message.split(marker)[0].rstrip()
        if not msg:
            click.echo("Aborted! Empty commit message")
            return
    else:
        msg = "\n".join(message)
    click.echo(f"Files to be committed: {files}")
    click.echo(f"Commit message:\n{msg}")


@cli.command(short_help="Copies files.")
@click.option(
    "--force", is_flag=True, help="forcibly copy over an existing managed file"
)
@click.argument("src", nargs=-1, type=click.Path())
@click.argument("dst", type=click.Path())
@pass_repo
def copy(repo, src, dst, force):
    """Copies one or multiple files to a new location.  This copies all
    files from SRC to DST.
    """
    for fn in src:
        click.echo(f"Copy from {fn} -> {dst}")

from urllib import parse as urlparse

import click


def validate_count(ctx, param, value):
    if value < 0 or value % 2 != 0:
        raise click.BadParameter("Should be a positive, even integer.")
    return value


class URL(click.ParamType[urlparse.ParseResult]):
    name = "url"

    def convert(self, value, param, ctx) -> urlparse.ParseResult:
        if not isinstance(value, tuple):
            value = urlparse.urlparse(value)
            if value.scheme not in ("http", "https"):
                self.fail(
                    f"invalid URL scheme ({value.scheme}). Only HTTP URLs are allowed",
                    param,
                    ctx,
                )
        return value


@click.command()
@click.option(
    "--count", default=2, callback=validate_count, help="A positive even number."
)
@click.option("--foo", help="A mysterious parameter.")
@click.option("--url", help="A URL", type=URL())
@click.version_option()
def cli(count, foo, url):
    """Validation.

    This example validates parameters in different ways.  It does it
    through callbacks, through a custom type as well as by validating
    manually in the function.
    """
    if foo is not None and foo != "wat":
        raise click.BadParameter(
            'If a value is provided it needs to be the value "wat".',
            param_hint=["--foo"],
        )
    click.echo(f"count: {count}")
    click.echo(f"foo: {foo}")
    click.echo(f"url: {url!r}")

# This module is based on the excellent work by Adam Bartoš who
# provided a lot of what went into the implementation here in
# the discussion to issue1602 in the Python bug tracker.
#
# There are some general differences in regards to how this works
# compared to the original patches as we do not need to patch
# the entire interpreter but just work in our little world of
# echo and prompt.
from __future__ import annotations

import collections.abc as cabc
import io
import sys
import time
import typing as t
from ctypes import Array
from ctypes import byref
from ctypes import c_char
from ctypes import c_char_p
from ctypes import c_int
from ctypes import c_ssize_t
from ctypes import c_ulong
from ctypes import c_void_p
from ctypes import POINTER
from ctypes import py_object
from ctypes import Structure
from ctypes.wintypes import DWORD
from ctypes.wintypes import HANDLE
from ctypes.wintypes import LPCWSTR
from ctypes.wintypes import LPWSTR
from gettext import gettext as _

from ._compat import _NonClosingTextIOWrapper

assert sys.platform == "win32"
import msvcrt  # noqa: E402
from ctypes import windll  # noqa: E402
from ctypes import WINFUNCTYPE  # noqa: E402

c_ssize_p = POINTER(c_ssize_t)

kernel32 = windll.kernel32
GetStdHandle = kernel32.GetStdHandle
ReadConsoleW = kernel32.ReadConsoleW
WriteConsoleW = kernel32.WriteConsoleW
GetConsoleMode = kernel32.GetConsoleMode
GetLastError = kernel32.GetLastError
GetCommandLineW = WINFUNCTYPE(LPWSTR)(("GetCommandLineW", windll.kernel32))
CommandLineToArgvW = WINFUNCTYPE(POINTER(LPWSTR), LPCWSTR, POINTER(c_int))(
    ("CommandLineToArgvW", windll.shell32)
)
LocalFree = WINFUNCTYPE(c_void_p, c_void_p)(("LocalFree", windll.kernel32))

STDIN_HANDLE = GetStdHandle(-10)
STDOUT_HANDLE = GetStdHandle(-11)
STDERR_HANDLE = GetStdHandle(-12)

PyBUF_SIMPLE = 0
PyBUF_WRITABLE = 1

ERROR_SUCCESS = 0
ERROR_NOT_ENOUGH_MEMORY = 8
ERROR_OPERATION_ABORTED = 995

STDIN_FILENO = 0
STDOUT_FILENO = 1
STDERR_FILENO = 2

EOF = b"\x1a"
MAX_BYTES_WRITTEN = 32767

if t.TYPE_CHECKING:
    try:
        # Using `typing_extensions.Buffer` instead of `collections.abc`
        # on Windows for some reason does not have `Sized` implemented.
        from collections.abc import Buffer  # type: ignore
    except ImportError:
        from typing_extensions import Buffer

try:
    from ctypes import pythonapi
except ImportError:
    # On PyPy we cannot get buffers so our ability to operate here is
    # severely limited.
    get_buffer = None
else:

    class Py_buffer(Structure):
        _fields_ = [  # noqa: RUF012
            ("buf", c_void_p),
            ("obj", py_object),
            ("len", c_ssize_t),
            ("itemsize", c_ssize_t),
            ("readonly", c_int),
            ("ndim", c_int),
            ("format", c_char_p),
            ("shape", c_ssize_p),
            ("strides", c_ssize_p),
            ("suboffsets", c_ssize_p),
            ("internal", c_void_p),
        ]

    PyObject_GetBuffer = pythonapi.PyObject_GetBuffer
    PyBuffer_Release = pythonapi.PyBuffer_Release

    def get_buffer(obj: Buffer, writable: bool = False) -> Array[c_char]:
        buf = Py_buffer()
        flags: int = PyBUF_WRITABLE if writable else PyBUF_SIMPLE
        PyObject_GetBuffer(py_object(obj), byref(buf), flags)

        try:
            buffer_type = c_char * buf.len
            out: Array[c_char] = buffer_type.from_address(buf.buf)
            return out
        finally:
            PyBuffer_Release(byref(buf))


class _WindowsConsoleRawIOBase(io.RawIOBase):
    def __init__(self, handle: int | None) -> None:
        self.handle = handle

    def isatty(self) -> t.Literal[True]:
        super().isatty()
        return True


class _WindowsConsoleReader(_WindowsConsoleRawIOBase):
    def readable(self) -> t.Literal[True]:
        return True

    def readinto(self, b: Buffer) -> int:
        bytes_to_be_read = len(b)
        if not bytes_to_be_read:
            return 0
        elif bytes_to_be_read % 2:
            raise ValueError(
                "cannot read odd number of bytes from UTF-16-LE encoded console"
            )

        buffer = get_buffer(b, writable=True)
        code_units_to_be_read = bytes_to_be_read // 2
        code_units_read = c_ulong()

        rv = ReadConsoleW(
            HANDLE(self.handle),
            buffer,
            code_units_to_be_read,
            byref(code_units_read),
            None,
        )
        if GetLastError() == ERROR_OPERATION_ABORTED:
            # wait for KeyboardInterrupt
            time.sleep(0.1)
        if not rv:
            raise OSError(_("Windows error: {error}").format(error=GetLastError()))

        if buffer[0] == EOF:
            return 0
        return 2 * code_units_read.value


class _WindowsConsoleWriter(_WindowsConsoleRawIOBase):
    def writable(self) -> t.Literal[True]:
        return True

    @staticmethod
    def _get_error_message(errno: int) -> str:
        if errno == ERROR_SUCCESS:
            return "ERROR_SUCCESS"
        elif errno == ERROR_NOT_ENOUGH_MEMORY:
            return "ERROR_NOT_ENOUGH_MEMORY"
        return _("Windows error: {error}").format(error=errno)

    def write(self, b: Buffer) -> int:
        bytes_to_be_written = len(b)
        buf = get_buffer(b)
        code_units_to_be_written = min(bytes_to_be_written, MAX_BYTES_WRITTEN) // 2
        code_units_written = c_ulong()

        WriteConsoleW(
            HANDLE(self.handle),
            buf,
            code_units_to_be_written,
            byref(code_units_written),
            None,
        )
        bytes_written = 2 * code_units_written.value

        if bytes_written == 0 and bytes_to_be_written > 0:
            raise OSError(self._get_error_message(GetLastError()))
        return bytes_written


class ConsoleStream:
    def __init__(self, text_stream: t.TextIO, byte_stream: t.BinaryIO) -> None:
        self._text_stream = text_stream
        self.buffer = byte_stream

    @property
    def name(self) -> str:
        return self.buffer.name

    def write(self, x: t.AnyStr) -> int:
        if isinstance(x, str):
            return self._text_stream.write(x)
        try:
            self.flush()
        except Exception:
            pass
        return self.buffer.write(x)

    def writelines(self, lines: cabc.Iterable[t.AnyStr]) -> None:
        for line in lines:
            self.write(line)

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._text_stream, name)

    def isatty(self) -> bool:
        return self.buffer.isatty()

    def __repr__(self) -> str:
        return f"<ConsoleStream name={self.name!r} encoding={self.encoding!r}>"


def _get_text_stdin(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedReader(_WindowsConsoleReader(STDIN_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))


def _get_text_stdout(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedWriter(_WindowsConsoleWriter(STDOUT_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))


def _get_text_stderr(buffer_stream: t.BinaryIO) -> t.TextIO:
    text_stream = _NonClosingTextIOWrapper(
        io.BufferedWriter(_WindowsConsoleWriter(STDERR_HANDLE)),
        "utf-16-le",
        "strict",
        line_buffering=True,
    )
    return t.cast(t.TextIO, ConsoleStream(text_stream, buffer_stream))


_stream_factories: cabc.Mapping[int, t.Callable[[t.BinaryIO], t.TextIO]] = {
    0: _get_text_stdin,
    1: _get_text_stdout,
    2: _get_text_stderr,
}


def _is_console(f: t.TextIO) -> bool:
    if not hasattr(f, "fileno"):
        return False

    try:
        fileno = f.fileno()
    except (OSError, io.UnsupportedOperation):
        return False

    handle = msvcrt.get_osfhandle(fileno)
    return bool(GetConsoleMode(handle, byref(DWORD())))


def _get_windows_console_stream(
    f: t.TextIO, encoding: str | None, errors: str | None
) -> t.TextIO | None:
    if (
        get_buffer is None
        or encoding not in {"utf-16-le", None}
        or errors not in {"strict", None}
        or not _is_console(f)
    ):
        return None

    func = _stream_factories.get(f.fileno())
    if func is None:
        return None

    b = getattr(f, "buffer", None)

    if b is None:
        return None

    return func(b)

from __future__ import annotations

import abc
import collections.abc as cabc
import enum
import os
import stat
import sys
import typing as t
import uuid
from datetime import datetime
from gettext import gettext as _
from gettext import ngettext

from ._compat import _get_argv_encoding
from ._compat import open_stream
from .exceptions import BadParameter
from .utils import format_filename
from .utils import LazyFile
from .utils import safecall

if t.TYPE_CHECKING:
    import typing_extensions as te

    from .core import Context
    from .core import Parameter
    from .shell_completion import CompletionItem

_ValueT = t.TypeVar("_ValueT")
_ValueT_contra = t.TypeVar("_ValueT_contra", contravariant=True)
_ValueT_co = t.TypeVar("_ValueT_co", covariant=True)

_FloatValueT = t.TypeVar("_FloatValueT", bound=float)
_FloatValueT_co = t.TypeVar("_FloatValueT_co", bound=float, covariant=True)


class ParamTypeInfoDict(t.TypedDict):
    param_type: str
    name: str


class ParamType(t.Generic[_ValueT_co], abc.ABC):
    """Represents the type of a parameter. Validates and converts values
    from the command line or Python into the correct type.

    To implement a custom type, subclass and implement at least the
    following:

    -   The :attr:`name` class attribute must be set.
    -   Calling an instance of the type with ``None`` must return
        ``None``. This is already implemented by default.
    -   :meth:`convert` must convert string values to the correct type.
    -   :meth:`convert` must accept values that are already the correct
        type.
    -   It must be able to convert a value if the ``ctx`` and ``param``
        arguments are ``None``. This can occur when converting prompt
        input.

    .. versionchanged:: 8.4.0
        Now a generic abstract base class. Parameterize with the
        converted value type (``ParamType[int]`` for an integer-returning
        type) so that :meth:`convert` and downstream consumers carry the
        narrowed return type.
    """

    is_composite: t.ClassVar[bool] = False
    arity: int = 1  # read-only

    #: the descriptive name of this type
    name: str

    #: if a list of this type is expected and the value is pulled from a
    #: string environment variable, this is what splits it up.  `None`
    #: means any whitespace.  For all parameters the general rule is that
    #: whitespace splits them up.  The exception are paths and files which
    #: are split by ``os.path.pathsep`` by default (":" on Unix and ";" on
    #: Windows).
    envvar_list_splitter: t.ClassVar[str | None] = None

    def to_info_dict(self) -> ParamTypeInfoDict:
        """Gather information that could be useful for a tool generating
        user-facing documentation.

        Use :meth:`click.Context.to_info_dict` to traverse the entire
        CLI structure.

        .. versionadded:: 8.0
        """
        # The class name without the "ParamType" suffix.
        param_type = type(self).__name__.partition("ParamType")[0]
        param_type = param_type.partition("ParameterType")[0]

        # Custom subclasses might not remember to set a name.
        if hasattr(self, "name"):
            name = self.name
        else:
            name = param_type

        return {"param_type": param_type, "name": name}

    def __call__(
        self,
        value: t.Any,
        param: Parameter | None = None,
        ctx: Context | None = None,
    ) -> _ValueT_co | None:
        if value is not None:
            return self.convert(value, param, ctx)
        return None

    def get_metavar(self, param: Parameter, ctx: Context) -> str | None:
        """Returns the metavar default for this param if it provides one."""

    def get_missing_message(self, param: Parameter, ctx: Context | None) -> str | None:
        """Optionally might return extra information about a missing
        parameter.

        .. versionadded:: 2.0
        """

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> _ValueT_co:
        """Convert the value to the correct type. This is not called if
        the value is ``None`` (the missing value).

        This must accept string values from the command line, as well as
        values that are already the correct type. It may also convert
        other compatible types.

        The ``param`` and ``ctx`` arguments may be ``None`` in certain
        situations, such as when converting prompt input.

        If the value cannot be converted, call :meth:`fail` with a
        descriptive message.

        :param value: The value to convert.
        :param param: The parameter that is using this type to convert
            its value. May be ``None``.
        :param ctx: The current context that arrived at this value. May
            be ``None``.
        """
        # The default returns the value as-is so subclasses that only customize
        # metadata are not forced to redeclare ``convert``.
        return t.cast("_ValueT_co", value)

    def split_envvar_value(self, rv: str) -> cabc.Sequence[str]:
        """Given a value from an environment variable this splits it up
        into small chunks depending on the defined envvar list splitter.

        If the splitter is set to `None`, which means that whitespace splits,
        then leading and trailing whitespace is ignored.  Otherwise, leading
        and trailing splitters usually lead to empty items being included.
        """
        return (rv or "").split(self.envvar_list_splitter)

    def fail(
        self,
        message: str,
        param: Parameter | None = None,
        ctx: Context | None = None,
    ) -> t.NoReturn:
        """Helper method to fail with an invalid value message."""
        raise BadParameter(message, ctx=ctx, param=param)

    def shell_complete(
        self, ctx: Context, param: Parameter, incomplete: str
    ) -> list[CompletionItem]:
        """Return a list of
        :class:`~click.shell_completion.CompletionItem` objects for the
        incomplete value. Most types do not provide completions, but
        some do, and this allows custom types to provide custom
        completions as well.

        :param ctx: Invocation context for this command.
        :param param: The parameter that is requesting completion.
        :param incomplete: Value being completed. May be empty.

        .. versionadded:: 8.0
        """
        return []


class CompositeParamType(ParamType[_ValueT_co]):
    is_composite: t.ClassVar[bool] = True

    @property
    @abc.abstractmethod
    def arity(self) -> int: ...  # type: ignore[override]


if t.TYPE_CHECKING:
    # on Python 3.10 this will raise a TypeError

    class FuncParamTypeInfoDict(
        ParamTypeInfoDict,
        t.Generic[_ValueT_contra, _ValueT_co],
    ):
        func: t.Callable[[_ValueT_contra], _ValueT_co]
else:

    class FuncParamTypeInfoDict(ParamTypeInfoDict):
        func: t.Callable[[t.Any], t.Any]


class FuncParamType(ParamType[_ValueT_co], t.Generic[_ValueT_contra, _ValueT_co]):
    name: str
    func: t.Callable[[_ValueT_contra], _ValueT_co]

    def __init__(self, func: t.Callable[[_ValueT_contra], _ValueT_co]) -> None:
        self.name = func.__name__
        self.func = func

    def to_info_dict(self) -> FuncParamTypeInfoDict[_ValueT_contra, _ValueT_co]:
        return {"func": self.func, **super().to_info_dict()}

    def convert(
        self, value: _ValueT_contra, param: Parameter | None, ctx: Context | None
    ) -> _ValueT_co:
        try:
            return self.func(value)
        except ValueError as exc:
            message = str(exc)

            if not message:
                try:
                    message = str(value)
                except UnicodeError:
                    message = t.cast("bytes", value).decode("utf-8", "replace")

            self.fail(message, param, ctx)


class UnprocessedParamType(ParamType[t.Any]):
    name = "text"

    def convert(
        self, value: _ValueT, param: Parameter | None, ctx: Context | None
    ) -> _ValueT:
        return value

    def __repr__(self) -> str:
        return "UNPROCESSED"


class StringParamType(ParamType[str]):
    name = "text"

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> str:
        if isinstance(value, bytes):
            enc = _get_argv_encoding()
            try:
                return value.decode(enc)
            except UnicodeError:
                fs_enc = sys.getfilesystemencoding()
                if fs_enc != enc:
                    try:
                        return value.decode(fs_enc)
                    except UnicodeError:
                        return value.decode("utf-8", "replace")
                else:
                    return value.decode("utf-8", "replace")
        return str(value)

    def __repr__(self) -> str:
        return "STRING"


if t.TYPE_CHECKING:
    # on Python 3.10 this will raise a TypeError

    class ChoiceInfoDict(ParamTypeInfoDict, t.Generic[_ValueT_co]):
        choices: tuple[_ValueT_co, ...]
        case_sensitive: bool
else:

    class ChoiceInfoDict(ParamTypeInfoDict):
        choices: tuple[t.Any, ...]
        case_sensitive: bool


class Choice(ParamType[_ValueT_co], t.Generic[_ValueT_co]):
    """The choice type allows a value to be checked against a fixed set
    of supported values.

    You may pass any iterable value which will be converted to a tuple
    and thus will only be iterated once.

    The resulting value will always be one of the originally passed choices.
    See :meth:`normalize_choice` for more info on the mapping of strings
    to choices. See :ref:`choice-opts` for an example.

    :param case_sensitive: Set to false to make choices case
        insensitive. Defaults to true.

    .. versionchanged:: 8.4.0
        Now generic in the choice value type. Parameterize with the type of
        the choice values (``Choice[HashType]`` for an enum, ``Choice[str]``
        for plain strings) to enable type-checked consumers.

    .. versionchanged:: 8.2.0
        Non-``str`` ``choices`` are now supported. It can additionally be any
        iterable. Before you were not recommended to pass anything but a list or
        tuple.

    .. versionadded:: 8.2.0
        Choice normalization can be overridden via :meth:`normalize_choice`.
    """

    name: str = "choice"

    choices: tuple[_ValueT_co, ...]
    case_sensitive: bool

    def __init__(
        self, choices: cabc.Iterable[_ValueT_co], case_sensitive: bool = True
    ) -> None:
        self.choices = tuple(choices)
        self.case_sensitive = case_sensitive

    def to_info_dict(self) -> ChoiceInfoDict[_ValueT_co]:
        return {
            "choices": self.choices,
            "case_sensitive": self.case_sensitive,
            **super().to_info_dict(),
        }

    def _normalized_mapping(
        self, ctx: Context | None = None
    ) -> cabc.Mapping[_ValueT_co, str]:
        """
        Returns mapping where keys are the original choices and the values are
        the normalized values that are accepted via the command line.

        This is a simple wrapper around :meth:`normalize_choice`, use that
        instead which is supported.
        """
        return {
            choice: self.normalize_choice(
                choice=choice,
                ctx=ctx,
            )
            for choice in self.choices
        }

    def normalize_choice(self, choice: object, ctx: Context | None) -> str:
        """
        Normalize a choice value, used to map a passed string to a choice.
        Each choice must have a unique normalized value.

        By default uses :meth:`Context.token_normalize_func` and if not case
        sensitive, convert it to a casefolded value.

        .. versionadded:: 8.2.0
        """
        normed_value = choice.name if isinstance(choice, enum.Enum) else str(choice)

        if ctx is not None and ctx.token_normalize_func is not None:
            normed_value = ctx.token_normalize_func(normed_value)

        if not self.case_sensitive:
            normed_value = normed_value.casefold()

        return normed_value

    def get_metavar(self, param: Parameter, ctx: Context) -> str | None:
        if param.param_type_name == "option" and not param.show_choices:  # type: ignore[attr-defined]
            choice_metavars = [
                convert_type(type(choice)).name.upper() for choice in self.choices
            ]
            choices_str = "|".join([*dict.fromkeys(choice_metavars)])
        else:
            choices_str = "|".join(
                [str(i) for i in self._normalized_mapping(ctx=ctx).values()]
            )

        # Use curly braces to indicate a required argument.
        if param.required and param.param_type_name == "argument":
            return f"{{{choices_str}}}"

        # Use square braces to indicate an option or optional argument.
        return f"[{choices_str}]"

    def get_missing_message(self, param: Parameter, ctx: Context | None) -> str:
        """
        Message shown when no choice is passed.

        .. versionchanged:: 8.2.0 Added ``ctx`` argument.
        """
        return _("Choose from:\n\t{choices}").format(
            choices=",\n\t".join(self._normalized_mapping(ctx=ctx).values())
        )

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> _ValueT_co:
        """
        For a given value from the parser, normalize it and find its
        matching normalized value in the list of choices. Then return the
        matched "original" choice.
        """
        normed_value = self.normalize_choice(choice=value, ctx=ctx)
        normalized_mapping = self._normalized_mapping(ctx=ctx)

        try:
            return next(
                original
                for original, normalized in normalized_mapping.items()
                if normalized == normed_value
            )
        except StopIteration:
            self.fail(
                self.get_invalid_choice_message(value=value, ctx=ctx),
                param=param,
                ctx=ctx,
            )

    def get_invalid_choice_message(self, value: t.Any, ctx: Context | None) -> str:
        """Get the error message when the given choice is invalid.

        :param value: The invalid value.

        .. versionadded:: 8.2
        """
        choices_str = ", ".join(map(repr, self._normalized_mapping(ctx=ctx).values()))
        return ngettext(
            "{value!r} is not {choice}.",
            "{value!r} is not one of {choices}.",
            len(self.choices),
        ).format(value=value, choice=choices_str, choices=choices_str)

    def __repr__(self) -> str:
        return _("Choice({choices})").format(choices=list(self.choices))

    def shell_complete(
        self, ctx: Context, param: Parameter, incomplete: str
    ) -> list[CompletionItem]:
        """Complete choices that start with the incomplete value.

        :param ctx: Invocation context for this command.
        :param param: The parameter that is requesting completion.
        :param incomplete: Value being completed. May be empty.

        .. versionadded:: 8.0
        """
        from click.shell_completion import CompletionItem

        str_choices = [self.normalize_choice(choice, ctx) for choice in self.choices]
        if self.case_sensitive:
            matched = (c for c in str_choices if c.startswith(incomplete))
        else:
            incomplete = incomplete.lower()
            matched = (c for c in str_choices if c.lower().startswith(incomplete))

        return [CompletionItem(c) for c in matched]


class DateTimeInfoDict(ParamTypeInfoDict):
    formats: cabc.Sequence[str]


class DateTime(ParamType[datetime]):
    """The DateTime type converts date strings into `datetime` objects.

    The format strings which are checked are configurable, but default to some
    common (non-timezone aware) ISO 8601 formats.

    When specifying *DateTime* formats, you should only pass a list or a tuple.
    Other iterables, like generators, may lead to surprising results.

    The format strings are processed using ``datetime.strptime``, and this
    consequently defines the format strings which are allowed.

    Parsing is tried using each format, in order, and the first format which
    parses successfully is used.

    :param formats: A list or tuple of date format strings, in the order in
                    which they should be tried. Defaults to
                    ``'%Y-%m-%d'``, ``'%Y-%m-%dT%H:%M:%S'``,
                    ``'%Y-%m-%d %H:%M:%S'``.
    """

    name = "datetime"

    formats: cabc.Sequence[str]

    def __init__(self, formats: cabc.Sequence[str] | None = None):
        self.formats = formats or [
            "%Y-%m-%d",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
        ]

    def to_info_dict(self) -> DateTimeInfoDict:
        return {"formats": self.formats, **super().to_info_dict()}

    def get_metavar(self, param: Parameter, ctx: Context) -> str:
        return f"[{'|'.join(self.formats)}]"

    def _try_to_convert_date(self, value: t.Any, format: str) -> datetime | None:
        try:
            return datetime.strptime(value, format)
        except ValueError:
            return None

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> datetime:
        if isinstance(value, datetime):
            return value

        for format in self.formats:
            converted = self._try_to_convert_date(value, format)

            if converted is not None:
                return converted

        formats_str = ", ".join(map(repr, self.formats))
        self.fail(
            ngettext(
                "{value!r} does not match the format {format}.",
                "{value!r} does not match the formats {formats}.",
                len(self.formats),
            ).format(value=value, format=formats_str, formats=formats_str),
            param,
            ctx,
        )

    def __repr__(self) -> str:
        return "DateTime"


class _NumberParamTypeBase(
    ParamType[_ValueT_co], t.Generic[_ValueT_contra, _ValueT_co]
):
    _number_class: t.Callable[[_ValueT_contra], _ValueT_co]

    def convert(
        self, value: _ValueT_contra, param: Parameter | None, ctx: Context | None
    ) -> _ValueT_co:
        try:
            return self._number_class(value)
        except ValueError:
            self.fail(
                _("{value!r} is not a valid {number_type}.").format(
                    value=value, number_type=self.name
                ),
                param,
                ctx,
            )


if t.TYPE_CHECKING:
    # on Python 3.10 this will raise a TypeError

    class NumberRangeInfoDict(ParamTypeInfoDict, t.Generic[_FloatValueT_co]):
        min: _FloatValueT_co | None
        max: _FloatValueT_co | None
        min_open: bool
        max_open: bool
        clamp: bool
else:

    class NumberRangeInfoDict(ParamTypeInfoDict):
        min: t.Any | None
        max: t.Any | None
        min_open: bool
        max_open: bool
        clamp: bool


class _NumberRangeBase(
    _NumberParamTypeBase[_ValueT_contra, _FloatValueT_co],
    t.Generic[_ValueT_contra, _FloatValueT_co],
):
    min: _FloatValueT_co | None
    max: _FloatValueT_co | None
    min_open: bool
    max_open: bool
    clamp: bool

    def __init__(
        self,
        min: _FloatValueT_co | None = None,
        max: _FloatValueT_co | None = None,
        min_open: bool = False,
        max_open: bool = False,
        clamp: bool = False,
    ) -> None:
        self.min = min
        self.max = max
        self.min_open = min_open
        self.max_open = max_open
        self.clamp = clamp

    def to_info_dict(self) -> NumberRangeInfoDict[_FloatValueT_co]:
        return {
            "min": self.min,
            "max": self.max,
            "min_open": self.min_open,
            "max_open": self.max_open,
            "clamp": self.clamp,
            **super().to_info_dict(),
        }

    def convert(
        self, value: _ValueT_contra, param: Parameter | None, ctx: Context | None
    ) -> _FloatValueT_co:
        import operator

        rv = super().convert(value, param, ctx)
        min = self.min
        max = self.max
        lt_min: bool = min is not None and (
            operator.le if self.min_open else operator.lt
        )(rv, min)
        gt_max: bool = max is not None and (
            operator.ge if self.max_open else operator.gt
        )(rv, max)

        if self.clamp:
            if min is not None and lt_min:
                return self._clamp(min, 1, self.min_open)

            if max is not None and gt_max:
                return self._clamp(max, -1, self.max_open)

        if lt_min or gt_max:
            self.fail(
                _("{value} is not in the range {range}.").format(
                    value=rv, range=self._describe_range()
                ),
                param,
                ctx,
            )

        return rv

    @abc.abstractmethod
    def _clamp(
        # Covariant type variables cannot be used in input positions, so we use a
        # separate method-scoped type variable instead.
        self: _NumberRangeBase[t.Any, _FloatValueT],
        bound: _FloatValueT,
        dir: t.Literal[1, -1],
        open: bool,
    ) -> _FloatValueT:
        """Find the valid value to clamp to bound in the given
        direction.

        :param bound: The boundary value.
        :param dir: 1 or -1 indicating the direction to move.
        :param open: If true, the range does not include the bound.
        """
        ...

    def _describe_range(self) -> str:
        """Describe the range for use in help text."""
        if self.min is None:
            op = "<" if self.max_open else "<="
            return f"x{op}{self.max}"

        if self.max is None:
            op = ">" if self.min_open else ">="
            return f"x{op}{self.min}"

        lop = "<" if self.min_open else "<="
        rop = "<" if self.max_open else "<="
        return f"{self.min}{lop}x{rop}{self.max}"

    def __repr__(self) -> str:
        clamp = " clamped" if self.clamp else ""
        return f"<{type(self).__name__} {self._describe_range()}{clamp}>"


class IntParamType(_NumberParamTypeBase[t.SupportsInt | t.SupportsIndex, int]):
    name = "integer"
    _number_class = int

    def __repr__(self) -> str:
        return "INT"


class IntRange(_NumberRangeBase[int, int], IntParamType):
    """Restrict an :data:`click.INT` value to a range of accepted
    values. See :ref:`ranges`.

    If ``min`` or ``max`` are not passed, any value is accepted in that
    direction. If ``min_open`` or ``max_open`` are enabled, the
    corresponding boundary is not included in the range.

    If ``clamp`` is enabled, a value outside the range is clamped to the
    boundary instead of failing.

    .. versionchanged:: 8.0
        Added the ``min_open`` and ``max_open`` parameters.
    """

    name = "integer range"

    def _clamp(self, bound: int, dir: t.Literal[1, -1], open: bool) -> int:
        if not open:
            return bound

        return bound + dir


class FloatParamType(_NumberParamTypeBase[t.SupportsFloat | t.SupportsIndex, float]):
    name = "float"
    _number_class = float

    def __repr__(self) -> str:
        return "FLOAT"


class FloatRange(_NumberRangeBase[float, float], FloatParamType):
    """Restrict a :data:`click.FLOAT` value to a range of accepted
    values. See :ref:`ranges`.

    If ``min`` or ``max`` are not passed, any value is accepted in that
    direction. If ``min_open`` or ``max_open`` are enabled, the
    corresponding boundary is not included in the range.

    If ``clamp`` is enabled, a value outside the range is clamped to the
    boundary instead of failing. This is not supported if either
    boundary is marked ``open``.

    .. versionchanged:: 8.0
        Added the ``min_open`` and ``max_open`` parameters.
    """

    name = "float range"

    def __init__(
        self,
        min: float | None = None,
        max: float | None = None,
        min_open: bool = False,
        max_open: bool = False,
        clamp: bool = False,
    ) -> None:
        super().__init__(
            min=min, max=max, min_open=min_open, max_open=max_open, clamp=clamp
        )

        if (min_open or max_open) and clamp:
            raise TypeError("Clamping is not supported for open bounds.")

    def _clamp(self, bound: float, dir: t.Literal[1, -1], open: bool) -> float:
        if not open:
            return bound

        # Could use math.nextafter here, but clamping an
        # open float range doesn't seem to be particularly useful. It's
        # left up to the user to write a callback to do it if needed.
        raise RuntimeError("Clamping is not supported for open bounds.")


class BoolParamType(ParamType[bool]):
    name = "boolean"

    bool_states: dict[str, bool] = {
        "1": True,
        "0": False,
        "yes": True,
        "no": False,
        "true": True,
        "false": False,
        "on": True,
        "off": False,
        "t": True,
        "f": False,
        "y": True,
        "n": False,
        # Absence of value is considered False.
        "": False,
    }
    """A mapping of string values to boolean states.

    Mapping is inspired by :py:attr:`configparser.ConfigParser.BOOLEAN_STATES`
    and extends it.

    .. caution::
        String values are lower-cased, as the ``str_to_bool`` comparison function
        below is case-insensitive.

    .. warning::
        The mapping is not exhaustive, and does not cover all possible boolean strings
        representations. It will remains as it is to avoid endless bikeshedding.

        Future work my be considered to make this mapping user-configurable from public
        API.
    """

    @staticmethod
    def str_to_bool(value: str | bool) -> bool | None:
        """Convert a string to a boolean value.

        If the value is already a boolean, it is returned as-is. If the value is a
        string, it is stripped of whitespaces and lower-cased, then checked against
        the known boolean states pre-defined in the `BoolParamType.bool_states` mapping
        above.

        Returns `None` if the value does not match any known boolean state.
        """
        if isinstance(value, bool):
            return value
        return BoolParamType.bool_states.get(value.strip().lower())

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> bool:
        normalized = self.str_to_bool(value)
        if normalized is None:
            self.fail(
                _(
                    "{value!r} is not a valid boolean. Recognized values: {states}"
                ).format(value=value, states=", ".join(sorted(self.bool_states))),
                param,
                ctx,
            )
        return normalized

    def __repr__(self) -> str:
        return "BOOL"


class UUIDParameterType(ParamType[uuid.UUID]):
    name = "uuid"

    def convert(
        self, value: uuid.UUID | str, param: Parameter | None, ctx: Context | None
    ) -> uuid.UUID:
        if isinstance(value, uuid.UUID):
            return value

        value = value.strip()

        try:
            return uuid.UUID(value)
        except ValueError:
            self.fail(
                _("{value!r} is not a valid UUID.").format(value=value), param, ctx
            )

    def __repr__(self) -> str:
        return "UUID"


class FileInfoDict(ParamTypeInfoDict):
    mode: str
    encoding: str | None


class File(ParamType[t.IO[t.Any]]):
    """Declares a parameter to be a file for reading or writing.  The file
    is automatically closed once the context tears down (after the command
    finished working).

    Files can be opened for reading or writing.  The special value ``-``
    indicates stdin or stdout depending on the mode.

    By default, the file is opened for reading text data, but it can also be
    opened in binary mode or for writing.  The encoding parameter can be used
    to force a specific encoding.

    The `lazy` flag controls if the file should be opened immediately or upon
    first IO. The default is to be non-lazy for standard input and output
    streams as well as files opened for reading, `lazy` otherwise. When opening a
    file lazily for reading, it is still opened temporarily for validation, but
    will not be held open until first IO. lazy is mainly useful when opening
    for writing to avoid creating the file until it is needed.

    Files can also be opened atomically in which case all writes go into a
    separate file in the same folder and upon completion the file will
    be moved over to the original location.  This is useful if a file
    regularly read by other users is modified.

    See :ref:`file-args` for more information.

    .. versionchanged:: 2.0
        Added the ``atomic`` parameter.
    """

    name = "filename"
    envvar_list_splitter: t.ClassVar[str] = os.path.pathsep

    mode: str
    encoding: str | None
    errors: str | None
    lazy: bool | None
    atomic: bool

    def __init__(
        self,
        mode: str = "r",
        encoding: str | None = None,
        errors: str | None = "strict",
        lazy: bool | None = None,
        atomic: bool = False,
    ) -> None:
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.lazy = lazy
        self.atomic = atomic

    def to_info_dict(self) -> FileInfoDict:
        return {
            "mode": self.mode,
            "encoding": self.encoding,
            **super().to_info_dict(),
        }

    def resolve_lazy_flag(self, value: str | os.PathLike[str]) -> bool:
        if self.lazy is not None:
            return self.lazy
        if os.fspath(value) == "-":
            return False
        elif "w" in self.mode:
            return True
        return False

    def convert(
        self,
        value: str | os.PathLike[str] | t.IO[t.Any],
        param: Parameter | None,
        ctx: Context | None,
    ) -> t.IO[t.Any]:
        if _is_file_like(value):
            return value

        try:
            lazy = self.resolve_lazy_flag(value)

            if lazy:
                lf = LazyFile(
                    value, self.mode, self.encoding, self.errors, atomic=self.atomic
                )

                if ctx is not None:
                    ctx.call_on_close(lf.close_intelligently)

                return t.cast("t.IO[t.Any]", lf)

            f, should_close = open_stream(
                value, self.mode, self.encoding, self.errors, atomic=self.atomic
            )

            # If a context is provided, we automatically close the file
            # at the end of the context execution (or flush out).  If a
            # context does not exist, it's the caller's responsibility to
            # properly close the file.  This for instance happens when the
            # type is used with prompts.
            if ctx is not None:
                if should_close:
                    ctx.call_on_close(safecall(f.close))
                else:
                    ctx.call_on_close(safecall(f.flush))

            return f
        except OSError as e:
            self.fail(
                f"'{format_filename(value)}': {e.strerror}",
                param,
                ctx,
            )

    def shell_complete(
        self, ctx: Context, param: Parameter, incomplete: str
    ) -> list[CompletionItem]:
        """Return a special completion marker that tells the completion
        system to use the shell to provide file path completions.

        :param ctx: Invocation context for this command.
        :param param: The parameter that is requesting completion.
        :param incomplete: Value being completed. May be empty.

        .. versionadded:: 8.0
        """
        from click.shell_completion import CompletionItem

        return [CompletionItem(incomplete, type="file")]


def _is_file_like(value: t.Any) -> te.TypeIs[t.IO[t.Any]]:
    return hasattr(value, "read") or hasattr(value, "write")


class PathInfoDict(ParamTypeInfoDict):
    exists: bool
    file_okay: bool
    dir_okay: bool
    writable: bool
    readable: bool
    allow_dash: bool


class Path(ParamType[str | bytes | os.PathLike[str]]):
    """The ``Path`` type is similar to the :class:`File` type, but
    returns the filename instead of an open file. Various checks can be
    enabled to validate the type of file and permissions.

    :param exists: The file or directory needs to exist for the value to
        be valid. If this is not set to ``True``, and the file does not
        exist, then all further checks are silently skipped.
    :param file_okay: Allow a file as a value.
    :param dir_okay: Allow a directory as a value.
    :param readable: if true, a readable check is performed.
    :param writable: if true, a writable check is performed.
    :param executable: if true, an executable check is performed.
    :param resolve_path: Make the value absolute and resolve any
        symlinks. A ``~`` is not expanded, as this is supposed to be
        done by the shell only.
    :param allow_dash: Allow a single dash as a value, which indicates
        a standard stream (but does not open it). Use
        :func:`~click.open_file` to handle opening this value.
    :param path_type: Convert the incoming path value to this type. If
        ``None``, keep Python's default, which is ``str``. Useful to
        convert to :class:`pathlib.Path`.

    .. versionchanged:: 8.1
        Added the ``executable`` parameter.

    .. versionchanged:: 8.0
        Allow passing ``path_type=pathlib.Path``.

    .. versionchanged:: 6.0
        Added the ``allow_dash`` parameter.
    """

    envvar_list_splitter: t.ClassVar[str] = os.path.pathsep

    exists: bool
    file_okay: bool
    dir_okay: bool
    readable: bool
    writable: bool
    executable: bool
    resolve_path: bool
    allow_dash: bool
    name: str

    def __init__(
        self,
        exists: bool = False,
        file_okay: bool = True,
        dir_okay: bool = True,
        writable: bool = False,
        readable: bool = True,
        resolve_path: bool = False,
        allow_dash: bool = False,
        path_type: type | None = None,
        executable: bool = False,
    ) -> None:
        self.exists = exists
        self.file_okay = file_okay
        self.dir_okay = dir_okay
        self.readable = readable
        self.writable = writable
        self.executable = executable
        self.resolve_path = resolve_path
        self.allow_dash = allow_dash
        self.type: type | None = path_type

        if self.file_okay and not self.dir_okay:
            self.name = _("file")
        elif self.dir_okay and not self.file_okay:
            self.name = _("directory")
        else:
            self.name = _("path")

    def to_info_dict(self) -> PathInfoDict:
        return {
            "exists": self.exists,
            "file_okay": self.file_okay,
            "dir_okay": self.dir_okay,
            "writable": self.writable,
            "readable": self.readable,
            "allow_dash": self.allow_dash,
            **super().to_info_dict(),
        }

    def coerce_path_result(
        self, value: str | os.PathLike[str]
    ) -> str | bytes | os.PathLike[str]:
        if self.type is not None and not isinstance(value, self.type):
            if self.type is str:
                return os.fsdecode(value)
            elif self.type is bytes:
                return os.fsencode(value)
            else:
                return t.cast("os.PathLike[str]", self.type(value))

        return value

    def convert(
        self,
        value: str | os.PathLike[str],
        param: Parameter | None,
        ctx: Context | None,
    ) -> str | bytes | os.PathLike[str]:
        rv = value

        is_dash = self.file_okay and self.allow_dash and rv in (b"-", "-")

        if not is_dash:
            if self.resolve_path:
                rv = os.path.realpath(rv)

            try:
                st = os.stat(rv)
            except OSError:
                if not self.exists:
                    return self.coerce_path_result(rv)
                self.fail(
                    _("{name} {filename!r} does not exist.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )

            if not self.file_okay and stat.S_ISREG(st.st_mode):
                self.fail(
                    _("{name} {filename!r} is a file.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )
            if not self.dir_okay and stat.S_ISDIR(st.st_mode):
                self.fail(
                    _("{name} {filename!r} is a directory.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )

            if self.readable and not os.access(rv, os.R_OK):
                self.fail(
                    _("{name} {filename!r} is not readable.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )

            if self.writable and not os.access(rv, os.W_OK):
                self.fail(
                    _("{name} {filename!r} is not writable.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )

            if self.executable and not os.access(value, os.X_OK):
                self.fail(
                    _("{name} {filename!r} is not executable.").format(
                        name=self.name.title(), filename=format_filename(value)
                    ),
                    param,
                    ctx,
                )

        return self.coerce_path_result(rv)

    def shell_complete(
        self, ctx: Context, param: Parameter, incomplete: str
    ) -> list[CompletionItem]:
        """Return a special completion marker that tells the completion
        system to use the shell to provide path completions for only
        directories or any paths.

        :param ctx: Invocation context for this command.
        :param param: The parameter that is requesting completion.
        :param incomplete: Value being completed. May be empty.

        .. versionadded:: 8.0
        """
        from click.shell_completion import CompletionItem

        type = "dir" if self.dir_okay and not self.file_okay else "file"
        return [CompletionItem(incomplete, type=type)]


class TupleInfoDict(ParamTypeInfoDict):
    types: cabc.Sequence[ParamTypeInfoDict]


class Tuple(CompositeParamType[tuple[t.Any, ...]]):
    """The default behavior of Click is to apply a type on a value directly.
    This works well in most cases, except for when `nargs` is set to a fixed
    count and different types should be used for different items.  In this
    case the :class:`Tuple` type can be used.  This type can only be used
    if `nargs` is set to a fixed number.

    For more information see :ref:`tuple-type`.

    This can be selected by using a Python tuple literal as a type.

    :param types: a list of types that should be used for the tuple items.
    """

    def __init__(self, types: cabc.Sequence[type[t.Any] | ParamType[t.Any]]) -> None:
        self.types: cabc.Sequence[ParamType[t.Any]] = [convert_type(ty) for ty in types]

    def to_info_dict(self) -> TupleInfoDict:
        return {
            "types": [ty.to_info_dict() for ty in self.types],
            **super().to_info_dict(),
        }

    @property
    def name(self) -> str:  # type: ignore[override]
        return f"<{' '.join(ty.name for ty in self.types)}>"

    @property
    def arity(self) -> int:  # type: ignore[override]
        return len(self.types)

    def convert(
        self, value: t.Any, param: Parameter | None, ctx: Context | None
    ) -> tuple[t.Any, ...]:
        len_type = len(self.types)
        len_value = len(value)

        if len_value != len_type:
            self.fail(
                ngettext(
                    "{len_type} values are required, but {len_value} was given.",
                    "{len_type} values are required, but {len_value} were given.",
                    len_value,
                ).format(len_type=len_type, len_value=len_value),
                param=param,
                ctx=ctx,
            )

        return tuple(
            ty(x, param, ctx) for ty, x in zip(self.types, value, strict=False)
        )


def _guess_type(
    ty: type[t.Any] | ParamType[t.Any] | None,
    default: t.Any | None,
) -> type[t.Any] | tuple[type[t.Any], ...] | ParamType[t.Any] | None:
    """Infer a type from *ty* or *default*.

    Returns *ty* unchanged when it is not ``None``.  Otherwise inspects
    *default* to produce a ``type``, a ``tuple`` of types (for tuple
    defaults), or ``None``.
    """
    if ty is not None:
        return ty

    if default is None:
        return None

    if not isinstance(default, (tuple, list)):
        return type(default)

    # If the default is empty, return None so convert_type falls
    # through to STRING.
    if not default:
        return None

    item = default[0]

    # A sequence of iterables needs to detect the inner types.
    # Can't call convert_type recursively because that would
    # incorrectly unwind the tuple to a single type.
    if isinstance(item, (tuple, list)):
        return tuple(map(type, item))

    return type(item)


@t.overload
def convert_type(ty: None, default: None = None) -> StringParamType: ...
@t.overload
def convert_type(
    ty: type | ParamType[t.Any], default: t.Any | None = None
) -> ParamType[t.Any]: ...
@t.overload
def convert_type(
    ty: t.Any | None, default: t.Any | None = None
) -> ParamType[t.Any]: ...
def convert_type(
    ty: t.Any | None = None, default: t.Any | None = None
) -> ParamType[t.Any]:
    """Find the most appropriate :class:`ParamType` for the given Python
    type. If the type isn't provided, it can be inferred from a default
    value.
    """
    guessed = _guess_type(ty, default)
    is_guessed = guessed is not ty

    if isinstance(guessed, tuple):
        return Tuple(guessed)

    if isinstance(guessed, ParamType):
        return guessed

    if guessed is str or guessed is None:
        return STRING

    if guessed is int:
        return INT

    if guessed is float:
        return FLOAT

    if guessed is bool:
        return BOOL

    if is_guessed:
        return STRING

    if __debug__:
        try:
            if issubclass(guessed, ParamType):
                raise AssertionError(
                    f"Attempted to use an uninstantiated parameter type ({guessed})."
                )
        except TypeError:
            # guessed is an instance (correct), so issubclass fails.
            pass

    return FuncParamType(guessed)


#: A dummy parameter type that just does nothing.  From a user's
#: perspective this appears to just be the same as `STRING` but
#: internally no string conversion takes place if the input was bytes.
#: This is usually useful when working with file paths as they can
#: appear in bytes and unicode.
#:
#: For path related uses the :class:`Path` type is a better choice but
#: there are situations where an unprocessed type is useful which is why
#: it is provided.
#:
#: .. versionadded:: 4.0
UNPROCESSED: t.Final[UnprocessedParamType] = UnprocessedParamType()

#: A unicode string parameter type which is the implicit default.  This
#: can also be selected by using ``str`` as type.
STRING: t.Final[StringParamType] = StringParamType()

#: An integer parameter.  This can also be selected by using ``int`` as
#: type.
INT: t.Final[IntParamType] = IntParamType()

#: A floating point value parameter.  This can also be selected by using
#: ``float`` as type.
FLOAT: t.Final[FloatParamType] = FloatParamType()

#: A boolean parameter.  This is the default for boolean flags.  This can
#: also be selected by using ``bool`` as a type.
BOOL: t.Final[BoolParamType] = BoolParamType()

#: A UUID parameter.
UUID: t.Final[UUIDParameterType] = UUIDParameterType()


class OptionHelpExtra(t.TypedDict, total=False):
    envvars: tuple[str, ...]
    default: str
    range: str
    required: str

from __future__ import annotations

import collections.abc as cabc
import typing as t
from gettext import gettext as _
from gettext import ngettext

from ._compat import get_text_stderr
from .globals import resolve_color_default
from .utils import echo
from .utils import format_filename

if t.TYPE_CHECKING:
    from .core import Command
    from .core import Context
    from .core import Parameter


def _join_param_hints(param_hint: cabc.Sequence[str] | str | None) -> str | None:
    if param_hint is not None and not isinstance(param_hint, str):
        return " / ".join(repr(x) for x in param_hint)

    return param_hint


def _format_possibilities(possibilities: list[str]) -> str:
    possibility_str = ", ".join(repr(p) for p in sorted(possibilities))
    return ngettext(
        "Did you mean {possibility}?",
        "(Did you mean one of: {possibilities}?)",
        len(possibilities),
    ).format(possibility=possibility_str, possibilities=possibility_str)


class ClickException(Exception):
    """An exception that Click can handle and show to the user."""

    #: The exit code for this exception.
    exit_code: t.ClassVar[int] = 1

    show_color: t.Final[bool | None]
    message: t.Final[str]

    def __init__(self, message: str) -> None:
        super().__init__(message)
        # The context will be removed by the time we print the message, so cache
        # the color settings here to be used later on (in `show`)
        self.show_color = resolve_color_default()
        self.message = message

    def format_message(self) -> str:
        return self.message

    def __str__(self) -> str:
        return self.message

    def show(self, file: t.IO[t.Any] | None = None) -> None:
        if file is None:
            file = get_text_stderr()

        echo(
            _("Error: {message}").format(message=self.format_message()),
            file=file,
            color=self.show_color,
        )


class UsageError(ClickException):
    """An internal exception that signals a usage error.  This typically
    aborts any further handling.

    :param message: the error message to display.
    :param ctx: optionally the context that caused this error.  Click will
                fill in the context automatically in some situations.
    """

    exit_code: t.ClassVar[int] = 2

    ctx: Context | None
    cmd: t.Final[Command | None]

    def __init__(self, message: str, ctx: Context | None = None) -> None:
        super().__init__(message)
        self.ctx = ctx
        self.cmd = self.ctx.command if self.ctx else None

    def show(self, file: t.IO[t.Any] | None = None) -> None:
        if file is None:
            file = get_text_stderr()
        color = None
        hint = ""
        if (
            self.ctx is not None
            and self.ctx.command.get_help_option(self.ctx) is not None
        ):
            help_names = self.ctx.command.get_help_option_names(self.ctx)
            # Pick the longest name (like ``--help`` over ``-h``) for
            # readability in error messages.
            hint = _("Try '{command} {option}' for help.").format(
                command=self.ctx.command_path,
                option=max(help_names, key=len),
            )
            hint = f"{hint}\n"
        if self.ctx is not None:
            color = self.ctx.color
            echo(f"{self.ctx.get_usage()}\n{hint}", file=file, color=color)
        echo(
            _("Error: {message}").format(message=self.format_message()),
            file=file,
            color=color,
        )


class BadParameter(UsageError):
    """An exception that formats out a standardized error message for a
    bad parameter.  This is useful when thrown from a callback or type as
    Click will attach contextual information to it (for instance, which
    parameter it is).

    .. versionadded:: 2.0

    :param param: the parameter object that caused this error.  This can
                  be left out, and Click will attach this info itself
                  if possible.
    :param param_hint: a string that shows up as parameter name.  This
                       can be used as alternative to `param` in cases
                       where custom validation should happen.  If it is
                       a string it's used as such, if it's a list then
                       each item is quoted and separated.
    """

    param: Parameter | None
    param_hint: cabc.Sequence[str] | str | None

    def __init__(
        self,
        message: str,
        ctx: Context | None = None,
        param: Parameter | None = None,
        param_hint: cabc.Sequence[str] | str | None = None,
    ) -> None:
        super().__init__(message, ctx)
        self.param = param
        self.param_hint = param_hint

    def format_message(self) -> str:
        if self.param_hint is not None:
            param_hint = self.param_hint
        elif self.param is not None:
            param_hint = self.param.get_error_hint(self.ctx)
        else:
            return _("Invalid value: {message}").format(message=self.message)

        return _("Invalid value for {param_hint}: {message}").format(
            param_hint=_join_param_hints(param_hint), message=self.message
        )


class MissingParameter(BadParameter):
    """Raised if click required an option or argument but it was not
    provided when invoking the script.

    .. versionadded:: 4.0

    :param param_type: a string that indicates the type of the parameter.
                       The default is to inherit the parameter type from
                       the given `param`.  Valid values are ``'parameter'``,
                       ``'option'`` or ``'argument'``.
    """

    param_type: t.Final[str | None]

    def __init__(
        self,
        message: str | None = None,
        ctx: Context | None = None,
        param: Parameter | None = None,
        param_hint: cabc.Sequence[str] | str | None = None,
        param_type: str | None = None,
    ) -> None:
        super().__init__(message or "", ctx, param, param_hint)
        self.param_type = param_type

    def format_message(self) -> str:
        if self.param_hint is not None:
            param_hint: cabc.Sequence[str] | str | None = self.param_hint
        elif self.param is not None:
            param_hint = self.param.get_error_hint(self.ctx)
        else:
            param_hint = None

        param_hint = _join_param_hints(param_hint)
        param_hint = f" {param_hint}" if param_hint else ""

        param_type = self.param_type
        if param_type is None and self.param is not None:
            param_type = self.param.param_type_name

        msg = self.message
        if self.param is not None:
            msg_extra = self.param.type.get_missing_message(
                param=self.param, ctx=self.ctx
            )
            if msg_extra:
                if msg:
                    msg += f". {msg_extra}"
                else:
                    msg = msg_extra

        msg = f" {msg}" if msg else ""

        # Translate param_type for known types.
        if param_type == "argument":
            missing = _("Missing argument")
        elif param_type == "option":
            missing = _("Missing option")
        elif param_type == "parameter":
            missing = _("Missing parameter")
        else:
            missing = _("Missing {param_type}").format(param_type=param_type)

        return f"{missing}{param_hint}.{msg}"

    def __str__(self) -> str:
        if not self.message:
            param_name = self.param.name if self.param else None
            return _("Missing parameter: {param_name}").format(param_name=param_name)
        else:
            return self.message


class NoSuchOption(UsageError):
    """Raised if Click attempted to handle an option that does not exist.

    .. versionadded:: 4.0
    """

    option_name: t.Final[str]
    possibilities: t.Final[list[str] | None]

    def __init__(
        self,
        option_name: str,
        message: str | None = None,
        possibilities: cabc.Iterable[str] | None = None,
        ctx: Context | None = None,
    ) -> None:
        if message is None:
            message = _("No such option {name!r}.").format(name=option_name)

        super().__init__(message, ctx)
        self.option_name = option_name

        if possibilities:
            from difflib import get_close_matches

            possibilities_ = get_close_matches(option_name, possibilities)
        else:
            possibilities_ = None
        self.possibilities = possibilities_

    def format_message(self) -> str:
        if not self.possibilities:
            return self.message
        return f"{self.message} {_format_possibilities(self.possibilities)}"


class NoSuchCommand(UsageError):
    """Raised if Click attempted to handle a command that does not exist.

    .. versionadded:: 8.4.0
    """

    command_name: t.Final[str]
    possibilities: t.Final[list[str] | None]

    def __init__(
        self,
        command_name: str,
        message: str | None = None,
        possibilities: cabc.Iterable[str] | None = None,
        ctx: Context | None = None,
    ) -> None:
        if message is None:
            message = _("No such command {name!r}.").format(name=command_name)

        super().__init__(message, ctx)
        self.command_name = command_name

        if possibilities:
            from difflib import get_close_matches

            possibilities_ = get_close_matches(command_name, possibilities)
        else:
            possibilities_ = None
        self.possibilities = possibilities_

    def format_message(self) -> str:
        if not self.possibilities:
            return self.message
        return f"{self.message} {_format_possibilities(self.possibilities)}"


class BadOptionUsage(UsageError):
    """Raised if an option is generally supplied but the use of the option
    was incorrect.  This is for instance raised if the number of arguments
    for an option is not correct.

    .. versionadded:: 4.0

    :param option_name: the name of the option being used incorrectly.
    """

    option_name: t.Final[str]

    def __init__(
        self, option_name: str, message: str, ctx: Context | None = None
    ) -> None:
        super().__init__(message, ctx)
        self.option_name = option_name


class BadArgumentUsage(UsageError):
    """Raised if an argument is generally supplied but the use of the argument
    was incorrect.  This is for instance raised if the number of values
    for an argument is not correct.

    .. versionadded:: 6.0
    """


class NoArgsIsHelpError(UsageError):
    ctx: Context

    def __init__(self, ctx: Context) -> None:
        super().__init__(ctx.get_help(), ctx=ctx)

    def show(self, file: t.IO[t.Any] | None = None) -> None:
        echo(self.format_message(), file=file, err=True, color=self.ctx.color)


class FileError(ClickException):
    """Raised if a file cannot be opened."""

    ui_filename: t.Final[str]
    filename: t.Final[str]

    def __init__(self, filename: str, hint: str | None = None) -> None:
        if hint is None:
            hint = _("unknown error")

        super().__init__(hint)
        self.ui_filename = format_filename(filename)
        self.filename = filename

    def format_message(self) -> str:
        return _("Could not open file {filename!r}: {message}").format(
            filename=self.ui_filename, message=self.message
        )


class Abort(RuntimeError):
    """An internal signalling exception that signals Click to abort."""


class Exit(RuntimeError):
    """An exception that indicates that the application should exit with some
    status code.

    :param code: the status code to exit with.
    """

    __slots__ = ("exit_code",)

    exit_code: t.Final[int]

    def __init__(self, code: int = 0) -> None:
        self.exit_code = code

from __future__ import annotations

import codecs
import collections.abc as cabc
import io
import os
import re
import sys
import typing as t
from types import TracebackType
from weakref import WeakKeyDictionary

CYGWIN = sys.platform.startswith("cygwin")
WIN = sys.platform.startswith("win")
_ansi_re = re.compile(r"\033\[[;?0-9]*[a-zA-Z]")


def _make_text_stream(
    stream: t.BinaryIO,
    encoding: str | None,
    errors: str | None,
    force_readable: bool = False,
    force_writable: bool = False,
) -> t.TextIO:
    if encoding is None:
        encoding = get_best_encoding(stream)
    if errors is None:
        errors = "replace"
    return _NonClosingTextIOWrapper(
        stream,
        encoding,
        errors,
        line_buffering=True,
        force_readable=force_readable,
        force_writable=force_writable,
    )


def is_ascii_encoding(encoding: str) -> bool:
    """Checks if a given encoding is ascii."""
    try:
        return codecs.lookup(encoding).name == "ascii"
    except LookupError:
        return False


def get_best_encoding(stream: t.IO[t.Any]) -> str:
    """Returns the default stream encoding if not found."""
    rv = getattr(stream, "encoding", None) or sys.getdefaultencoding()
    if is_ascii_encoding(rv):
        return "utf-8"
    return rv


class _NonClosingTextIOWrapper(io.TextIOWrapper):
    def __init__(
        self,
        stream: t.BinaryIO,
        encoding: str | None,
        errors: str | None,
        force_readable: bool = False,
        force_writable: bool = False,
        **extra: t.Any,
    ) -> None:
        self._stream = stream = t.cast(
            t.BinaryIO, _FixupStream(stream, force_readable, force_writable)
        )
        super().__init__(stream, encoding, errors, **extra)

    def __del__(self) -> None:
        try:
            self.detach()
        except Exception:
            pass

    def isatty(self) -> bool:
        # https://bitbucket.org/pypy/pypy/issue/1803
        return self._stream.isatty()


class _FixupStream:
    """The new io interface needs more from streams than streams
    traditionally implement.  As such, this fix-up code is necessary in
    some circumstances.

    The forcing of readable and writable flags are there because some tools
    put badly patched objects on sys (one such offender are certain version
    of jupyter notebook).
    """

    def __init__(
        self,
        stream: t.BinaryIO,
        force_readable: bool = False,
        force_writable: bool = False,
    ):
        self._stream = stream
        self._force_readable = force_readable
        self._force_writable = force_writable

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._stream, name)

    def read1(self, size: int) -> bytes:
        f = getattr(self._stream, "read1", None)

        if f is not None:
            return t.cast(bytes, f(size))

        return self._stream.read(size)

    def readable(self) -> bool:
        if self._force_readable:
            return True
        x = getattr(self._stream, "readable", None)
        if x is not None:
            return t.cast(bool, x())
        try:
            self._stream.read(0)
        except Exception:
            return False
        return True

    def writable(self) -> bool:
        if self._force_writable:
            return True
        x = getattr(self._stream, "writable", None)
        if x is not None:
            return t.cast(bool, x())
        try:
            self._stream.write(b"")
        except Exception:
            try:
                self._stream.write(b"")
            except Exception:
                return False
        return True

    def seekable(self) -> bool:
        x = getattr(self._stream, "seekable", None)
        if x is not None:
            return t.cast(bool, x())
        try:
            self._stream.seek(self._stream.tell())
        except Exception:
            return False
        return True


def _is_binary_reader(stream: t.IO[t.Any], default: bool = False) -> bool:
    try:
        return isinstance(stream.read(0), bytes)
    except Exception:
        return default
        # This happens in some cases where the stream was already
        # closed.  In this case, we assume the default.


def _is_binary_writer(stream: t.IO[t.Any], default: bool = False) -> bool:
    try:
        stream.write(b"")
    except Exception:
        try:
            stream.write("")
            return False
        except Exception:
            pass
        return default
    return True


def _find_binary_reader(stream: t.IO[t.Any]) -> t.BinaryIO | None:
    # We need to figure out if the given stream is already binary.
    # This can happen because the official docs recommend detaching
    # the streams to get binary streams.  Some code might do this, so
    # we need to deal with this case explicitly.
    if _is_binary_reader(stream, False):
        return t.cast(t.BinaryIO, stream)

    buf = getattr(stream, "buffer", None)

    # Same situation here; this time we assume that the buffer is
    # actually binary in case it's closed.
    if buf is not None and _is_binary_reader(buf, True):
        return t.cast(t.BinaryIO, buf)

    return None


def _find_binary_writer(stream: t.IO[t.Any]) -> t.BinaryIO | None:
    # We need to figure out if the given stream is already binary.
    # This can happen because the official docs recommend detaching
    # the streams to get binary streams.  Some code might do this, so
    # we need to deal with this case explicitly.
    if _is_binary_writer(stream, False):
        return t.cast(t.BinaryIO, stream)

    buf = getattr(stream, "buffer", None)

    # Same situation here; this time we assume that the buffer is
    # actually binary in case it's closed.
    if buf is not None and _is_binary_writer(buf, True):
        return t.cast(t.BinaryIO, buf)

    return None


def _stream_is_misconfigured(stream: t.TextIO) -> bool:
    """A stream is misconfigured if its encoding is ASCII."""
    # If the stream does not have an encoding set, we assume it's set
    # to ASCII.  This appears to happen in certain unittest
    # environments.  It's not quite clear what the correct behavior is
    # but this at least will force Click to recover somehow.
    return is_ascii_encoding(getattr(stream, "encoding", None) or "ascii")


def _is_compat_stream_attr(stream: t.TextIO, attr: str, value: str | None) -> bool:
    """A stream attribute is compatible if it is equal to the
    desired value or the desired value is unset and the attribute
    has a value.
    """
    stream_value = getattr(stream, attr, None)
    return stream_value == value or (value is None and stream_value is not None)


def _is_compatible_text_stream(
    stream: t.TextIO, encoding: str | None, errors: str | None
) -> bool:
    """Check if a stream's encoding and errors attributes are
    compatible with the desired values.
    """
    return _is_compat_stream_attr(
        stream, "encoding", encoding
    ) and _is_compat_stream_attr(stream, "errors", errors)


def _force_correct_text_stream(
    text_stream: t.IO[t.Any],
    encoding: str | None,
    errors: str | None,
    is_binary: t.Callable[[t.IO[t.Any], bool], bool],
    find_binary: t.Callable[[t.IO[t.Any]], t.BinaryIO | None],
    force_readable: bool = False,
    force_writable: bool = False,
) -> t.TextIO:
    if is_binary(text_stream, False):
        binary_reader = t.cast(t.BinaryIO, text_stream)
    else:
        text_stream = t.cast(t.TextIO, text_stream)
        # If the stream looks compatible, and won't default to a
        # misconfigured ascii encoding, return it as-is.
        if _is_compatible_text_stream(text_stream, encoding, errors) and not (
            encoding is None and _stream_is_misconfigured(text_stream)
        ):
            return text_stream

        # Otherwise, get the underlying binary reader.
        possible_binary_reader = find_binary(text_stream)

        # If that's not possible, silently use the original reader
        # and get mojibake instead of exceptions.
        if possible_binary_reader is None:
            return text_stream

        binary_reader = possible_binary_reader

    # Default errors to replace instead of strict in order to get
    # something that works.
    if errors is None:
        errors = "replace"

    # Wrap the binary stream in a text stream with the correct
    # encoding parameters.
    return _make_text_stream(
        binary_reader,
        encoding,
        errors,
        force_readable=force_readable,
        force_writable=force_writable,
    )


def _force_correct_text_reader(
    text_reader: t.IO[t.Any],
    encoding: str | None,
    errors: str | None,
    force_readable: bool = False,
) -> t.TextIO:
    return _force_correct_text_stream(
        text_reader,
        encoding,
        errors,
        _is_binary_reader,
        _find_binary_reader,
        force_readable=force_readable,
    )


def _force_correct_text_writer(
    text_writer: t.IO[t.Any],
    encoding: str | None,
    errors: str | None,
    force_writable: bool = False,
) -> t.TextIO:
    return _force_correct_text_stream(
        text_writer,
        encoding,
        errors,
        _is_binary_writer,
        _find_binary_writer,
        force_writable=force_writable,
    )


def get_binary_stdin() -> t.BinaryIO:
    reader = _find_binary_reader(sys.stdin)
    if reader is None:
        raise RuntimeError("Was not able to determine binary stream for sys.stdin.")
    return reader


def get_binary_stdout() -> t.BinaryIO:
    writer = _find_binary_writer(sys.stdout)
    if writer is None:
        raise RuntimeError("Was not able to determine binary stream for sys.stdout.")
    return writer


def get_binary_stderr() -> t.BinaryIO:
    writer = _find_binary_writer(sys.stderr)
    if writer is None:
        raise RuntimeError("Was not able to determine binary stream for sys.stderr.")
    return writer


def get_text_stdin(encoding: str | None = None, errors: str | None = None) -> t.TextIO:
    rv = _get_windows_console_stream(sys.stdin, encoding, errors)
    if rv is not None:
        return rv
    return _force_correct_text_reader(sys.stdin, encoding, errors, force_readable=True)


def get_text_stdout(encoding: str | None = None, errors: str | None = None) -> t.TextIO:
    rv = _get_windows_console_stream(sys.stdout, encoding, errors)
    if rv is not None:
        return rv
    return _force_correct_text_writer(sys.stdout, encoding, errors, force_writable=True)


def get_text_stderr(encoding: str | None = None, errors: str | None = None) -> t.TextIO:
    rv = _get_windows_console_stream(sys.stderr, encoding, errors)
    if rv is not None:
        return rv
    return _force_correct_text_writer(sys.stderr, encoding, errors, force_writable=True)


def _wrap_io_open(
    file: str | os.PathLike[str] | int,
    mode: str,
    encoding: str | None,
    errors: str | None,
) -> t.IO[t.Any]:
    """Handles not passing ``encoding`` and ``errors`` in binary mode."""
    if "b" in mode:
        return open(file, mode)

    return open(file, mode, encoding=encoding, errors=errors)


def open_stream(
    filename: str | os.PathLike[str],
    mode: str = "r",
    encoding: str | None = None,
    errors: str | None = "strict",
    atomic: bool = False,
) -> tuple[t.IO[t.Any], bool]:
    binary = "b" in mode
    filename = os.fspath(filename)

    # Standard streams first. These are simple because they ignore the
    # atomic flag. Use fsdecode to handle Path("-").
    if os.fsdecode(filename) == "-":
        if any(m in mode for m in ["w", "a", "x"]):
            if binary:
                return get_binary_stdout(), False
            return get_text_stdout(encoding=encoding, errors=errors), False
        if binary:
            return get_binary_stdin(), False
        return get_text_stdin(encoding=encoding, errors=errors), False

    # Non-atomic writes directly go out through the regular open functions.
    if not atomic:
        return _wrap_io_open(filename, mode, encoding, errors), True

    # Some usability stuff for atomic writes
    if "a" in mode:
        raise ValueError(
            "Appending to an existing file is not supported, because that"
            " would involve an expensive `copy`-operation to a temporary"
            " file. Open the file in normal `w`-mode and copy explicitly"
            " if that's what you're after."
        )
    if "x" in mode:
        raise ValueError("Use the `overwrite`-parameter instead.")
    if "w" not in mode:
        raise ValueError("Atomic writes only make sense with `w`-mode.")

    # Atomic writes are more complicated.  They work by opening a file
    # as a proxy in the same folder and then using the fdopen
    # functionality to wrap it in a Python file.  Then we wrap it in an
    # atomic file that moves the file over on close.
    import errno
    import random

    try:
        perm: int | None = os.stat(filename).st_mode
    except OSError:
        perm = None

    flags = os.O_RDWR | os.O_CREAT | os.O_EXCL

    if binary:
        flags |= getattr(os, "O_BINARY", 0)

    while True:
        tmp_filename = os.path.join(
            os.path.dirname(filename),
            f".__atomic-write{random.randrange(1 << 32):08x}",
        )
        try:
            fd = os.open(tmp_filename, flags, 0o666 if perm is None else perm)
            break
        except OSError as e:
            if e.errno == errno.EEXIST or (
                os.name == "nt"
                and e.errno == errno.EACCES
                and os.path.isdir(e.filename)
                and os.access(e.filename, os.W_OK)
            ):
                continue
            raise

    if perm is not None:
        os.chmod(tmp_filename, perm)  # in case perm includes bits in umask

    f = _wrap_io_open(fd, mode, encoding, errors)
    af = _AtomicFile(f, tmp_filename, os.path.realpath(filename))
    return t.cast(t.IO[t.Any], af), True


class _AtomicFile:
    def __init__(self, f: t.IO[t.Any], tmp_filename: str, real_filename: str) -> None:
        self._f = f
        self._tmp_filename = tmp_filename
        self._real_filename = real_filename
        self.closed = False

    @property
    def name(self) -> str:
        return self._real_filename

    def close(self, delete: bool = False) -> None:
        if self.closed:
            return
        self._f.close()
        os.replace(self._tmp_filename, self._real_filename)
        self.closed = True

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._f, name)

    def __enter__(self) -> _AtomicFile:
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc_value: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.close(delete=exc_type is not None)

    def __repr__(self) -> str:
        return repr(self._f)


def strip_ansi(value: str) -> str:
    return _ansi_re.sub("", value)


def _is_jupyter_kernel_output(stream: t.IO[t.Any]) -> bool:
    while isinstance(stream, (_FixupStream, _NonClosingTextIOWrapper)):
        stream = stream._stream

    return stream.__class__.__module__.startswith("ipykernel.")


def should_strip_ansi(
    stream: t.IO[t.Any] | None = None, color: bool | None = None
) -> bool:
    if color is None:
        if stream is None:
            stream = sys.stdin
        elif hasattr(stream, "color"):
            # ._termui_impl.MaybeStripAnsi handles stripping ansi itself,
            # so we don't need to strip it here
            return False
        return not isatty(stream) and not _is_jupyter_kernel_output(stream)
    return not color


# double check is needed so mypy does not analyze this on Linux
if sys.platform.startswith("win") and WIN:
    from ._winconsole import _get_windows_console_stream

    def _get_argv_encoding() -> str:
        import locale

        return locale.getpreferredencoding()

else:

    def _get_argv_encoding() -> str:
        return getattr(sys.stdin, "encoding", None) or sys.getfilesystemencoding()

    def _get_windows_console_stream(
        f: t.TextIO, encoding: str | None, errors: str | None
    ) -> t.TextIO | None:
        return None


def term_len(x: str) -> int:
    return len(strip_ansi(x))


def isatty(stream: t.IO[t.Any]) -> bool:
    try:
        return stream.isatty()
    except Exception:
        return False


def _make_cached_stream_func(
    src_func: t.Callable[[], t.TextIO | None],
    wrapper_func: t.Callable[[], t.TextIO],
) -> t.Callable[[], t.TextIO | None]:
    cache: cabc.MutableMapping[t.TextIO, t.TextIO] = WeakKeyDictionary()

    def func() -> t.TextIO | None:
        stream = src_func()

        if stream is None:
            return None

        try:
            rv = cache.get(stream)
        except Exception:
            rv = None
        if rv is not None:
            return rv
        rv = wrapper_func()
        try:
            cache[stream] = rv
        except Exception:
            pass
        return rv

    return func


_default_text_stdin = _make_cached_stream_func(lambda: sys.stdin, get_text_stdin)
_default_text_stdout = _make_cached_stream_func(lambda: sys.stdout, get_text_stdout)
_default_text_stderr = _make_cached_stream_func(lambda: sys.stderr, get_text_stderr)


binary_streams: cabc.Mapping[str, t.Callable[[], t.BinaryIO]] = {
    "stdin": get_binary_stdin,
    "stdout": get_binary_stdout,
    "stderr": get_binary_stderr,
}

text_streams: cabc.Mapping[str, t.Callable[[str | None, str | None], t.TextIO]] = {
    "stdin": get_text_stdin,
    "stdout": get_text_stdout,
    "stderr": get_text_stderr,
}

import * as babel from '@babel/core'
import type { Plugin } from 'esbuild'
import { getBuildExtensions } from 'esbuild-extra'
import type { Options } from 'tsup'
import { defineConfig } from 'tsup'
import type { MangleErrorsPluginOptions } from './scripts/mangleErrors.mjs'
import { mangleErrorsPlugin } from './scripts/mangleErrors.mjs'

const tsconfig = 'tsconfig.build.json' satisfies Options['tsconfig']

// Extract error strings, replace them with error codes, and write messages to a file
const mangleErrorsTransform: Plugin = {
  name: mangleErrorsPlugin.name,
  setup(build) {
    const { onTransform } = getBuildExtensions(build, mangleErrorsPlugin.name)

    onTransform({ loaders: ['ts', 'tsx'] }, async args => {
      try {
        const res = await babel.transformAsync(args.code, {
          parserOpts: {
            plugins: ['typescript']
          },
          plugins: [
            [
              mangleErrorsPlugin,
              { minify: false } satisfies MangleErrorsPluginOptions
            ]
          ]
        })

        if (res == null) {
          throw new Error('Babel transformAsync returned null')
        }

        return {
          code: res.code!,
          map: res.map!
        }
      } catch (err) {
        console.error('Babel mangleErrors error: ', err)
        return null
      }
    })
  }
}

export default defineConfig((options): Options[] => {
  const commonOptions: Options = {
    entry: {
      redux: 'src/index.ts'
    },
    esbuildPlugins: [mangleErrorsTransform],
    sourcemap: true,
    tsconfig,
    ...options
  }

  return [
    // Standard ESM, embedded `process.env.NODE_ENV` checks
    {
      ...commonOptions,
      format: ['esm'],
      outExtension: () => ({ js: '.mjs' }), // Add dts: '.d.ts' when egoist/tsup#1053 lands
      dts: true,
      clean: true
    },
    // Support Webpack 4 by pointing `"module"` to a file with a `.js` extension
    {
      ...commonOptions,
      format: ['esm'],
      target: ['es2017'],
      dts: false,
      outExtension: () => ({ js: '.js' }),
      entry: { 'redux.legacy-esm': 'src/index.ts' }
    },
    // Browser-ready ESM, production + minified
    {
      ...commonOptions,
      entry: {
        'redux.browser': 'src/index.ts'
      },
      define: {
        'process.env.NODE_ENV': JSON.stringify('production')
      },
      format: ['esm'],
      outExtension: () => ({ js: '.mjs' }),
      minify: true
    },
    {
      ...commonOptions,
      format: ['cjs'],
      outDir: './dist/cjs/',
      outExtension: () => ({ js: '.cjs' })
    }
  ]
})

import type { StoreEnhancer, Action, Store, Reducer } from 'redux'
import { createStore, combineReducers } from 'redux'
import { vi } from 'vitest'
import {
  addTodo,
  dispatchInMiddle,
  getStateInMiddle,
  subscribeInMiddle,
  unsubscribeInMiddle,
  throwError,
  unknownAction
} from './helpers/actionCreators'
import * as reducers from './helpers/reducers'
import type { ObservableInput } from 'rxjs'
import { from } from 'rxjs'
import { map } from 'rxjs/operators'
import $$observable from '../src/utils/symbol-observable'

describe('createStore', () => {
  it('exposes the public API', () => {
    const store = createStore(combineReducers(reducers))

    // Since switching to internal Symbol.observable impl, it will show up as a key in node env
    // So we filter it out
    const methods = Object.keys(store).filter(key => key !== $$observable)

    expect(methods.length).toBe(4)
    expect(methods).toContain('subscribe')
    expect(methods).toContain('dispatch')
    expect(methods).toContain('getState')
    expect(methods).toContain('replaceReducer')
  })

  it('throws if reducer is not a function', () => {
    // @ts-expect-error
    expect(() => createStore(undefined)).toThrow()
    // @ts-expect-error
    expect(() => createStore('test')).toThrow()
    // @ts-expect-error
    expect(() => createStore({})).toThrow()

    expect(() => createStore(() => {})).not.toThrow()
  })

  it('passes the initial state', () => {
    const store = createStore(reducers.todos, [
      {
        id: 1,
        text: 'Hello'
      }
    ])
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])
  })

  it('applies the reducer to the previous state', () => {
    const store = createStore(reducers.todos)
    expect(store.getState()).toEqual([])

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(store.getState()).toEqual([])

    store.dispatch(addTodo('Hello'))
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])

    store.dispatch(addTodo('World'))
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])
  })

  it('applies the reducer to the initial state', () => {
    const store = createStore(reducers.todos, [
      {
        id: 1,
        text: 'Hello'
      }
    ])
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])

    store.dispatch(addTodo('World'))
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])
  })

  it('preserves the state when replacing a reducer', () => {
    const store = createStore(reducers.todos)
    store.dispatch(addTodo('Hello'))
    store.dispatch(addTodo('World'))
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])

    store.replaceReducer(reducers.todosReverse)
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])

    store.dispatch(addTodo('Perhaps'))
    expect(store.getState()).toEqual([
      {
        id: 3,
        text: 'Perhaps'
      },
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])

    store.replaceReducer(reducers.todos)
    expect(store.getState()).toEqual([
      {
        id: 3,
        text: 'Perhaps'
      },
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])

    store.dispatch(addTodo('Surely'))
    expect(store.getState()).toEqual([
      {
        id: 3,
        text: 'Perhaps'
      },
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      },
      {
        id: 4,
        text: 'Surely'
      }
    ])
  })

  it('supports multiple subscriptions', () => {
    const store = createStore(reducers.todos)
    const listenerA = vi.fn()
    const listenerB = vi.fn()

    let unsubscribeA = store.subscribe(listenerA)
    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(1)
    expect(listenerB.mock.calls.length).toBe(0)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(2)
    expect(listenerB.mock.calls.length).toBe(0)

    const unsubscribeB = store.subscribe(listenerB)
    expect(listenerA.mock.calls.length).toBe(2)
    expect(listenerB.mock.calls.length).toBe(0)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(1)

    unsubscribeA()
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(1)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(2)

    unsubscribeB()
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(2)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(2)

    unsubscribeA = store.subscribe(listenerA)
    expect(listenerA.mock.calls.length).toBe(3)
    expect(listenerB.mock.calls.length).toBe(2)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(4)
    expect(listenerB.mock.calls.length).toBe(2)
  })

  it('only removes listener once when unsubscribe is called', () => {
    const store = createStore(reducers.todos)
    const listenerA = vi.fn()
    const listenerB = vi.fn()

    const unsubscribeA = store.subscribe(listenerA)
    store.subscribe(listenerB)

    unsubscribeA()
    unsubscribeA()

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listenerA.mock.calls.length).toBe(0)
    expect(listenerB.mock.calls.length).toBe(1)
  })

  it('only removes relevant listener when unsubscribe is called', () => {
    const store = createStore(reducers.todos)
    const listener = vi.fn()

    store.subscribe(listener)
    const unsubscribeSecond = store.subscribe(listener)

    unsubscribeSecond()
    unsubscribeSecond()

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener.mock.calls.length).toBe(1)
  })

  it('supports removing a subscription within a subscription', () => {
    const store = createStore(reducers.todos)
    const listenerA = vi.fn()
    const listenerB = vi.fn()
    const listenerC = vi.fn()

    store.subscribe(listenerA)
    const unSubB = store.subscribe(() => {
      listenerB()
      unSubB()
    })
    store.subscribe(listenerC)

    // @ts-expect-error
    store.dispatch(unknownAction())
    // @ts-expect-error
    store.dispatch(unknownAction())

    expect(listenerA.mock.calls.length).toBe(2)
    expect(listenerB.mock.calls.length).toBe(1)
    expect(listenerC.mock.calls.length).toBe(2)
  })

  it('notifies all subscribers about current dispatch regardless if any of them gets unsubscribed in the process', () => {
    const store = createStore(reducers.todos)

    const unsubscribeHandles: any[] = []
    const doUnsubscribeAll = () =>
      unsubscribeHandles.forEach(unsubscribe => unsubscribe())

    const listener1 = vi.fn()
    const listener2 = vi.fn()
    const listener3 = vi.fn()

    unsubscribeHandles.push(store.subscribe(() => listener1()))
    unsubscribeHandles.push(
      store.subscribe(() => {
        listener2()
        doUnsubscribeAll()
      })
    )
    unsubscribeHandles.push(store.subscribe(() => listener3()))

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(1)
    expect(listener2.mock.calls.length).toBe(1)
    expect(listener3.mock.calls.length).toBe(1)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(1)
    expect(listener2.mock.calls.length).toBe(1)
    expect(listener3.mock.calls.length).toBe(1)
  })

  it('notifies only subscribers active at the moment of current dispatch', () => {
    const store = createStore(reducers.todos)

    const listener1 = vi.fn()
    const listener2 = vi.fn()
    const listener3 = vi.fn()

    let listener3Added = false
    const maybeAddThirdListener = () => {
      if (!listener3Added) {
        listener3Added = true
        store.subscribe(() => listener3())
      }
    }

    store.subscribe(() => listener1())
    store.subscribe(() => {
      listener2()
      maybeAddThirdListener()
    })

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(1)
    expect(listener2.mock.calls.length).toBe(1)
    expect(listener3.mock.calls.length).toBe(0)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(2)
    expect(listener2.mock.calls.length).toBe(2)
    expect(listener3.mock.calls.length).toBe(1)
  })

  it('uses the last snapshot of subscribers during nested dispatch', () => {
    const store = createStore(reducers.todos)

    const listener1 = vi.fn()
    const listener2 = vi.fn()
    const listener3 = vi.fn()
    const listener4 = vi.fn()

    let unsubscribe4: any
    const unsubscribe1 = store.subscribe(() => {
      listener1()
      expect(listener1.mock.calls.length).toBe(1)
      expect(listener2.mock.calls.length).toBe(0)
      expect(listener3.mock.calls.length).toBe(0)
      expect(listener4.mock.calls.length).toBe(0)

      unsubscribe1()
      unsubscribe4 = store.subscribe(listener4)
      // @ts-expect-error
      store.dispatch(unknownAction())

      expect(listener1.mock.calls.length).toBe(1)
      expect(listener2.mock.calls.length).toBe(1)
      expect(listener3.mock.calls.length).toBe(1)
      expect(listener4.mock.calls.length).toBe(1)
    })
    store.subscribe(listener2)
    store.subscribe(listener3)

    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(1)
    expect(listener2.mock.calls.length).toBe(2)
    expect(listener3.mock.calls.length).toBe(2)
    expect(listener4.mock.calls.length).toBe(1)

    unsubscribe4()
    // @ts-expect-error
    store.dispatch(unknownAction())
    expect(listener1.mock.calls.length).toBe(1)
    expect(listener2.mock.calls.length).toBe(3)
    expect(listener3.mock.calls.length).toBe(3)
    expect(listener4.mock.calls.length).toBe(1)
  })

  it('provides an up-to-date state when a subscriber is notified', async () => {
    const store = createStore(reducers.todos)

    let resolve: (value: unknown) => void = () => {}
    let promise = new Promise(_resolve => {
      resolve = _resolve
    })
    store.subscribe(() => {
      resolve(store.getState())
    })
    store.dispatch(addTodo('Hello'))
    const state = await promise

    expect(state).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])
  })

  it('does not leak private listeners array', async () => {
    const store = createStore(reducers.todos)
    let resolve: (value: unknown) => void = () => {}
    let promise = new Promise(_resolve => {
      resolve = _resolve
    })

    store.subscribe(function (this: any) {
      resolve(this)
    })
    store.dispatch(addTodo('Hello'))
    const result = await promise

    expect(result).toBe(undefined)
  })

  it('only accepts plain object actions', () => {
    const store = createStore(reducers.todos)
    // @ts-expect-error
    expect(() => store.dispatch(unknownAction())).not.toThrow()

    function AwesomeMap() {}
    // @ts-expect-error
    ;[null, undefined, 42, 'hey', new AwesomeMap()].forEach(nonObject =>
      expect(() => store.dispatch(nonObject)).toThrow(/plain/)
    )
  })

  it('handles nested dispatches gracefully', () => {
    function foo(state = 0, action: Action) {
      return action.type === 'foo' ? 1 : state
    }

    function bar(state = 0, action: Action) {
      return action.type === 'bar' ? 2 : state
    }

    const store = createStore(combineReducers({ foo, bar }))

    store.subscribe(function kindaComponentDidUpdate() {
      const state = store.getState()
      if (state.bar === 0) {
        store.dispatch({ type: 'bar' })
      }
    })

    store.dispatch({ type: 'foo' })
    expect(store.getState()).toEqual({
      foo: 1,
      bar: 2
    })
  })

  it('does not allow dispatch() from within a reducer', () => {
    const store = createStore(reducers.dispatchInTheMiddleOfReducer)

    expect(() =>
      store.dispatch(
        // @ts-expect-error
        dispatchInMiddle(store.dispatch.bind(store, unknownAction()))
      )
    ).toThrow(/may not dispatch/)

    expect(() => store.dispatch(dispatchInMiddle(() => {}))).not.toThrow()
  })

  it('does not allow getState() from within a reducer', () => {
    const store = createStore(reducers.getStateInTheMiddleOfReducer)

    expect(() =>
      store.dispatch(getStateInMiddle(store.getState.bind(store)))
    ).toThrow(/You may not call store.getState()/)

    expect(() => store.dispatch(getStateInMiddle(() => {}))).not.toThrow()
  })

  it('does not allow subscribe() from within a reducer', () => {
    const store = createStore(reducers.subscribeInTheMiddleOfReducer)

    expect(() =>
      store.dispatch(subscribeInMiddle(store.subscribe.bind(store, () => {})))
    ).toThrow(/You may not call store.subscribe()/)

    expect(() => store.dispatch(subscribeInMiddle(() => {}))).not.toThrow()
  })

  it('does not allow unsubscribe from subscribe() from within a reducer', () => {
    const store = createStore(reducers.unsubscribeInTheMiddleOfReducer)
    const unsubscribe = store.subscribe(() => {})

    expect(() =>
      store.dispatch(unsubscribeInMiddle(unsubscribe.bind(store)))
    ).toThrow(/You may not unsubscribe from a store/)

    expect(() => store.dispatch(unsubscribeInMiddle(() => {}))).not.toThrow()
  })

  it('recovers from an error within a reducer', () => {
    const store = createStore(reducers.errorThrowingReducer)
    expect(() => store.dispatch(throwError())).toThrow()

    // @ts-expect-error
    expect(() => store.dispatch(unknownAction())).not.toThrow()
  })

  it('throws if action type is missing', () => {
    const store = createStore(reducers.todos)
    // @ts-expect-error
    expect(() => store.dispatch({})).toThrow(
      /Actions may not have an undefined "type" property/
    )
  })

  it('throws an error that correctly describes the type of item dispatched', () => {
    const store = createStore(reducers.todos)
    // @ts-ignore
    expect(() => store.dispatch(Promise.resolve(42))).toThrow(
      /the actual type was: 'Promise'/
    )

    // @ts-ignore
    expect(() => store.dispatch(() => {})).toThrow(
      /the actual type was: 'function'/
    )

    // @ts-ignore
    expect(() => store.dispatch(new Date())).toThrow(
      /the actual type was: 'date'/
    )

    // @ts-ignore
    expect(() => store.dispatch(null)).toThrow(/the actual type was: 'null'/)

    // @ts-ignore
    expect(() => store.dispatch(undefined)).toThrow(
      /the actual type was: 'undefined'/
    )
  })

  it('throws if action type is undefined', () => {
    const store = createStore(reducers.todos)
    // @ts-expect-error
    expect(() => store.dispatch({ type: undefined })).toThrow(
      /Actions may not have an undefined "type" property/
    )
  })

  it('throws if action type is not string', () => {
    const store = createStore(reducers.todos)
    // @ts-expect-error
    expect(() => store.dispatch({ type: false })).toThrow(
      /the actual type was: 'boolean'.*Value was: 'false'/
    )
    // @ts-expect-error
    expect(() => store.dispatch({ type: 0 })).toThrow(
      /the actual type was: 'number'.*Value was: '0'/
    )
    // @ts-expect-error
    expect(() => store.dispatch({ type: null })).toThrow(
      /the actual type was: 'null'.*Value was: 'null'/
    )
    // @ts-expect-error
    expect(() => store.dispatch({ type: '' })).not.toThrow()
  })

  it('accepts enhancer as the third argument', () => {
    const emptyArray: any[] = []
    const spyEnhancer =
      (vanillaCreateStore: any) =>
      (...args: any[]) => {
        expect(args[0]).toBe(reducers.todos)
        expect(args[1]).toBe(emptyArray)
        expect(args.length).toBe(2)
        const vanillaStore = vanillaCreateStore(...args)
        return {
          ...vanillaStore,
          dispatch: vi.fn(vanillaStore.dispatch)
        }
      }

    const store = createStore(reducers.todos, emptyArray, spyEnhancer)
    const action = addTodo('Hello')
    store.dispatch(action)
    expect(store.dispatch).toBeCalledWith(action)
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])
  })

  it('accepts enhancer as the second argument if initial state is missing', () => {
    const spyEnhancer =
      (vanillaCreateStore: any) =>
      (...args: any[]) => {
        expect(args[0]).toBe(reducers.todos)
        expect(args[1]).toBe(undefined)
        expect(args.length).toBe(2)
        const vanillaStore = vanillaCreateStore(...args)
        return {
          ...vanillaStore,
          dispatch: vi.fn(vanillaStore.dispatch)
        }
      }

    const store = createStore(reducers.todos, spyEnhancer)
    const action = addTodo('Hello')
    store.dispatch(action)
    expect(store.dispatch).toBeCalledWith(action)
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])
  })

  it('throws if enhancer is neither undefined nor a function', () => {
    expect(() =>
      createStore(reducers.todos, undefined, {} as unknown as StoreEnhancer)
    ).toThrow()

    expect(() =>
      createStore(reducers.todos, undefined, [] as unknown as StoreEnhancer)
    ).toThrow()

    // @ts-expect-error
    expect(() => createStore(reducers.todos, undefined, null)).toThrow()

    expect(() =>
      createStore(reducers.todos, undefined, false as unknown as StoreEnhancer)
    ).toThrow()

    expect(() =>
      createStore(reducers.todos, undefined, undefined)
    ).not.toThrow()

    expect(() => createStore(reducers.todos, undefined, x => x)).not.toThrow()

    expect(() =>
      createStore<any, reducers.TodoAction, {}, {}>(reducers.todos, x => x)
    ).not.toThrow()

    expect(() => createStore(reducers.todos, [])).not.toThrow()

    expect(() =>
      createStore<any, reducers.TodoAction, {}, {}>(reducers.todos, {})
    ).not.toThrow()
  })

  it('throws if nextReducer is not a function', () => {
    const store = createStore(reducers.todos)

    // @ts-expect-error
    expect(() => store.replaceReducer(undefined)).toThrow(
      'Expected the nextReducer to be a function.'
    )

    expect(() => store.replaceReducer(() => [])).not.toThrow()
  })

  it('throws if listener is not a function', () => {
    const store = createStore(reducers.todos)
    // @ts-expect-error
    expect(() => store.subscribe(undefined)).toThrow()
    // @ts-expect-error
    expect(() => store.subscribe('')).toThrow()
    // @ts-expect-error
    expect(() => store.subscribe(null)).toThrow()
    // @ts-expect-error
    expect(() => store.subscribe(undefined)).toThrow()
  })

  describe('Symbol.observable interop point', () => {
    it('should exist', () => {
      const store = createStore(() => {})
      // @ts-expect-error
      expect(typeof store[$$observable]).toBe('function')
    })

    describe('returned value', () => {
      it('should be subscribable', () => {
        const store = createStore(() => {})
        // @ts-expect-error
        const obs = store[$$observable]()
        expect(typeof obs.subscribe).toBe('function')
      })

      it('may be used to retrieve itself', () => {
        const store = createStore(() => {})
        // @ts-expect-error
        const obs = store[$$observable]()
        expect(obs[$$observable]()).toBe(obs)
      })

      it('should throw a TypeError if an observer object is not supplied to subscribe', () => {
        const store = createStore(() => {})
        // @ts-expect-error
        const obs = store[$$observable]()

        expect(function () {
          obs.subscribe()
        }).toThrowError(
          new TypeError(
            `Expected the observer to be an object. Instead, received: 'undefined'`
          )
        )

        expect(function () {
          obs.subscribe(null)
        }).toThrowError(
          new TypeError(
            `Expected the observer to be an object. Instead, received: 'null'`
          )
        )

        expect(function () {
          obs.subscribe(() => {})
        }).toThrowError(
          new TypeError(
            `Expected the observer to be an object. Instead, received: 'function'`
          )
        )

        expect(function () {
          obs.subscribe({})
        }).not.toThrow()
      })

      it('should return a subscription object when subscribed', () => {
        const store = createStore(() => {})
        // @ts-expect-error
        const obs = store[$$observable]()
        const sub = obs.subscribe({})
        expect(typeof sub.unsubscribe).toBe('function')
      })
    })

    it('should pass an integration test with no unsubscribe', () => {
      function foo(state = 0, action: Action) {
        return action.type === 'foo' ? 1 : state
      }

      function bar(state = 0, action: Action) {
        return action.type === 'bar' ? 2 : state
      }

      const store = createStore(combineReducers({ foo, bar }))
      // @ts-expect-error
      const observable = store[$$observable]()
      const results: any[] = []

      observable.subscribe({
        next(state: any) {
          results.push(state)
        }
      })

      store.dispatch({ type: 'foo' })
      store.dispatch({ type: 'bar' })

      expect(results).toEqual([
        { foo: 0, bar: 0 },
        { foo: 1, bar: 0 },
        { foo: 1, bar: 2 }
      ])
    })

    it('should pass an integration test with an unsubscribe', () => {
      function foo(state = 0, action: Action) {
        return action.type === 'foo' ? 1 : state
      }

      function bar(state = 0, action: Action) {
        return action.type === 'bar' ? 2 : state
      }

      const store = createStore(combineReducers({ foo, bar }))
      // @ts-expect-error
      const observable = store[$$observable]()
      const results: any[] = []

      const sub = observable.subscribe({
        next(state: any) {
          results.push(state)
        }
      })

      store.dispatch({ type: 'foo' })
      sub.unsubscribe()
      store.dispatch({ type: 'bar' })

      expect(results).toEqual([
        { foo: 0, bar: 0 },
        { foo: 1, bar: 0 }
      ])
    })

    it('should pass an integration test with a common library (RxJS)', () => {
      function foo(state = 0, action: Action) {
        return action.type === 'foo' ? 1 : state
      }

      function bar(state = 0, action: Action) {
        return action.type === 'bar' ? 2 : state
      }

      const store: ObservableInput<{ foo: number; bar: number }> = createStore(
        combineReducers({ foo, bar })
      )
      const observable = from(store)
      const results: any[] = []

      const sub = observable
        .pipe(map(state => ({ fromRx: true, ...state })))
        .subscribe(state => results.push(state))
      ;(store as unknown as Store).dispatch({ type: 'foo' })
      sub.unsubscribe()
      ;(store as unknown as Store).dispatch({ type: 'bar' })

      expect(results).toEqual([
        { foo: 0, bar: 0, fromRx: true },
        { foo: 1, bar: 0, fromRx: true }
      ])
    })
  })

  it('does not log an error if parts of the current state will be ignored by a nextReducer using combineReducers', () => {
    const originalConsoleError = console.error
    console.error = vi.fn()

    const reducer: Reducer<number> = (s = 0) => s

    const yReducer = combineReducers<{
      z: typeof reducer
      w?: typeof reducer
    }>({
      z: reducer,
      w: reducer
    })

    const store = createStore(
      combineReducers<{ x?: typeof reducer; y: typeof yReducer }>({
        x: reducer,
        y: yReducer
      })
    )

    store.replaceReducer(
      combineReducers({
        y: combineReducers({
          z: reducer
        })
      })
    )

    expect((console.error as any).mock.calls.length).toBe(0)
    console.error = originalConsoleError
  })

  it('throws if passing several enhancer functions without preloaded state', () => {
    const rootReducer = combineReducers(reducers)
    const dummyEnhancer = (f: any) => f
    expect(() =>
      // use a fake pre-loaded state to get a valid createStore signature
      createStore(rootReducer, dummyEnhancer as unknown as {}, dummyEnhancer)
    ).toThrow()
  })

  it('throws if passing several enhancer functions with preloaded state', () => {
    const rootReducer = combineReducers(reducers)
    const dummyEnhancer = (f: any) => f
    expect(() =>
      // work around the type so we can call this poorly
      (createStore as any)(
        rootReducer,
        { todos: [] },
        dummyEnhancer,
        dummyEnhancer
      )
    ).toThrow()
  })
})

import { bindActionCreators, createStore } from '../src'
import type { ActionCreator, Store } from '../src'
import { todos } from './helpers/reducers'
import * as actionCreators from './helpers/actionCreators'

describe('bindActionCreators', () => {
  let store: Store
  let actionCreatorFunctions: any

  beforeEach(() => {
    store = createStore(todos)
    actionCreatorFunctions = { ...actionCreators }
    Object.keys(actionCreatorFunctions).forEach(key => {
      if (typeof actionCreatorFunctions[key] !== 'function') {
        delete actionCreatorFunctions[key]
      }
    })
  })

  it('wraps the action creators with the dispatch function', () => {
    const boundActionCreators = bindActionCreators(
      actionCreators,
      store.dispatch
    )
    expect(Object.keys(boundActionCreators)).toEqual(
      Object.keys(actionCreatorFunctions)
    )

    const action = boundActionCreators.addTodo('Hello')
    expect(action).toEqual(actionCreators.addTodo('Hello'))
    expect(store.getState()).toEqual([{ id: 1, text: 'Hello' }])
  })

  it('wraps action creators transparently', () => {
    const uniqueThis = {}
    const argArray = [1, 2, 3]
    function actionCreator(this: any) {
      return { type: 'UNKNOWN_ACTION', this: this, args: [...arguments] }
    }
    const boundActionCreator = bindActionCreators(actionCreator, store.dispatch)

    const boundAction = boundActionCreator.apply(uniqueThis, argArray as [])
    const action = actionCreator.apply(uniqueThis, argArray as [])
    expect(boundAction).toEqual(action)
    expect(boundAction.this).toBe(uniqueThis)
    expect(action.this).toBe(uniqueThis)
  })

  it('skips non-function values in the passed object', () => {
    // as this is testing against invalid values, we will cast to unknown and then back to ActionCreator<any>
    // in a typescript environment this test is unnecessary, but required in javascript
    const boundActionCreators = bindActionCreators(
      {
        ...actionCreators,
        foo: 42,
        bar: 'baz',
        wow: undefined,
        much: {},
        test: null
      } as unknown as ActionCreator<any>,
      store.dispatch
    )
    expect(Object.keys(boundActionCreators)).toEqual(
      Object.keys(actionCreatorFunctions)
    )
  })

  it('supports wrapping a single function only', () => {
    const actionCreator = actionCreators.addTodo
    const boundActionCreator = bindActionCreators(actionCreator, store.dispatch)

    const action = boundActionCreator('Hello')
    expect(action).toEqual(actionCreator('Hello'))
    expect(store.getState()).toEqual([{ id: 1, text: 'Hello' }])
  })

  it('throws for an undefined actionCreator', () => {
    expect(() => {
      // @ts-expect-error
      bindActionCreators(undefined, store.dispatch)
    }).toThrow(
      `bindActionCreators expected an object or a function, but instead received: 'undefined'. ` +
        `Did you write "import ActionCreators from" instead of "import * as ActionCreators from"?`
    )
  })

  it('throws for a null actionCreator', () => {
    expect(() => {
      // @ts-expect-error
      bindActionCreators(null, store.dispatch)
    }).toThrow(
      `bindActionCreators expected an object or a function, but instead received: 'null'. ` +
        `Did you write "import ActionCreators from" instead of "import * as ActionCreators from"?`
    )
  })

  it('throws for a primitive actionCreator', () => {
    expect(() => {
      bindActionCreators(
        'string' as unknown as ActionCreator<any>,
        store.dispatch
      )
    }).toThrow(
      `bindActionCreators expected an object or a function, but instead received: 'string'. ` +
        `Did you write "import ActionCreators from" instead of "import * as ActionCreators from"?`
    )
  })
})

/* eslint-disable no-console */
import type { Reducer, Action } from 'redux'
import {
  createStore,
  combineReducers,
  __DO_NOT_USE__ActionTypes as ActionTypes
} from 'redux'
import { vi } from 'vitest'

describe('Utils', () => {
  describe('combineReducers', () => {
    it('returns a composite reducer that maps the state keys to given reducers', () => {
      type IncrementAction = { type: 'increment' }
      type PushAction = { type: 'push'; value: unknown }

      const reducer = combineReducers({
        counter: (state: number = 0, action: IncrementAction) =>
          action.type === 'increment' ? state + 1 : state,
        stack: (state: any[] = [], action: PushAction) =>
          action.type === 'push' ? [...state, action.value] : state
      })

      const s1 = reducer(undefined, { type: 'increment' })
      expect(s1).toEqual({ counter: 1, stack: [] })
      const s2 = reducer(s1, { type: 'push', value: 'a' })
      expect(s2).toEqual({ counter: 1, stack: ['a'] })
    })

    it('ignores all props which are not a function', () => {
      // we double-cast because these conditions can only happen in a javascript setting
      const reducer = combineReducers({
        fake: true as unknown as Reducer,
        broken: 'string' as unknown as Reducer,
        another: { nested: 'object' } as unknown as Reducer,
        stack: (state = []) => state
      })

      expect(Object.keys(reducer(undefined, { type: 'push' }))).toEqual([
        'stack'
      ])
    })

    it('warns if a reducer prop is undefined', () => {
      const preSpy = console.error
      const spy = vi.fn()
      console.error = spy

      let isNotDefined: any
      combineReducers({ isNotDefined })
      expect(spy.mock.calls[0][0]).toMatch(
        /No reducer provided for key "isNotDefined"/
      )

      spy.mockClear()
      combineReducers({ thing: undefined })
      expect(spy.mock.calls[0][0]).toMatch(
        /No reducer provided for key "thing"/
      )

      spy.mockClear()
      console.error = preSpy
    })

    it('throws an error if a reducer returns undefined handling an action', () => {
      const reducer = combineReducers({
        counter(state: number = 0, action: Action) {
          switch (action && action.type) {
            case 'increment':
              return state + 1
            case 'decrement':
              return state - 1
            case 'whatever':
            case null:
            case undefined:
              return undefined
            default:
              return state
          }
        }
      })

      expect(() => reducer({ counter: 0 }, { type: 'whatever' })).toThrow(
        /"whatever".*"counter"/
      )
      // @ts-expect-error
      expect(() => reducer({ counter: 0 }, null)).toThrow(
        /"counter".*an action/
      )
      expect(() => reducer({ counter: 0 }, {} as unknown as Action)).toThrow(
        /"counter".*an action/
      )
    })

    it('throws an error on first call if a reducer returns undefined initializing', () => {
      const reducer = combineReducers({
        counter(state: number, action: Action) {
          switch (action.type) {
            case 'increment':
              return state + 1
            case 'decrement':
              return state - 1
            default:
              return state
          }
        }
      })
      expect(() => reducer(undefined, { type: '' })).toThrow(
        /"counter".*initialization/
      )
    })

    it('catches error thrown in reducer when initializing and re-throw', () => {
      const reducer = combineReducers({
        throwingReducer() {
          throw new Error('Error thrown in reducer')
        }
      })
      expect(() => reducer(undefined, undefined as unknown as Action)).toThrow(
        /Error thrown in reducer/
      )
    })

    it('maintains referential equality if the reducers it is combining do', () => {
      const reducer = combineReducers({
        child1(state = {}) {
          return state
        },
        child2(state = {}) {
          return state
        },
        child3(state = {}) {
          return state
        }
      })

      const initialState = reducer(undefined, { type: '@@INIT' })
      expect(reducer(initialState, { type: 'FOO' })).toBe(initialState)
    })

    it('does not have referential equality if one of the reducers changes something', () => {
      const reducer = combineReducers({
        child1(state = {}) {
          return state
        },
        child2(state: { count: number } = { count: 0 }, action: Action) {
          switch (action.type) {
            case 'increment':
              return { count: state.count + 1 }
            default:
              return state
          }
        },
        child3(state = {}) {
          return state
        }
      })

      const initialState = reducer(undefined, { type: '@@INIT' })
      expect(reducer(initialState, { type: 'increment' })).not.toBe(
        initialState
      )
    })

    it('throws an error on first call if a reducer attempts to handle a private action', () => {
      const reducer = combineReducers({
        counter(state: number, action: Action) {
          switch (action.type) {
            case 'increment':
              return state + 1
            case 'decrement':
              return state - 1
            // Never do this in your code:
            case ActionTypes.INIT:
              return 0
            default:
              return undefined
          }
        }
      })
      expect(() => reducer(undefined, undefined as unknown as Action)).toThrow(
        /"counter".*private/
      )
    })

    it('warns if no reducers are passed to combineReducers', () => {
      const preSpy = console.error
      const spy = vi.fn()
      console.error = spy

      const reducer = combineReducers({})
      // @ts-ignore
      reducer(undefined, { type: '' })
      expect(spy.mock.calls[0][0]).toMatch(
        /Store does not have a valid reducer/
      )

      spy.mockClear()
      console.error = preSpy
    })

    it('warns if input state does not match reducer shape', () => {
      const preSpy = console.error
      const spy = vi.fn()
      const nullAction = undefined as unknown as Action
      console.error = spy

      interface ShapeState {
        foo: { bar: number }
        baz: { qux: number }
      }

      const reducer = combineReducers({
        foo(state = { bar: 1 }) {
          return state
        },
        baz(state = { qux: 3 }) {
          return state
        }
      })

      reducer(undefined, nullAction)
      expect(spy.mock.calls.length).toBe(0)

      reducer({ foo: { bar: 2 } } as unknown as ShapeState, nullAction)
      expect(spy.mock.calls.length).toBe(0)

      reducer(
        {
          foo: { bar: 2 },
          baz: { qux: 4 }
        },
        nullAction
      )
      expect(spy.mock.calls.length).toBe(0)

      createStore(reducer, { bar: 2 } as unknown as ShapeState)
      expect(spy.mock.calls[0][0]).toMatch(
        /Unexpected key "bar".*createStore.*instead: "foo", "baz"/
      )

      createStore(reducer, {
        bar: 2,
        qux: 4,
        thud: 5
      } as unknown as ShapeState)
      expect(spy.mock.calls[1][0]).toMatch(
        /Unexpected keys "qux", "thud".*createStore.*instead: "foo", "baz"/
      )

      createStore(reducer, 1 as unknown as ShapeState)
      expect(spy.mock.calls[2][0]).toMatch(
        /createStore has unexpected type of "number".*keys: "foo", "baz"/
      )

      reducer({ corge: 2 } as unknown as ShapeState, nullAction)
      expect(spy.mock.calls[3][0]).toMatch(
        /Unexpected key "corge".*reducer.*instead: "foo", "baz"/
      )

      reducer({ fred: 2, grault: 4 } as unknown as ShapeState, nullAction)
      expect(spy.mock.calls[4][0]).toMatch(
        /Unexpected keys "fred", "grault".*reducer.*instead: "foo", "baz"/
      )

      reducer(1 as unknown as ShapeState, nullAction)
      expect(spy.mock.calls[5][0]).toMatch(
        /reducer has unexpected type of "number".*keys: "foo", "baz"/
      )

      spy.mockClear()
      console.error = preSpy
    })

    it('only warns for unexpected keys once', () => {
      const preSpy = console.error
      const spy = vi.fn()
      console.error = spy
      const nullAction = { type: '' }

      const foo = (state = { foo: 1 }) => state
      const bar = (state = { bar: 2 }) => state

      expect(spy.mock.calls.length).toBe(0)

      interface WarnState {
        foo: { foo: number }
        bar: { bar: number }
      }

      const reducer = combineReducers({ foo, bar })
      const state = { foo: 1, bar: 2, qux: 3 } as unknown as WarnState
      const bazState = { ...state, baz: 5 } as unknown as WarnState

      reducer(state, nullAction)
      reducer(state, nullAction)
      reducer(state, nullAction)
      reducer(state, nullAction)
      expect(spy.mock.calls.length).toBe(1)

      reducer(bazState, nullAction)
      reducer({ ...bazState }, nullAction)
      reducer({ ...bazState }, nullAction)
      reducer({ ...bazState }, nullAction)
      expect(spy.mock.calls.length).toBe(2)

      spy.mockClear()
      console.error = preSpy
    })

    describe('With Replace Reducers', function () {
      const foo = (state = {}) => state
      const bar = (state = {}) => state
      const ACTION = { type: 'ACTION' }

      it('should return an updated state when additional reducers are passed to combineReducers', function () {
        type State = { foo: {}; bar?: {} }

        const originalCompositeReducer = combineReducers<State>({ foo })
        const store = createStore(originalCompositeReducer)

        store.dispatch(ACTION)

        const initialState = store.getState()

        store.replaceReducer(combineReducers<State>({ foo, bar }))
        store.dispatch(ACTION)

        const nextState = store.getState()
        expect(nextState).not.toBe(initialState)
      })

      it('should return an updated state when reducers passed to combineReducers are changed', function () {
        type State = { foo?: {}; bar: {}; baz?: {} }

        const baz = (state = {}) => state

        const originalCompositeReducer = combineReducers<State>({ foo, bar })
        const store = createStore(originalCompositeReducer)

        store.dispatch(ACTION)

        const initialState = store.getState()

        store.replaceReducer(combineReducers<State>({ baz, bar }))
        store.dispatch(ACTION)

        const nextState = store.getState()
        expect(nextState).not.toBe(initialState)
      })

      it('should return the same state when reducers passed to combineReducers not changed', function () {
        const originalCompositeReducer = combineReducers({ foo, bar })
        const store = createStore(originalCompositeReducer)

        store.dispatch(ACTION)

        const initialState = store.getState()

        store.replaceReducer(combineReducers({ foo, bar }))
        store.dispatch(ACTION)

        const nextState = store.getState()
        expect(nextState).toBe(initialState)
      })

      it('should return an updated state when one of more reducers passed to the combineReducers are removed', function () {
        const originalCompositeReducer = combineReducers<{
          foo?: typeof foo
          bar: typeof bar
        }>({ foo, bar })
        const store = createStore(originalCompositeReducer)

        store.dispatch(ACTION)

        const initialState = store.getState()

        store.replaceReducer(combineReducers({ bar }))

        const nextState = store.getState()
        expect(nextState).not.toBe(initialState)
      })
    })
  })
})

import { createStore, applyMiddleware } from 'redux'
import type { Middleware, MiddlewareAPI, Action, Store, Dispatch } from 'redux'
import { vi } from 'vitest'
import * as reducers from './helpers/reducers'
import { addTodo, addTodoAsync, addTodoIfEmpty } from './helpers/actionCreators'
import { thunk } from './helpers/middleware'

describe('applyMiddleware', () => {
  it('warns when dispatching during middleware setup', () => {
    function dispatchingMiddleware(store: Store) {
      store.dispatch(addTodo("Don't dispatch in middleware setup"))
      return (next: Dispatch) => (action: Action) => next(action)
    }

    expect(() =>
      applyMiddleware(dispatchingMiddleware as Middleware)(createStore)(
        reducers.todos
      )
    ).toThrow()
  })

  it('wraps dispatch method with middleware once', () => {
    function test(spyOnMethods: any): Middleware {
      return methods => {
        spyOnMethods(methods)
        return next => action => next(action)
      }
    }

    const spy = vi.fn()
    const store = applyMiddleware(test(spy), thunk)(createStore)(reducers.todos)

    store.dispatch(addTodo('Use Redux'))
    store.dispatch(addTodo('Flux FTW!'))

    expect(spy.mock.calls.length).toEqual(1)

    expect(spy.mock.calls[0][0]).toHaveProperty('getState')
    expect(spy.mock.calls[0][0]).toHaveProperty('dispatch')

    expect(store.getState()).toEqual([
      { id: 1, text: 'Use Redux' },
      { id: 2, text: 'Flux FTW!' }
    ])
  })

  it('passes recursive dispatches through the middleware chain', () => {
    function test(spyOnMethods: any): Middleware {
      return () => next => action => {
        spyOnMethods(action)
        return next(action)
      }
    }

    const spy = vi.fn()
    const store = applyMiddleware(test(spy), thunk)(createStore)(reducers.todos)

    // the typing for redux-thunk is super complex, so we will use an as unknown hack
    const dispatchedValue = store.dispatch(
      addTodoAsync('Use Redux') as any
    ) as unknown as Promise<void>
    return dispatchedValue.then(() => {
      expect(spy.mock.calls.length).toEqual(2)
    })
  })

  it('works with thunk middleware', async () => {
    const store = applyMiddleware(thunk)(createStore)(reducers.todos)

    store.dispatch(addTodoIfEmpty('Hello') as any)
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])

    store.dispatch(addTodoIfEmpty('Hello') as any)
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      }
    ])

    store.dispatch(addTodo('World'))
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      }
    ])

    // the typing for redux-thunk is super complex, so we will use an "as unknown" hack
    const dispatchedValue = store.dispatch(
      addTodoAsync('Maybe') as any
    ) as unknown as Promise<void>
    await dispatchedValue
    expect(store.getState()).toEqual([
      {
        id: 1,
        text: 'Hello'
      },
      {
        id: 2,
        text: 'World'
      },
      {
        id: 3,
        text: 'Maybe'
      }
    ])
  })

  it('passes through all arguments of dispatch calls from within middleware', () => {
    const spy = vi.fn()
    const testCallArgs = ['test']

    interface MultiDispatch<A extends Action = Action> {
      <T extends A>(action: T, extraArg?: string[]): T
    }

    const multiArgMiddleware: Middleware<
      MultiDispatch,
      any,
      MultiDispatch
    > = _store => {
      return next => (action: any, callArgs?: any) => {
        if (Array.isArray(callArgs)) {
          return action(...callArgs)
        }
        return next(action)
      }
    }

    function dummyMiddleware({ dispatch }: MiddlewareAPI) {
      return (_next: unknown) => (action: any) => dispatch(action, testCallArgs)
    }

    const store = createStore(
      reducers.todos,
      applyMiddleware(multiArgMiddleware, dummyMiddleware)
    )

    store.dispatch(spy as any)
    expect(spy.mock.calls[0]).toEqual(testCallArgs)
  })
})

import { compose } from '../src'

describe('Utils', () => {
  describe('compose', () => {
    it('composes from right to left', () => {
      const double = (x: number) => x * 2
      const square = (x: number) => x * x
      expect(compose(square)(5)).toBe(25)
      expect(compose(square, double)(5)).toBe(100)
      expect(compose(double, square, double)(5)).toBe(200)
    })

    it('composes functions from right to left', () => {
      const a = (next: (x: string) => string) => (x: string) => next(x + 'a')
      const b = (next: (x: string) => string) => (x: string) => next(x + 'b')
      const c = (next: (x: string) => string) => (x: string) => next(x + 'c')
      const final = (x: string) => x

      expect(compose(a, b, c)(final)('')).toBe('abc')
      expect(compose(b, c, a)(final)('')).toBe('bca')
      expect(compose(c, a, b)(final)('')).toBe('cab')
    })

    it('throws at runtime if argument is not a function', () => {
      type sFunc = (x: number, y: number) => number
      const square = (x: number, _: number) => x * x
      const add = (x: number, y: number) => x + y

      expect(() =>
        compose(square, add, false as unknown as sFunc)(1, 2)
      ).toThrow()
      // @ts-expect-error
      expect(() => compose(square, add, undefined)(1, 2)).toThrow()
      expect(() =>
        compose(square, add, true as unknown as sFunc)(1, 2)
      ).toThrow()
      expect(() =>
        compose(square, add, NaN as unknown as sFunc)(1, 2)
      ).toThrow()
      expect(() =>
        compose(square, add, '42' as unknown as sFunc)(1, 2)
      ).toThrow()
    })

    it('can be seeded with multiple arguments', () => {
      const square = (x: number, _: number) => x * x
      const add = (x: number, y: number) => x + y
      expect(compose(square, add)(1, 2)).toBe(9)
    })

    it('returns the first given argument if given no functions', () => {
      expect(compose<number>()(1, 2)).toBe(1)
      expect(compose()(3)).toBe(3)
      expect(compose()(undefined)).toBe(undefined)
    })

    it('returns the first function if given only one', () => {
      const fn = () => {}

      expect(compose(fn)).toBe(fn)
    })
  })
})

import type { Action, Dispatch } from 'redux'

interface Component<P> {
  props: P
}

interface HOC<T> {
  <P>(wrapped: Component<P & T>): Component<P>
}

declare function connect<T, D extends Dispatch = Dispatch>(
  mapDispatchToProps: (dispatch: D) => T
): HOC<T>

describe('type tests', () => {
  test('inject default dispatch.', () => {
    const hoc: HOC<{ onClick(): void }> = connect(dispatch => {
      return {
        onClick() {
          expectTypeOf(dispatch).toBeCallableWith({ type: 'INCREMENT' })

          expectTypeOf(dispatch)
            .parameter(0)
            .not.toMatchTypeOf(Promise.resolve({ type: 'INCREMENT' }))

          expectTypeOf(dispatch).parameter(0).not.toMatchTypeOf('not-an-action')
        }
      }
    })
  })

  test('inject dispatch that restricts allowed action types.', () => {
    interface IncrementAction {
      type: 'INCREMENT'
      count?: number
    }

    interface DecrementAction {
      type: 'DECREMENT'
      count?: number
    }

    // Union of all actions in the app.
    type MyAction = IncrementAction | DecrementAction

    const hoc: HOC<{ onClick(): void }> = connect(
      (dispatch: Dispatch<MyAction>) => {
        return {
          onClick() {
            expectTypeOf(dispatch).toBeCallableWith({ type: 'INCREMENT' })

            expectTypeOf(dispatch).toBeCallableWith({
              type: 'DECREMENT',
              count: 10
            })

            expectTypeOf(dispatch)
              .parameter(0)
              .not.toMatchTypeOf({ type: 'DECREMENT', count: '' })

            expectTypeOf(dispatch)
              .parameter(0)
              .not.toEqualTypeOf({ type: 'SOME_OTHER_TYPE' })

            expectTypeOf(dispatch)
              .parameter(0)
              .not.toMatchTypeOf('not-an-action')
          }
        }
      }
    )
  })

  test('inject extended dispatch.', () => {
    type PromiseDispatch = <T extends Action>(promise: Promise<T>) => Promise<T>

    type MyDispatch = Dispatch & PromiseDispatch

    const hoc: HOC<{ onClick(): void }> = connect((dispatch: MyDispatch) => {
      return {
        onClick() {
          // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
          // do not work in this scenario.
          dispatch({ type: 'INCREMENT' })

          expectTypeOf(dispatch).toBeCallableWith(
            Promise.resolve({ type: 'INCREMENT' })
          )

          expectTypeOf(dispatch).parameter(0).not.toMatchTypeOf('not-an-action')
        }
      }
    })
  })
})

import type { Action as ReduxAction } from 'redux'

describe('type tests', () => {
  test('FSA', () => {
    interface Action<P> extends ReduxAction {
      payload: P
    }

    const action: Action<string> = {
      type: 'ACTION_TYPE',
      payload: 'test'
    }

    expectTypeOf(action.payload).toBeString()
  })

  test('FreeShapeAction', () => {
    interface Action extends ReduxAction {
      [key: string]: any
    }

    const action: Action = {
      type: 'ACTION_TYPE',
      text: 'test'
    }

    expectTypeOf(action.text).toBeAny()
  })

  test('StringLiteralTypeAction', () => {
    type ActionType = 'A' | 'B' | 'C'

    interface Action extends ReduxAction {
      type: ActionType
    }

    const action: Action = {
      type: 'A'
    }

    expectTypeOf(action.type).toEqualTypeOf<ActionType>()
  })
})

import { compose } from 'redux'

describe('type tests', () => {
  // adapted from DefinitelyTyped/compose-function

  const numberToNumber = (a: number): number => a + 2

  const numberToString = (a: number): string => 'foo'

  const stringToNumber = (a: string): number => 5

  test('compose', () => {
    expectTypeOf(compose(numberToNumber, numberToNumber)(5)).toBeNumber()

    expectTypeOf(compose(numberToString, numberToNumber)(5)).toBeString()

    expectTypeOf(compose(numberToString, stringToNumber)('f')).toBeString()

    expectTypeOf(
      compose(
        (f: (a: string) => number) => (p: string) => 5,
        (f: (a: number) => string) => (p: string) => 4
      )(numberToString)
    ).toMatchTypeOf<(a: string) => number>()

    expectTypeOf(
      compose(stringToNumber, numberToString, numberToNumber)(5)
    ).toBeNumber()

    expectTypeOf(
      compose(numberToString, stringToNumber, numberToString, numberToNumber)(5)
    ).toBeString()

    // rest signature
    expectTypeOf(
      compose<string>(
        numberToString,
        numberToNumber,
        stringToNumber,
        numberToString,
        stringToNumber
      )('fo')
    ).toBeString()

    const multiArgFn = (a: string, b: number, c: boolean): string => 'foo'

    expectTypeOf(compose(multiArgFn)('bar', 42, true)).toBeString()

    expectTypeOf(
      compose(stringToNumber, multiArgFn)('bar', 42, true)
    ).toBeNumber()

    expectTypeOf(
      compose(numberToString, stringToNumber, multiArgFn)('bar', 42, true)
    ).toBeString()

    expectTypeOf(
      compose(
        stringToNumber,
        numberToString,
        stringToNumber,
        multiArgFn
      )('bar', 42, true)
    ).toBeNumber()

    const funcs = [stringToNumber, numberToString, stringToNumber]

    expectTypeOf(compose(...funcs)).toBeCallableWith('bar')
  })
})

import type {
  Action,
  ActionCreator,
  ActionCreatorsMapObject,
  Dispatch
} from 'redux'
import { bindActionCreators } from 'redux'
import { addTodo } from '../helpers/actionCreators'

interface AddTodoAction extends Action {
  text: string
}

declare const dispatch: Dispatch

describe('type tests', () => {
  test('ActionCreator', () => {
    const addTodo: ActionCreator<AddTodoAction, [string]> = text => ({
      type: 'ADD_TODO',
      text
    })

    expectTypeOf(addTodo('test')).toEqualTypeOf<AddTodoAction>()
  })

  test('bound', () => {
    type AddTodoThunk = (dispatch: Dispatch) => AddTodoAction
    const addTodoViaThunk: ActionCreator<AddTodoThunk> =
      text => (_: Dispatch) => ({
        type: 'ADD_TODO',
        text
      })

    const boundAddTodo = bindActionCreators(addTodo, dispatch)

    expectTypeOf(boundAddTodo('test')).toMatchTypeOf<AddTodoAction>()

    const boundAddTodoViaThunk = bindActionCreators<
      ActionCreator<AddTodoThunk, [string]>,
      ActionCreator<AddTodoAction, [string]>
    >(addTodoViaThunk, dispatch)

    expectTypeOf(boundAddTodoViaThunk('test')).toEqualTypeOf<AddTodoAction>()

    const boundActionCreators = bindActionCreators({ addTodo }, dispatch)

    expectTypeOf(
      boundActionCreators.addTodo('test')
    ).toMatchTypeOf<AddTodoAction>()

    interface M extends ActionCreatorsMapObject {
      addTodoViaThunk: ActionCreator<AddTodoThunk, [string]>
    }

    interface N extends ActionCreatorsMapObject {
      addTodoViaThunk: ActionCreator<AddTodoAction, [string]>
    }

    const boundActionCreators2 = bindActionCreators<M, N>(
      { addTodoViaThunk },
      dispatch
    )

    expectTypeOf(
      boundActionCreators2.addTodoViaThunk('test')
    ).toEqualTypeOf<AddTodoAction>()
  })
})

import type {
  Action,
  Observer,
  Reducer,
  Store,
  StoreEnhancer,
  Unsubscribe
} from 'redux'
import { combineReducers, createStore } from 'redux'

describe('type tests', () => {
  type BrandedString = string & { _brand: 'type' }

  const brandedString = 'a string' as BrandedString

  type State = {
    a: 'a'
    b: {
      c: 'c'
      d: 'd'
    }
    e: BrandedString
  }

  interface DerivedAction extends Action {
    type: 'a'
    b: 'b'
  }

  const reducer: Reducer<State> = (
    state: State | undefined = {
      a: 'a',
      b: {
        c: 'c',
        d: 'd'
      },
      e: brandedString
    },
    action: Action
  ): State => {
    return state
  }

  const reducerWithAction: Reducer<State, DerivedAction> = (
    state: State | undefined = {
      a: 'a',
      b: {
        c: 'c',
        d: 'd'
      },
      e: brandedString
    },
    action: DerivedAction
  ): State => {
    return state
  }

  const funcWithStore = (store: Store<State, DerivedAction>) => {}

  test('createStore', () => {
    const store: Store<State> = createStore(reducer)

    // test that nullable state is preserved
    const nullableStore = createStore((): string | null => null)

    expectTypeOf(nullableStore.getState()).toEqualTypeOf<string | null>()

    // ensure that an array-based state works
    const arrayReducer = (state: any[] = []) => state || []

    expectTypeOf(createStore(arrayReducer)).toMatchTypeOf<Store<any[]>>()

    expectTypeOf(
      createStore(reducer, { a: 'a', b: { c: 'c', d: 'd' }, e: brandedString })
    ).toEqualTypeOf<Store<State>>()

    // @ts-expect-error
    createStore(reducer, { b: { c: 'c' }, e: brandedString })

    const reducerA: Reducer<string> = (state = 'a') => state

    const reducerB: Reducer<{ c: string; d: string }> = (
      state = { c: 'c', d: 'd' }
    ) => state

    const reducerE: Reducer<BrandedString> = (state = brandedString) => state

    const combinedReducer = combineReducers({
      a: reducerA,
      b: reducerB,
      e: reducerE
    })

    const storeWithCombineReducer = createStore(combinedReducer, {
      b: { c: 'c', d: 'd' },
      e: brandedString
    })

    const storeWithCombineReducerAndBadPreloadedState =
      // @ts-expect-error
      // prettier-ignore
      createStore( combinedReducer, { b: { c: 'c' }, e: brandedString  }  )

    const nestedCombinedReducer = combineReducers({
      a: (state: string = 'a') => state,
      b: combineReducers({
        c: (state: string = 'c') => state,
        d: (state: string = 'd') => state
      }),
      e: (state: BrandedString = brandedString) => state
    })

    // @ts-expect-error
    const storeWithNestedCombineReducer = createStore(nestedCombinedReducer, {
      b: { c: 5 },
      e: brandedString
    })

    const simpleCombinedReducer = combineReducers({
      c: (state: string = 'c') => state,
      d: (state: string = 'd') => state
    })

    const storeWithSimpleCombinedReducer =
      // @ts-expect-error
      // prettier-ignore
      createStore(simpleCombinedReducer, { c: 5 })

    // Note: It's not necessary that the errors occur on the lines specified, just as long as something errors somewhere
    // since the preloaded state doesn't match the reducer type.

    const simpleCombinedReducerWithImplicitState = combineReducers({
      c: (state = 'c') => state,
      d: (state = 'd') => state
    })

    const storeWithSimpleCombinedReducerWithImplicitState =
      // @ts-expect-error
      // prettier-ignore
      createStore( simpleCombinedReducerWithImplicitState,  { c: 5 } )

    const storeWithActionReducer = createStore(reducerWithAction)

    const storeWithActionReducerAndPreloadedState = createStore(
      reducerWithAction,
      {
        a: 'a',
        b: { c: 'c', d: 'd' },
        e: brandedString
      }
    )

    expectTypeOf(funcWithStore).toBeCallableWith(storeWithActionReducer)

    expectTypeOf(funcWithStore).toBeCallableWith(
      storeWithActionReducerAndPreloadedState
    )

    const storeWithActionReducerAndBadPreloadedState =
      // @ts-expect-error
      // prettier-ignore
      createStore( reducerWithAction,  {   b: { c: 'c' },  e: brandedString  } )

    const enhancer: StoreEnhancer = next => next

    const storeWithSpecificEnhancer: Store<State> = createStore(
      reducer,
      enhancer
    )

    const storeWithPreloadedStateAndEnhancer: Store<State> = createStore(
      reducer,
      {
        a: 'a',
        b: { c: 'c', d: 'd' },
        e: brandedString
      },
      enhancer
    )

    const storeWithBadPreloadedStateAndEnhancer: Store<State> = createStore(
      reducer,
      {
        // @ts-expect-error
        b: { c: 'c' }
      },
      enhancer
    )

    /* dispatch */

    store.dispatch({
      type: 'ADD_TODO',
      text: 'test'
    })

    /* getState */

    expectTypeOf(store.getState()).toEqualTypeOf<State>()

    /* subscribe / unsubscribe */

    const unsubscribe: Unsubscribe = store.subscribe(() => {
      console.log('Current state:', store.getState())
    })

    expectTypeOf(unsubscribe).toBeCallableWith()

    /* replaceReducer */

    const newReducer: Reducer<State> = reducer

    expectTypeOf(store.replaceReducer).toBeCallableWith(newReducer)

    /* observable */

    let observable = store[Symbol.observable]()

    observable = observable[Symbol.observable]()

    const observer: Observer<State> = {
      next(state: State) {
        console.log('current state:', state)
      }
    }

    const unsubscribeFromObservable = observable.subscribe(observer).unsubscribe

    expectTypeOf(unsubscribeFromObservable).toBeCallableWith()
  })
})

import type {
  Action,
  AnyAction,
  PreloadedStateShapeFromReducersMapObject,
  Reducer,
  ReducersMapObject
} from 'redux'
import { combineReducers } from 'redux'

describe('type tests', () => {
  test('AnyAction type is used to allow action property access without requiring type casting.', () => {
    // Simple reducer definition with no action shape checks.
    // Uses string comparison to determine action type.

    type State = number

    const reducer: Reducer<State> = (state = 0, action) => {
      if (action.type === 'INCREMENT') {
        const { count = 1 } = action
        if (typeof count === 'number') {
          return state + count
        }
      }

      if (action.type === 'DECREMENT') {
        const { count = 1 } = action
        if (typeof count === 'number') {
          return state + count
        }
      }

      return state
    }

    // Reducer function accepts any object with `type` prop as action.
    // Any extra props are allowed too.
    const s: State = reducer(undefined, { type: 'init' })

    expectTypeOf(reducer(s, { type: 'INCREMENT' })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'INCREMENT', count: 10 })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'DECREMENT' })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'DECREMENT', count: 10 })).toEqualTypeOf(s)

    expectTypeOf(
      reducer(s, { type: 'SOME_OTHER_TYPE', someField: 'value' })
    ).toEqualTypeOf(s)

    // State shape is strictly checked.
    expectTypeOf(reducer).parameters.not.toMatchTypeOf([
      'string',
      { type: 'INCREMENT' }
    ])

    // Combined reducer also accepts any action.
    const combined = combineReducers({ sub: reducer })

    const cs: { sub: State } = combined(undefined, { type: 'init' })

    expectTypeOf(combined(cs, { type: 'INCREMENT', count: 10 })).toEqualTypeOf(
      cs
    )

    // Combined reducer's state is strictly checked.
    expectTypeOf(combined).parameters.not.toMatchTypeOf([
      { unknown: '' },
      { type: 'INCREMENT' }
    ])
  })

  test('reducer definition using discriminated unions.', () => {
    //  See https://basarat.gitbooks.io/typescript/content/docs/types/discriminated-unions.html#redux

    type State = number

    interface IncrementAction {
      type: 'INCREMENT'
      count?: number
    }

    interface DecrementAction {
      type: 'DECREMENT'
      count?: number
    }

    interface MultiplyAction {
      type: 'MULTIPLY'
      count?: number
    }

    interface DivideAction {
      type: 'DIVIDE'
      count?: number
    }

    // Union of all actions in the app.
    type MyAction0 = IncrementAction | DecrementAction

    type MyAction1 = MultiplyAction | DivideAction

    const reducer0: Reducer<State, MyAction0> = (state = 0, action) => {
      if (action.type === 'INCREMENT') {
        // Action shape is determined by `type` discriminator.
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state + count
      }

      if (action.type === 'DECREMENT') {
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state - count
      }

      return state
    }

    const reducer1: Reducer<State, MyAction1> = (state = 0, action) => {
      if (action.type === 'MULTIPLY') {
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state * count
      }

      if (action.type === 'DIVIDE') {
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state / count
      }

      return state
    }

    // Reducer state is initialized by Redux using Init action which is private.
    // To initialize manually (e.g. in tests) we have to type cast init action
    // or add a custom init action to MyAction union.
    const s: State = reducer0(undefined, { type: 'init' } as any)

    expectTypeOf(reducer0(s, { type: 'INCREMENT' })).toEqualTypeOf(s)

    expectTypeOf(reducer0(s, { type: 'INCREMENT', count: 10 })).toEqualTypeOf(s)

    // Known actions are strictly checked.
    expectTypeOf(reducer0).parameters.not.toMatchTypeOf([
      s,
      { type: 'DECREMENT', coun: 10 }
    ])

    // Unknown actions are rejected.
    expectTypeOf(reducer0).parameters.not.toMatchTypeOf([
      s,
      { type: 'SOME_OTHER_TYPE' }
    ])

    expectTypeOf(reducer0).parameters.not.toMatchTypeOf<
      [typeof s, { type: 'SOME_OTHER_TYPE'; someField: 'value' }]
    >()

    // Combined reducer infers state and actions by default which maintains type
    // safety and still allows inclusion of third-party reducers without the need
    // to explicitly add their state and actions to the union.
    const combined = combineReducers({ sub0: reducer0, sub1: reducer1 })

    const cs = combined(undefined, { type: 'INCREMENT' })

    expectTypeOf(combined).toBeCallableWith(cs, { type: 'MULTIPLY' })

    expectTypeOf(combined).parameters.not.toMatchTypeOf<
      [typeof cs, { type: 'init' }]
    >()

    expectTypeOf(combined).parameters.not.toMatchTypeOf<
      [typeof cs, { type: 'SOME_OTHER_TYPE' }]
    >()

    // Combined reducer can be made to only accept known actions.
    const strictCombined = combineReducers({
      sub: reducer0
    })

    const scs = strictCombined(undefined, { type: 'INCREMENT' })

    expectTypeOf(strictCombined).toBeCallableWith(scs, { type: 'DECREMENT' })

    expectTypeOf(strictCombined).parameters.not.toMatchTypeOf<
      [typeof scs, { type: 'SOME_OTHER_TYPE' }]
    >()
  })

  test('reducer definition using type guards.', () => {
    function isAction<A extends Action>(
      action: Action,
      type: any
    ): action is A {
      return action.type === type
    }

    type State = number

    interface IncrementAction {
      type: 'INCREMENT'
      count?: number
    }

    interface DecrementAction {
      type: 'DECREMENT'
      count?: number
    }

    const reducer: Reducer<State, AnyAction> = (state = 0, action) => {
      if (isAction<IncrementAction>(action, 'INCREMENT')) {
        // TODO: this doesn't seem to work correctly with UnknownAction - `action` becomes `UnknownAction & IncrementAction`
        // Action shape is determined by the type guard returned from `isAction`
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state + count
      }

      if (isAction<DecrementAction>(action, 'DECREMENT')) {
        expectTypeOf(action).not.toHaveProperty('wrongField')

        const { count = 1 } = action

        return state - count
      }

      return state
    }

    const s: State = reducer(undefined, { type: 'init' })

    expectTypeOf(reducer(s, { type: 'INCREMENT' })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'INCREMENT', count: 10 })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'DECREMENT' })).toEqualTypeOf(s)

    expectTypeOf(reducer(s, { type: 'DECREMENT', count: 10 })).toEqualTypeOf(s)

    expectTypeOf(
      reducer(s, { type: 'SOME_OTHER_TYPE', someField: 'value' })
    ).toEqualTypeOf(s)

    const combined = combineReducers({ sub: reducer })

    const cs: { sub: State } = combined(undefined, { type: 'init' })

    expectTypeOf(combined(cs, { type: 'INCREMENT' })).toEqualTypeOf(cs)
  })

  test('ReducersMapObject with default type args.', () => {
    const obj: ReducersMapObject = {}

    for (const key of Object.keys(obj)) {
      expectTypeOf(obj[key]).toBeCallableWith(undefined, { type: 'SOME_TYPE' })

      expectTypeOf(obj[key]).parameters.not.toMatchTypeOf<
        [undefined, 'not-an-action']
      >()
    }
  })

  test('`PreloadedStateShapeFromReducersMapObject` has correct type when given a custom action', () => {
    type MyAction = { type: 'foo' }

    // TODO: not sure how to write this test??
    // Expect this to match type `{ nested: string | undefined; }`
    type P = PreloadedStateShapeFromReducersMapObject<{
      nested: Reducer<string, MyAction>
    }>
  })

  test('`combineReducer` has correct return type when given a custom action', () => {
    type MyAction = { type: 'foo' }

    type State = string
    const nested: Reducer<State, MyAction> = (state = 'foo') => state

    type Combined = { nested: State }

    // Expect no error
    const combined: Reducer<
      Combined,
      MyAction,
      Partial<Combined>
    > = combineReducers({ nested })
  })
})

import type { Dispatch } from 'redux'

describe('type tests', () => {
  test('default Dispatch type accepts any object with `type` property.', () => {
    const dispatch: Dispatch = null as any

    const a = dispatch({ type: 'INCREMENT', count: 10 })

    expectTypeOf(a).toHaveProperty('count')

    expectTypeOf(a).not.toHaveProperty('wrongProp')

    expectTypeOf(dispatch).parameter(0).not.toMatchTypeOf('not-an-action')
  })

  test('Dispatch accepts type argument that restricts allowed action types.', () => {
    interface IncrementAction {
      type: 'INCREMENT'
      count?: number
    }

    interface DecrementAction {
      type: 'DECREMENT'
      count?: number
    }

    // Union of all actions in the app.
    type MyAction = IncrementAction | DecrementAction

    const dispatch: Dispatch<MyAction> = null as any

    expectTypeOf(dispatch).parameter(0).toMatchTypeOf({ type: 'INCREMENT' })

    expectTypeOf(dispatch).toBeCallableWith({ type: 'DECREMENT', count: 10 })

    // Known actions are strictly checked.
    expectTypeOf(dispatch)
      .parameter(0)
      .not.toMatchTypeOf({ type: 'DECREMENT', count: '' })

    // Unknown actions are rejected.
    expectTypeOf(dispatch)
      .parameter(0)
      .not.toEqualTypeOf({ type: 'SOME_OTHER_TYPE' })
  })
})

import type { Action, Reducer, StoreEnhancer } from 'redux'
import { createStore } from 'redux'

interface State {
  someField: 'string'
}

const reducer: Reducer<State> = null as any

describe('type tests', () => {
  test('Store enhancer that extends the type of dispatch.', () => {
    type PromiseDispatch = <T extends Action>(promise: Promise<T>) => Promise<T>

    const enhancer: StoreEnhancer<{
      dispatch: PromiseDispatch
    }> =
      createStore =>
      <S, A extends Action, PreloadedState>(
        reducer: Reducer<S, A, PreloadedState>,
        preloadedState?: PreloadedState | undefined
      ) => {
        const store = createStore(reducer, preloadedState)

        return {
          ...store,
          dispatch: (action: any) => {
            if (action.type) {
              store.dispatch(action)
            } else if (action.then) {
              action.then(store.dispatch)
            }
            return action
          }
        }
      }

    const store = createStore(reducer, enhancer)

    // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
    // do not work in this scenario.
    store.dispatch({ type: 'INCREMENT' })

    store.dispatch(Promise.resolve({ type: 'INCREMENT' }))

    expectTypeOf(store.dispatch).parameter(0).not.toMatchTypeOf('not-an-action')

    expectTypeOf(store.dispatch)
      .parameter(0)
      .not.toMatchTypeOf(Promise.resolve('not-an-action'))
  })

  test('Store enhancer that extends the type of the state.', () => {
    interface ExtraState {
      extraField: string
    }

    const enhancer: StoreEnhancer<{}, ExtraState> =
      createStore =>
      <S, A extends Action, PreloadedState>(
        reducer: Reducer<S, A, PreloadedState>,
        preloadedState?: PreloadedState | undefined
      ) => {
        function wrapReducer<PreloadedStateToWrap>(
          reducer: Reducer<S, A, PreloadedStateToWrap>
        ): Reducer<S & ExtraState, A, PreloadedStateToWrap & ExtraState> {
          return (state, action) => {
            const newState = reducer(state, action)

            return {
              ...newState,
              extraField: 'extra'
            }
          }
        }

        const wrappedPreloadedState = preloadedState
          ? {
              ...preloadedState,
              extraField: 'extra'
            }
          : undefined

        const store = createStore(wrapReducer(reducer), wrappedPreloadedState)

        return {
          ...store,
          replaceReducer(nextReducer: Reducer<S, A>) {
            store.replaceReducer(wrapReducer(nextReducer))
          }
        }
      }

    const store = createStore(reducer, enhancer)

    expectTypeOf(store.getState()).toHaveProperty('someField')

    expectTypeOf(store.getState()).toHaveProperty('extraField')

    expectTypeOf(store.getState()).not.toHaveProperty('wrongField')
  })

  test('Store enhancer that adds methods to the store.', () => {
    const enhancer: StoreEnhancer<{ method(): string }> =
      createStore =>
      (...args) => {
        const store = createStore(...args)

        return {
          ...store,
          method: () => 'foo'
        }
      }

    const store = createStore(reducer, enhancer)

    expectTypeOf(store.getState).toBeCallableWith()

    expectTypeOf(store.method()).toBeString()

    expectTypeOf(store).not.toHaveProperty('wrongMethod')
  })

  test('replaceReducer with a store enhancer', () => {
    interface ExtraState {
      extraField: string
    }

    const enhancer: StoreEnhancer<{ method(): string }, ExtraState> =
      createStore =>
      <S, A extends Action, PreloadedState>(
        reducer: Reducer<S, A, PreloadedState>,
        preloadedState?: PreloadedState | undefined
      ) => {
        function wrapReducer<PreloadedStateToWrap>(
          reducer: Reducer<S, A, PreloadedStateToWrap>
        ): Reducer<S & ExtraState, A, PreloadedStateToWrap & ExtraState> {
          return (state, action) => {
            const newState = reducer(state, action)

            return {
              ...newState,
              extraField: 'extra'
            }
          }
        }

        const wrappedPreloadedState = preloadedState
          ? {
              ...preloadedState,
              extraField: 'extra'
            }
          : undefined

        const store = createStore(wrapReducer(reducer), wrappedPreloadedState)

        return {
          ...store,
          replaceReducer(nextReducer: Reducer<S, A>) {
            store.replaceReducer(wrapReducer(nextReducer))
          },
          method: () => 'foo'
        }
      }

    interface PartialState {
      someField?: 'string'
      test?: boolean
    }

    const initialReducer: Reducer<PartialState, Action> = () => ({
      someField: 'string'
    })

    const store = createStore<
      PartialState,
      Action,
      { method(): string },
      ExtraState
    >(initialReducer, enhancer)

    const newReducer = (state: PartialState = { test: true }, _: Action) =>
      state

    expectTypeOf(store.replaceReducer).parameter(0).toEqualTypeOf(newReducer)

    expectTypeOf(store.getState()).toHaveProperty('test')

    expectTypeOf(store.getState()).toHaveProperty('extraField')

    expectTypeOf(store.getState()).not.toHaveProperty('wrongField')

    expectTypeOf(store.method()).toBeString()

    expectTypeOf(store).not.toHaveProperty('wrongMethod')
  })

  test('mhelmersonExample', () => {
    interface State {
      someField: 'string'
    }

    interface ExtraState {
      extraField: 'extra'
    }

    const reducer: Reducer<State> = null as any

    test('state extension expected to work', () => {
      interface ExtraState {
        extraField: string
      }

      const enhancer: StoreEnhancer<{}, ExtraState> =
        createStore =>
        <S, A extends Action, PreloadedState>(
          reducer: Reducer<S, A, PreloadedState>,
          preloadedState?: PreloadedState | undefined
        ) => {
          const wrappedReducer: Reducer<
            S & ExtraState,
            A,
            PreloadedState & ExtraState
          > = (state, action) => {
            const newState = reducer(state, action)

            return {
              ...newState,
              extraField: 'extra'
            }
          }

          const wrappedPreloadedState = preloadedState
            ? {
                ...preloadedState,
                extraField: 'extra'
              }
            : undefined

          const store = createStore(wrappedReducer, wrappedPreloadedState)

          return {
            ...store,
            replaceReducer(nextReducer: Reducer<S, A>) {
              const nextWrappedReducer: Reducer<S & ExtraState, A> = (
                state,
                action
              ) => {
                const newState = nextReducer(state, action)

                return {
                  ...newState,
                  extraField: 'extra'
                }
              }

              return store.replaceReducer(nextWrappedReducer)
            }
          }
        }

      interface PartialState {
        someField?: 'string'
        test?: boolean
      }

      const initialReducer: Reducer<PartialState, Action> = () => ({
        someField: 'string'
      })

      const store = createStore<PartialState, Action, {}, ExtraState>(
        initialReducer,
        enhancer
      )

      expectTypeOf(store.replaceReducer)
        .parameter(0)
        .toEqualTypeOf(initialReducer)

      expectTypeOf(store.getState()).toHaveProperty('extraField')

      expectTypeOf(store.getState()).not.toHaveProperty('wrongField')

      expectTypeOf(store.getState()).toHaveProperty('test')

      const newReducer = (state: PartialState = { test: true }, _: Action) =>
        state

      expectTypeOf(store.replaceReducer).parameter(0).toEqualTypeOf(newReducer)

      expectTypeOf(store.getState()).toHaveProperty('test')

      expectTypeOf(store.getState()).toHaveProperty('extraField')

      expectTypeOf(store.getState()).not.toHaveProperty('wrongField')
    })
  })

  test('finalHelmersonExample', () => {
    interface ExtraState {
      foo: string
    }

    function persistReducer<S, A extends Action, PreloadedState>(
      config: any,
      reducer: Reducer<S, A, PreloadedState>
    ) {
      return (
        state: (S & ExtraState) | PreloadedState | undefined,
        action: A
      ) => {
        const newState = reducer(state, action)

        return {
          ...newState,
          foo: 'hi'
        }
      }
    }

    function persistStore<S>(store: S) {
      return store
    }

    function createPersistEnhancer(
      persistConfig: any
    ): StoreEnhancer<{}, ExtraState> {
      return createStore =>
        <S, A extends Action, PreloadedState>(
          reducer: Reducer<S, A, PreloadedState>,
          preloadedState?: PreloadedState | undefined
        ) => {
          const persistedReducer = persistReducer(persistConfig, reducer)

          const store = createStore(persistedReducer, preloadedState)

          const persistor = persistStore(store)

          return {
            ...store,
            replaceReducer: (nextReducer: Reducer<S, A>) => {
              store.replaceReducer(persistReducer(persistConfig, nextReducer))
            },
            persistor
          }
        }
    }

    interface PartialState {
      someField?: 'string'
      test?: boolean
    }

    const initialReducer: Reducer<PartialState, Action> = () => ({
      someField: 'string'
    })

    const store = createStore<PartialState, Action, {}, ExtraState>(
      initialReducer,
      createPersistEnhancer('hi')
    )

    expectTypeOf(store.getState()).toHaveProperty('foo')

    expectTypeOf(store.getState()).not.toHaveProperty('wrongField')

    const newReducer = (state: PartialState = { test: true }, _: Action) =>
      state

    expectTypeOf(store.replaceReducer).parameter(0).toEqualTypeOf(newReducer)

    expectTypeOf(store.getState()).toHaveProperty('test')

    expectTypeOf(store.getState()).not.toHaveProperty('whatever')

    expectTypeOf(store.getState()).not.toHaveProperty('wrongField')
  })

  test('composedEnhancers', () => {
    interface State {
      someState: string
    }

    const reducer: Reducer<State> = null as any

    interface Ext1 {
      enhancer1: string
    }

    interface Ext2 {
      enhancer2: number
    }

    const enhancer1: StoreEnhancer<Ext1> =
      createStore => (reducer, preloadedState) => {
        const store = createStore(reducer, preloadedState)
        return {
          ...store,
          enhancer1: 'foo'
        }
      }

    const enhancer2: StoreEnhancer<Ext2> =
      createStore => (reducer, preloadedState) => {
        const store = createStore(reducer, preloadedState)
        return {
          ...store,
          enhancer2: 5
        }
      }

    const composedEnhancer: StoreEnhancer<Ext1 & Ext2> = createStore =>
      enhancer2(enhancer1(createStore))

    const enhancedStore = createStore(reducer, composedEnhancer)

    expectTypeOf(enhancedStore).toHaveProperty('enhancer1')

    expectTypeOf(enhancedStore).toHaveProperty('enhancer2')

    expectTypeOf(enhancedStore).not.toHaveProperty('enhancer3')
  })
})

import type {
  Action,
  Dispatch,
  Middleware,
  MiddlewareAPI,
  Reducer
} from 'redux'
import { applyMiddleware, createStore } from 'redux'

type PromiseDispatch = <T extends Action>(promise: Promise<T>) => Promise<T>

interface Thunk<R, S, DispatchExt = {}> {
  (dispatch: Dispatch & ThunkDispatch<S> & DispatchExt, getState: () => S): R
}

interface ThunkDispatch<S, DispatchExt = {}> {
  <R>(thunk: Thunk<R, S, DispatchExt>): R
}

declare const logger: () => Middleware

declare const promise: () => Middleware<PromiseDispatch>

declare const thunk: <S, DispatchExt>() => Middleware<
  ThunkDispatch<S, DispatchExt>,
  S,
  Dispatch & ThunkDispatch<S>
>

describe('type tests', () => {
  test("Logger middleware doesn't add any extra types to dispatch, just logs actions and state.", () => {
    const loggerMiddleware: Middleware =
      ({ getState }) =>
      next =>
      action => {
        console.log('will dispatch', action)

        // Call the next dispatch method in the middleware chain.
        const returnValue = next(action)

        console.log('state after dispatch', getState())

        // This will likely be the action itself, unless
        // a middleware further in chain changed it.
        return returnValue
      }
  })

  test('Promise middleware adds support for dispatching promises.', () => {
    const promiseMiddleware: Middleware<PromiseDispatch> =
      ({ dispatch }) =>
      next =>
      action => {
        if (action instanceof Promise) {
          action.then(dispatch)
          return action
        }

        return next(action)
      }

    return promiseMiddleware
  })

  test('Thunk middleware adds support for dispatching thunks.', () => {
    function thunk<S, DispatchExt>() {
      const thunkMiddleware: Middleware<
        ThunkDispatch<S, DispatchExt>,
        S,
        Dispatch & ThunkDispatch<S>
      > = api => next => action =>
        typeof action === 'function'
          ? action(api.dispatch, api.getState)
          : next(action)

      return thunkMiddleware
    }
  })

  test('middleware that expects exact state type.', () => {
    type State = { field: 'string' }

    const customMiddleware: Middleware<{}, State> = api => next => action => {
      expectTypeOf(api.getState()).toHaveProperty('field')

      expectTypeOf(api.getState()).not.toHaveProperty('wrongField')

      return next(action)
    }
  })

  test('middleware that expects custom dispatch.', () => {
    type MyAction = { type: 'INCREMENT' } | { type: 'DECREMENT' }

    // dispatch that expects action union
    type MyDispatch = Dispatch<MyAction>

    const customDispatch: Middleware =
      (api: MiddlewareAPI<MyDispatch>) => next => action => {
        expectTypeOf(api.dispatch).toBeCallableWith({ type: 'INCREMENT' })

        expectTypeOf(api.dispatch).toBeCallableWith({ type: 'DECREMENT' })

        // `.not.toMatchTypeOf` does not work in this scenario.
        expectTypeOf(api.dispatch)
          .parameter(0)
          .not.toEqualTypeOf({ type: 'UNKNOWN' })
      }
  })

  test('test the type of store.dispatch after applying different middleware.', () => {
    interface State {
      someField: 'string'
    }
    const reducer: Reducer<State> = null as any

    test('logger', () => {
      const storeWithLogger = createStore(reducer, applyMiddleware(logger()))
      // can only dispatch actions
      expectTypeOf(storeWithLogger.dispatch).toBeCallableWith({
        type: 'INCREMENT'
      })

      expectTypeOf(storeWithLogger.dispatch)
        .parameter(0)
        .not.toMatchTypeOf(Promise.resolve({ type: 'INCREMENT' }))

      expectTypeOf(storeWithLogger.dispatch)
        .parameter(0)
        .not.toMatchTypeOf('not-an-action')
    })

    test('promise', () => {
      const storeWithPromise = createStore(reducer, applyMiddleware(promise()))

      // can dispatch actions and promises
      // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
      // do not work in this scenario.
      storeWithPromise.dispatch({ type: 'INCREMENT' })

      storeWithPromise.dispatch(Promise.resolve({ type: 'INCREMENT' }))

      expectTypeOf(storeWithPromise.dispatch)
        .parameter(0)
        .not.toMatchTypeOf('not-an-action')

      expectTypeOf(storeWithPromise.dispatch)
        .parameter(0)
        .not.toMatchTypeOf(Promise.resolve('not-an-action'))
    })

    test('promise + logger', () => {
      const storeWithPromiseAndLogger = createStore(
        reducer,
        applyMiddleware(promise(), logger())
      )

      // can dispatch actions and promises
      // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
      // do not work in this scenario.
      storeWithPromiseAndLogger.dispatch({ type: 'INCREMENT' })

      storeWithPromiseAndLogger.dispatch(Promise.resolve({ type: 'INCREMENT' }))

      expectTypeOf(storeWithPromiseAndLogger.dispatch)
        .parameter(0)
        .not.toMatchTypeOf('not-an-action')

      expectTypeOf(storeWithPromiseAndLogger.dispatch)
        .parameter(0)
        .not.toMatchTypeOf(Promise.resolve('not-an-action'))
    })

    test('promise + thunk', () => {
      const storeWithPromiseAndThunk = createStore(
        reducer,
        applyMiddleware(promise(), thunk<State, PromiseDispatch>(), logger())
      )

      // can dispatch actions, promises and thunks
      // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
      // do not work in this scenario.
      storeWithPromiseAndThunk.dispatch({ type: 'INCREMENT' })

      // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
      // do not work in this scenario.
      storeWithPromiseAndThunk.dispatch(Promise.resolve({ type: 'INCREMENT' }))

      storeWithPromiseAndThunk.dispatch((dispatch, getState) => {
        expectTypeOf(getState()).toHaveProperty('someField')

        expectTypeOf(getState()).not.toHaveProperty('wrongField')

        // injected dispatch accepts actions, thunks and promises
        // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
        // do not work in this scenario.
        dispatch({ type: 'INCREMENT' })

        // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
        // do not work in this scenario.
        dispatch(dispatch => dispatch({ type: 'INCREMENT' }))

        expectTypeOf(dispatch).toBeCallableWith(
          Promise.resolve({ type: 'INCREMENT' })
        )

        expectTypeOf(dispatch).parameter(0).not.toMatchTypeOf('not-an-action')
      })

      expectTypeOf(storeWithPromiseAndThunk.dispatch)
        .parameter(0)
        .not.toMatchTypeOf('not-an-action')

      expectTypeOf(storeWithPromiseAndThunk.dispatch)
        .parameter(0)
        .not.toMatchTypeOf(Promise.resolve('not-an-action'))
    })

    test('test variadic signature.', () => {
      const storeWithLotsOfMiddleware = createStore(
        reducer,
        applyMiddleware<PromiseDispatch>(
          promise(),
          logger(),
          logger(),
          logger(),
          logger(),
          logger()
        )
      )

      // `.toBeCallableWith or .parameter(0).toMatchTypeOf`
      // do not work in this scenario.
      storeWithLotsOfMiddleware.dispatch({ type: 'INCREMENT' })

      expectTypeOf(storeWithLotsOfMiddleware.dispatch).toBeCallableWith(
        Promise.resolve({ type: 'INCREMENT' })
      )
    })
  })
})

