import undoable from 'redux-undo'

const todo = (state, action) => {
  switch (action.type) {
    case 'ADD_TODO':
      return {
        id: action.id,
        text: action.text,
        completed: false
      }
    case 'TOGGLE_TODO':
      if (state.id !== action.id) {
        return state
      }

      return {
        ...state,
        completed: !state.completed
      }
    default:
      return state
  }
}

const todos = (state = [], action) => {
  switch (action.type) {
    case 'ADD_TODO':
      return [...state, todo(undefined, action)]
    case 'TOGGLE_TODO':
      return state.map(t => todo(t, action))
    default:
      return state
  }
}

const undoableTodos = undoable(todos)

export default undoableTodos

export default function generateTree() {
  let tree = {
    0: {
      id: 0,
      counter: 0,
      childIds: []
    }
  }

  for (let i = 1; i < 1000; i++) {
    let parentId = Math.floor(Math.pow(Math.random(), 2) * i)
    tree[i] = {
      id: i,
      counter: 0,
      childIds: []
    }
    tree[parentId].childIds.push(i)
  }

  return tree
}

export const INCREMENT = 'INCREMENT'
export const CREATE_NODE = 'CREATE_NODE'
export const DELETE_NODE = 'DELETE_NODE'
export const ADD_CHILD = 'ADD_CHILD'
export const REMOVE_CHILD = 'REMOVE_CHILD'

export const increment = nodeId => ({
  type: INCREMENT,
  nodeId
})

let nextId = 0
export const createNode = () => ({
  type: CREATE_NODE,
  nodeId: `new_${nextId++}`
})

export const deleteNode = nodeId => ({
  type: DELETE_NODE,
  nodeId
})

export const addChild = (nodeId, childId) => ({
  type: ADD_CHILD,
  nodeId,
  childId
})

export const removeChild = (nodeId, childId) => ({
  type: REMOVE_CHILD,
  nodeId,
  childId
})

import React from 'react'
import { shallow } from 'enzyme'
import ConnectedNode, { Node } from './Node'

function setup(id, counter, childIds, parentId) {
  const actions = {
    increment: jest.fn(),
    removeChild: jest.fn(),
    deleteNode: jest.fn(),
    createNode: jest.fn(),
    addChild: jest.fn()
  }

  const eventArgs = {
    preventDefault: jest.fn()
  }

  const component = shallow(
    <Node
      id={id}
      counter={counter}
      parentId={parentId}
      childIds={childIds}
      {...actions}
    />
  )

  return {
    component: component,
    removeLink: component.findWhere(n => n.type() === 'a' && n.contains('×')),
    addLink: component.findWhere(
      n => n.type() === 'a' && n.contains('Add child')
    ),
    button: component.find('button'),
    childNodes: component.find(ConnectedNode),
    actions: actions,
    eventArgs: eventArgs
  }
}

describe('Node component', () => {
  it('should display counter', () => {
    const { component } = setup(1, 23, [])
    expect(component.text()).toMatch(/^Counter: 23/)
  })

  it('should call increment on button click', () => {
    const { button, actions } = setup(1, 23, [])
    button.simulate('click')

    expect(actions.increment).toBeCalledWith(1)
  })

  it('should not render remove link', () => {
    const { removeLink } = setup(1, 23, [])
    expect(removeLink.length).toEqual(0)
  })

  it('should call createNode action on Add child click', () => {
    const { addLink, actions, eventArgs } = setup(2, 1, [])
    actions.createNode.mockReturnValue({ nodeId: 3 })
    addLink.simulate('click', eventArgs)

    expect(actions.createNode).toBeCalled()
  })

  it('should call addChild action on Add child click', () => {
    const { addLink, actions, eventArgs } = setup(2, 1, [])
    actions.createNode.mockReturnValue({ nodeId: 3 })

    addLink.simulate('click', eventArgs)

    expect(actions.addChild).toBeCalledWith(2, 3)
  })

  describe('when given childIds', () => {
    it('should render child nodes', () => {
      const { childNodes } = setup(1, 23, [2, 3])
      expect(childNodes.length).toEqual(2)
    })
  })

  describe('when given parentId', () => {
    it('should call removeChild action on remove link click', () => {
      const { removeLink, actions, eventArgs } = setup(2, 1, [], 1)
      removeLink.simulate('click', eventArgs)

      expect(actions.removeChild).toBeCalledWith(1, 2)
    })

    it('should call deleteNode action on remove link click', () => {
      const { removeLink, actions, eventArgs } = setup(2, 1, [], 1)
      removeLink.simulate('click', eventArgs)

      expect(actions.deleteNode).toBeCalledWith(2)
    })
  })
})

import React from 'react'
import { Component } from 'react'
import { connect } from 'react-redux'
import * as actions from '../actions'

export class Node extends Component {
  handleIncrementClick = () => {
    const { increment, id } = this.props
    increment(id)
  }

  handleAddChildClick = e => {
    e.preventDefault()

    const { addChild, createNode, id } = this.props
    const childId = createNode().nodeId
    addChild(id, childId)
  }

  handleRemoveClick = e => {
    e.preventDefault()

    const { removeChild, deleteNode, parentId, id } = this.props
    removeChild(parentId, id)
    deleteNode(id)
  }

  renderChild = childId => {
    const { id } = this.props
    return (
      <li key={childId}>
        <ConnectedNode id={childId} parentId={id} />
      </li>
    )
  }

  render() {
    const { counter, parentId, childIds } = this.props
    return (
      <div>
        Counter: {counter}{' '}
        <button onClick={this.handleIncrementClick}>+</button>{' '}
        {typeof parentId !== 'undefined' && (
          <a
            href="#"
            onClick={this.handleRemoveClick} // eslint-disable jsx-a11y/anchor-is-valid
            style={{ color: 'lightgray', textDecoration: 'none' }}
          >
            ×
          </a>
        )}
        <ul>
          {childIds.map(this.renderChild)}
          <li key="add">
            <a
              href="#" // eslint-disable jsx-a11y/anchor-is-valid
              onClick={this.handleAddChildClick}
            >
              Add child
            </a>
          </li>
        </ul>
      </div>
    )
  }
}

function mapStateToProps(state, ownProps) {
  return state[ownProps.id]
}

const ConnectedNode = connect(mapStateToProps, actions)(Node)
export default ConnectedNode

import {
  INCREMENT,
  ADD_CHILD,
  REMOVE_CHILD,
  CREATE_NODE,
  DELETE_NODE
} from '../actions'

const childIds = (state, action) => {
  switch (action.type) {
    case ADD_CHILD:
      return [...state, action.childId]
    case REMOVE_CHILD:
      return state.filter(id => id !== action.childId)
    default:
      return state
  }
}

const node = (state, action) => {
  switch (action.type) {
    case CREATE_NODE:
      return {
        id: action.nodeId,
        counter: 0,
        childIds: []
      }
    case INCREMENT:
      return {
        ...state,
        counter: state.counter + 1
      }
    case ADD_CHILD:
    case REMOVE_CHILD:
      return {
        ...state,
        childIds: childIds(state.childIds, action)
      }
    default:
      return state
  }
}

const getAllDescendantIds = (state, nodeId) =>
  state[nodeId].childIds.reduce(
    (acc, childId) => [...acc, childId, ...getAllDescendantIds(state, childId)],
    []
  )

const deleteMany = (state, ids) => {
  state = { ...state }
  ids.forEach(id => delete state[id])
  return state
}

export default (state = {}, action) => {
  const { nodeId } = action
  if (typeof nodeId === 'undefined') {
    return state
  }

  if (action.type === DELETE_NODE) {
    const descendantIds = getAllDescendantIds(state, nodeId)
    return deleteMany(state, [nodeId, ...descendantIds])
  }

  return {
    ...state,
    [nodeId]: node(state[nodeId], action)
  }
}

import deepFreeze from 'deep-freeze'
import reducer from './index'
import {
  increment,
  createNode,
  deleteNode,
  addChild,
  removeChild
} from '../actions'

describe('reducer', () => {
  it('should provide the initial state', () => {
    expect(reducer(undefined, {})).toEqual({})
  })

  it('should handle INCREMENT action', () => {
    const stateBefore = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: []
      }
    }
    const action = increment('node_0')
    const stateAfter = {
      node_0: {
        id: 'node_0',
        counter: 1,
        childIds: []
      }
    }

    deepFreeze(stateBefore)
    deepFreeze(action)

    expect(reducer(stateBefore, action)).toEqual(stateAfter)
  })

  it('should handle CREATE_NODE action', () => {
    const stateBefore = {}
    const action = createNode()
    const stateAfter = {
      [action.nodeId]: {
        id: action.nodeId,
        counter: 0,
        childIds: []
      }
    }

    deepFreeze(stateBefore)
    deepFreeze(action)

    expect(reducer(stateBefore, action)).toEqual(stateAfter)
  })

  it('should handle DELETE_NODE action', () => {
    const stateBefore = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: ['node_1']
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      },
      node_2: {
        id: 'node_2',
        counter: 0,
        childIds: ['node_3', 'node_4']
      },
      node_3: {
        id: 'node_3',
        counter: 0,
        childIds: []
      },
      node_4: {
        id: 'node_4',
        counter: 0,
        childIds: []
      }
    }
    const action = deleteNode('node_2')
    const stateAfter = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: ['node_1']
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      }
    }

    deepFreeze(stateBefore)
    deepFreeze(action)

    expect(reducer(stateBefore, action)).toEqual(stateAfter)
  })

  it('should handle ADD_CHILD action', () => {
    const stateBefore = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: []
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      }
    }
    const action = addChild('node_0', 'node_1')
    const stateAfter = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: ['node_1']
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      }
    }

    deepFreeze(stateBefore)
    deepFreeze(action)

    expect(reducer(stateBefore, action)).toEqual(stateAfter)
  })

  it('should handle REMOVE_CHILD action', () => {
    const stateBefore = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: ['node_1']
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      }
    }
    const action = removeChild('node_0', 'node_1')
    const stateAfter = {
      node_0: {
        id: 'node_0',
        counter: 0,
        childIds: []
      },
      node_1: {
        id: 'node_1',
        counter: 0,
        childIds: []
      }
    }

    deepFreeze(stateBefore)
    deepFreeze(action)

    expect(reducer(stateBefore, action)).toEqual(stateAfter)
  })
})

