        httpAgent: agent,
        maxRedirects: 0,
        proxy: false,
        signal: controller.signal,
        timeout: '0',
      })
      .then(
        () => null,
        (error) => error
      );

    try {
      await setTimeoutAsync(50);
      controller.abort();
      const error = await request;
      assert.strictEqual(error.code, AxiosError.ERR_CANCELED);
    } finally {
      controller.abort();
      agent.destroy();
    }
  });

