            response.end(body + '6789');
          });
        });
      },
      { port: PROXY_PORT }
    );
    proxy.on('connect', (req, sock) => {
      connectAttempts += 1;
      sock.end();
    });

    try {
      const response = await axios.get(`http://localhost:${server.address().port}/`, {
        proxy: {
          host: 'localhost',
          port: proxy.address().port,
        },
