  describe('HTTP2', () => {
    const createHttp2Axios = (baseURL) =>
      axios.create({
        baseURL,
        httpVersion: 2,
        http2Options: {
          rejectUnauthorized: false,
        },
      });

    it('should merge request http2Options with its instance config', async () => {
      const http2Axios = createHttp2Axios('https://localhost:8080');

      const { data } = await http2Axios.get('/', {
        http2Options: {
          foo: 'test',
        },
        adapter: async (config) => {
          return {
            data: config.http2Options,
          };
        },
      });

      assert.deepStrictEqual(data, {
        rejectUnauthorized: false,
        foo: 'test',
      });
    });

    it('should support http2 transport', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          res.end('OK');
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);
        const { data } = await http2Axios.get(localServerURL);
        assert.deepStrictEqual(data, 'OK');
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support request payload', async () => {
      const server = await startHTTPServer(null, {
        useHTTP2: true,
        port: SERVER_PORT,
      });

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);
        const payload = 'DATA';
        const { data } = await http2Axios.post(localServerURL, payload);
        assert.deepStrictEqual(data, payload);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should enforce maxBodyLength for HTTP/2 streamed uploads', async () => {
      let bytesReceived = 0;
      const server = await startHTTPServer(
        (req, res) => {
          req.on('data', (chunk) => {
            bytesReceived += chunk.length;
          });
          req.on('error', () => {});
          req.on('end', () => {
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({ received: bytesReceived }));
          });
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);
        const payload = Buffer.alloc(2 * 1024 * 1024, 0x63);
        const source = stream.Readable.from([payload]);

        await assert.rejects(
          http2Axios.post(localServerURL, source, {
            maxBodyLength: 1024,
            headers: { 'Content-Type': 'application/octet-stream' },
          }),
          (error) => {
            assert.strictEqual(error.message, 'Request body larger than maxBodyLength limit');
            assert.strictEqual(error.code, AxiosError.ERR_BAD_REQUEST);
            return true;
          }
        );

        assert.ok(
          bytesReceived <= 1024 * 4,
          `server should not receive full payload; got ${bytesReceived}`
        );
      } finally {
        if (server.closeAllSessions) {
          server.closeAllSessions();
        }
        await stopHTTPServer(server);
      }
    });

    it('should support FormData as a payload', async () => {
      if (typeof FormData !== 'function') {
        return;
      }

      const server = await startHTTPServer(
        async (req, res) => {
          const { fields, files } = await handleFormData(req);

          res.end(
            JSON.stringify({
              fields,
              files,
            })
          );
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);
        const form = new FormData();
        form.append('x', 'foo');
        form.append('y', 'bar');

        const { data } = await http2Axios.post(localServerURL, form);

        assert.deepStrictEqual(data, {
          fields: {
            x: ['foo'],
            y: ['bar'],
          },
          files: {},
        });
      } finally {
        await stopHTTPServer(server);
      }
    });

    describe('response types', () => {
      const originalData = '{"test": "OK"}';
      const fixtures = {
        text: (value) => assert.strictEqual(value, originalData),
        arraybuffer: (value) => assert.deepStrictEqual(value, Buffer.from(originalData)),
        stream: async (value) => assert.deepStrictEqual(await getStream(value), originalData),
        json: async (value) => assert.deepStrictEqual(value, JSON.parse(originalData)),
      };

      for (const [responseType, assertValue] of Object.entries(fixtures)) {
        it(`should support ${responseType} response type`, async () => {
          const server = await startHTTPServer(
            (req, res) => {
              res.end(originalData);
            },
            {
              useHTTP2: true,
              port: SERVER_PORT,
            }
          );

          try {
            const localServerURL = `https://localhost:${server.address().port}`;
            const http2Axios = createHttp2Axios(localServerURL);
            const { data } = await http2Axios.get(localServerURL, {
              responseType,
            });
            await assertValue(data);
          } finally {
            await stopHTTPServer(server);
          }
        });
      }
    });

    it('should support request timeout', async () => {
      let isAborted = false;
      let aborted;
      const promise = new Promise((resolve) => (aborted = resolve));

      const server = await startHTTPServer(
        (req, res) => {
          setTimeout(() => {
            res.end('OK');
          }, 15000);
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);

        server.on('stream', (http2Stream) => {
          http2Stream.once('aborted', () => {
            isAborted = true;
            aborted();
          });
        });

        await assert.rejects(async () => {
          await http2Axios.get(localServerURL, {
            timeout: 500,
          });
        }, /timeout/);

        await promise;
        assert.ok(isAborted);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support request cancellation', async () => {
      if (typeof AbortSignal !== 'function' || !AbortSignal.timeout) {
        return;
      }

      let isAborted = false;
      let aborted;
      const promise = new Promise((resolve) => (aborted = resolve));

      const server = await startHTTPServer(
        (req, res) => {
          setTimeout(() => {
            res.end('OK');
          }, 15000);
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);

        server.on('stream', (http2Stream) => {
          http2Stream.once('aborted', () => {
            isAborted = true;
            aborted();
          });
        });

        await assert.rejects(async () => {
          await http2Axios.get(localServerURL, {
            signal: AbortSignal.timeout(500),
          });
        }, /CanceledError: canceled/);

        await promise;
        assert.ok(isAborted);
      } finally {
        await stopHTTPServer(server);
      }
    });

    it('should support stream response cancellation', async () => {
      let isAborted = false;
      const source = axios.CancelToken.source();

      let aborted;
      const promise = new Promise((resolve) => (aborted = resolve));

      const server = await startHTTPServer(
        (req, res) => {
          generateReadable(10000, 100, 100).pipe(res);
        },
        {
          useHTTP2: true,
          port: SERVER_PORT,
        }
      );

      try {
        const localServerURL = `https://localhost:${server.address().port}`;
        const http2Axios = createHttp2Axios(localServerURL);

        server.on('stream', (http2Stream) => {
          http2Stream.once('aborted', () => {
            isAborted = true;
            aborted();
          });
        });

        const { data } = await http2Axios.get(localServerURL, {
          cancelToken: source.token,
          responseType: 'stream',
        });

        setTimeout(() => source.cancel());

        await assert.rejects(
          new Promise((resolve, reject) => {
            stream.pipeline(data, devNull(), (error) => {
              if (error) {
                reject(error);
                return;
              }

              resolve();
            });
          }),
          /CanceledError: canceled/
        );

        await promise;
        assert.ok(isAborted);
      } finally {
        await stopHTTPServer(server);
      }
    });

    describe('session', () => {
      // HTTP2 session tests are sensitive to cross-test port reuse: when one
      // test's server is torn down (closeAllSessions destroys h2 sessions),
      // a follow-up test binding the same port can observe a "Premature
      // close" on its own stream. Use ephemeral ports (port: 0, the default
      // from startHTTPServer) and a small retry budget as a backstop.
      it('should reuse session for the target authority', { retry: 2 }, async () => {
        const server = await startHTTPServer(
          (req, res) => {
            setTimeout(() => res.end('OK'), 1000);
          },
          {
            useHTTP2: true,
          }
        );

        try {
          const localServerURL = `https://localhost:${server.address().port}`;
          const http2Axios = createHttp2Axios(localServerURL);

          const [response1, response2] = await Promise.all([
            http2Axios.get(localServerURL, {
              responseType: 'stream',
            }),
            http2Axios.get(localServerURL, {
              responseType: 'stream',
            }),
          ]);

          assert.strictEqual(response1.data.session, response2.data.session);

          assert.deepStrictEqual(
            await Promise.all([getStream(response1.data), getStream(response2.data)]),
            ['OK', 'OK']
          );
        } finally {
          await stopHTTPServer(server);
        }
      });

      it('should use different sessions for different authorities', { retry: 2 }, async () => {
        const server = await startHTTPServer(
          (req, res) => {
            setTimeout(() => {
              res.end('OK');
            }, 2000);
          },
          {
            useHTTP2: true,
          }
        );

        const server2 = await startHTTPServer(
          (req, res) => {
            setTimeout(() => {
              res.end('OK');
            }, 2000);
          },
          {
            useHTTP2: true,
          }
        );

        try {
          const localServerURL = `https://localhost:${server.address().port}`;
          const localServerURL2 = `https://localhost:${server2.address().port}`;
          const http2Axios = createHttp2Axios(localServerURL);

          const [response1, response2] = await Promise.all([
            http2Axios.get(localServerURL, {
              responseType: 'stream',
            }),
            http2Axios.get(localServerURL2, {
              responseType: 'stream',
            }),
          ]);

          assert.notStrictEqual(response1.data.session, response2.data.session);

          assert.deepStrictEqual(
            await Promise.all([getStream(response1.data), getStream(response2.data)]),
            ['OK', 'OK']
          );
        } finally {
          await Promise.all([stopHTTPServer(server), stopHTTPServer(server2)]);
        }
      });

      it(
        'should use different sessions for requests with different http2Options set',
        { retry: 2 },
        async () => {
          const server = await startHTTPServer(
            (req, res) => {
              setTimeout(() => {
                res.end('OK');
              }, 1000);
            },
            {
              useHTTP2: true,
            }
          );

          try {
            const localServerURL = `https://localhost:${server.address().port}`;
            const http2Axios = createHttp2Axios(localServerURL);

            const [response1, response2] = await Promise.all([
              http2Axios.get(localServerURL, {
                http2Options: {
                  sessionTimeout: 2000,
                },
              }),
              http2Axios.get(localServerURL, {
                http2Options: {
                  sessionTimeout: 4000,
                },
              }),
            ]);

            assert.notStrictEqual(response1.request.session, response2.request.session);
            assert.deepStrictEqual([response1.data, response2.data], ['OK', 'OK']);
          } finally {
            await stopHTTPServer(server);
          }
        }
      );

      it(
        'should use the same session for request with the same resolved http2Options set',
        { retry: 2 },
        async () => {
          const server = await startHTTPServer(
            (req, res) => {
              setTimeout(() => res.end('OK'), 1000);
            },
            {
              useHTTP2: true,
            }
          );

          try {
            const localServerURL = `https://localhost:${server.address().port}`;
            const http2Axios = createHttp2Axios(localServerURL);

            const responses = await Promise.all([
              http2Axios.get(localServerURL, {
                responseType: 'stream',
              }),
              http2Axios.get(localServerURL, {
                responseType: 'stream',
                http2Options: undefined,
              }),
              http2Axios.get(localServerURL, {
                responseType: 'stream',
                http2Options: {},
              }),
            ]);

            assert.strictEqual(responses[1].data.session, responses[0].data.session);
            assert.strictEqual(responses[2].data.session, responses[0].data.session);

            assert.deepStrictEqual(
              await Promise.all(responses.map(({ data }) => getStream(data))),
              ['OK', 'OK', 'OK']
            );
          } finally {
            await stopHTTPServer(server);
          }
        }
      );

      it(
        'should use different sessions after previous session timeout',
        { retry: 2, timeout: 15000 },
        async () => {
          const server = await startHTTPServer(
            (req, res) => {
              setTimeout(() => res.end('OK'), 100);
            },
            {
              useHTTP2: true,
            }
          );

          try {
            const localServerURL = `https://localhost:${server.address().port}`;
            const http2Axios = createHttp2Axios(localServerURL);

            const response1 = await http2Axios.get(localServerURL, {
              responseType: 'stream',
              http2Options: {
                sessionTimeout: 1000,
              },
            });

            const session1 = response1.data.session;
            const data1 = await getStream(response1.data);

            await setTimeoutAsync(5000);

            const response2 = await http2Axios.get(localServerURL, {
              responseType: 'stream',
              http2Options: {
                sessionTimeout: 1000,
              },
            });

            const session2 = response2.data.session;
            const data2 = await getStream(response2.data);

            assert.notStrictEqual(session1, session2);
            assert.strictEqual(data1, 'OK');
            assert.strictEqual(data2, 'OK');
          } finally {
            await stopHTTPServer(server);
          }
        }
      );
    });
  });

  it('should not abort stream on settle rejection', async () => {
    const server = await startHTTPServer(
      (req, res) => {
        res.statusCode = 404;
        res.end('OK');
      },
      { port: SERVER_PORT }
    );

    try {
      let error;

      try {
        await axios.get(`http://localhost:${server.address().port}`, {
          responseType: 'stream',
        });
      } catch (err) {
        error = err;
      }

      assert.ok(error, 'request should be rejected');
      assert.strictEqual(await getStream(error.response.data), 'OK');
    } finally {
      await stopHTTPServer(server);
    }
  });

  it('should reject when only the request socket emits an error', async () => {
    const noop = () => {};
    const socket = new EventEmitter();
    socket.setKeepAlive = noop;
    socket.on('error', noop);

    const transport = {
      request() {
        return new (class MockRequest extends EventEmitter {
          constructor() {
            super();
            this.destroyed = false;
          }

          setTimeout() {}

          write() {}

          end() {
            this.emit('socket', socket);

            setImmediate(() => {
              socket.emit('error', Object.assign(new Error('write EPIPE'), { code: 'EPIPE' }));
            });
          }

          destroy(err) {
            if (this.destroyed) {
              return;
            }

            this.destroyed = true;
            err && this.emit('error', err);
            this.emit('close');
          }
        })();
      },
    };

    const error = await Promise.race([
      axios.post('http://example.com/', 'test', {
        transport,
        maxRedirects: 0,
      }),
      setTimeoutAsync(200).then(() => {
        throw new Error('socket error did not reject the request');
      }),
    ]).catch((err) => err);

    assert.ok(error instanceof AxiosError);
    assert.strictEqual(error.code, 'EPIPE');
    assert.strictEqual(error.message, 'write EPIPE');
  });

  describe('keep-alive', () => {
    it('should not emit MaxListenersExceededWarning under concurrent requests through a pooled keep-alive agent (regression #10780)', async () => {
      const server = await startHTTPServer(
        (req, res) => {
          // Small delay forces concurrent requests to queue on the single pooled socket.
          setTimeout(() => {
            res.writeHead(200, { 'Content-Type': 'text/plain' });
            res.end('ok');
          }, 5);
        },
        { port: SERVER_PORT }
      );

      const warnings = [];
      const warningHandler = (warning) => {
        if (warning && warning.name === 'MaxListenersExceededWarning') {
          warnings.push(warning);
        }
      };
      process.on('warning', warningHandler);

      const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });

      try {
        const baseURL = `http://localhost:${server.address().port}`;
        const CONCURRENCY = 30;

        const results = await Promise.all(
          Array.from({ length: CONCURRENCY }, (_, i) =>
            axios.get(`/req-${i}`, { baseURL, httpAgent: agent })
          )
        );

        assert.strictEqual(results.length, CONCURRENCY);
        for (const r of results) {
          assert.strictEqual(r.status, 200);
          assert.strictEqual(r.data, 'ok');
        }

        // Allow any deferred process 'warning' emissions to flush.
        await setTimeoutAsync(50);

        assert.strictEqual(
          warnings.length,
          0,
          `expected no MaxListenersExceededWarning, got ${warnings.length}: ${warnings.map((w) => w.message).join('; ')}`
        );

        // Inspect live sockets on the agent: none should have more than one
        // axios-installed error listener, regardless of how many requests ran.
        const allSockets = []
          .concat(...Object.values(agent.sockets || {}))
          .concat(...Object.values(agent.freeSockets || {}));
        for (const sock of allSockets) {
          assert.ok(
            sock.listenerCount('error') <= 2,
            `socket should have at most a couple of error listeners (agent + axios), got ${sock.listenerCount('error')}`
          );
        }
      } finally {
        process.removeListener('warning', warningHandler);
        agent.destroy();
        await stopHTTPServer(server);
      }
    }, 30000);

    it('should not leak memory via retained request closures under a long burst of keep-alive requests (regression #10780)', async () => {
      // This guards against stage88's report of OOM at ~480k sequential requests:
      // if the per-request closure leaked, heap would grow linearly. We simulate
      // a shorter burst and verify retained closures are released (via WeakRef
      // reachability check after GC, if exposed).
      if (typeof global.gc !== 'function') {
        // Skip when GC is not exposed (run with `node --expose-gc`).
        return;
      }

      const server = await startHTTPServer(
        (req, res) => {
          res.writeHead(200);
          res.end('ok');
        },
        { port: SERVER_PORT }
      );

      const agent = new http.Agent({ keepAlive: true, maxSockets: 4 });

      try {
        const baseURL = `http://localhost:${server.address().port}`;

        const refs = [];
        for (let i = 0; i < 200; i += 1) {
          // eslint-disable-next-line no-await-in-loop
          const response = await axios.get('/', { baseURL, httpAgent: agent });
          refs.push(new WeakRef(response.request));
        }

        // Drop strong refs and force GC.
        global.gc();
        await setTimeoutAsync(10);
        global.gc();

        const retained = refs.filter((r) => r.deref() !== undefined).length;
        // Some trailing requests may still be referenced in internal buffers.
        // The fix's correctness: retained count scales with agent socket count,
        // NOT with request count. A pre-fix leak would keep >>socket count.
        assert.ok(
          retained <= 20,
          `expected most request objects to be collectible after GC; ${retained}/200 retained suggests a closure leak`
        );
      } finally {
        agent.destroy();
        await stopHTTPServer(server);
      }
    }, 30000);

    it('should not fail with "socket hang up" when using timeouts', async () => {
      const server = await startHTTPServer(
        async (req, res) => {
          if (req.url === '/wait') {
            await new Promise((resolve) => setTimeout(resolve, 5000));
          }

          res.end('ok');
        },
        { port: SERVER_PORT }
      );

      try {
        const baseURL = `http://localhost:${server.address().port}`;
        await axios.get('/1', { baseURL, timeout: 1000 });
        await axios.get('/wait', { baseURL, timeout: 0 });
      } finally {
        await stopHTTPServer(server);
      }
    }, 15000);

    it('should install at most one socket error listener across reused keep-alive sockets', async () => {
      const noop = () => {};
      const socket = new EventEmitter();
      socket.setKeepAlive = noop;
      socket.on('error', noop);

      const baseErrorListenerCount = socket.listenerCount('error');

      const transport = {
        request(_, cb) {
          return new (class MockRequest extends EventEmitter {
            constructor() {
              super();
              this.destroyed = false;
            }

            setTimeout() {}

            write() {}

            end() {
              this.emit('socket', socket);

              setImmediate(() => {
                const response = stream.Readable.from(['ok']);
                response.statusCode = 200;
                response.headers = {};

                cb(response);
                this.emit('close');
              });
            }

            destroy(err) {
              if (this.destroyed) {
                return;
              }

              this.destroyed = true;
              err && this.emit('error', err);
              this.emit('close');
            }
          })();
        },
      };

      // First request: axios installs its single per-socket listener.
      await axios.get('http://example.com/first', {
        transport,
        maxRedirects: 0,
      });
      await setTimeoutAsync(0);
      assert.strictEqual(
        socket.listenerCount('error'),
        baseErrorListenerCount + 1,
        'axios should install exactly one socket error listener'
      );

      // Many subsequent requests reusing the same socket must not add more listeners.
      for (let i = 0; i < 20; i += 1) {
        // eslint-disable-next-line no-await-in-loop
        await axios.get(`http://example.com/next-${i}`, {
          transport,
          maxRedirects: 0,
        });
        // eslint-disable-next-line no-await-in-loop
        await setTimeoutAsync(0);
        assert.strictEqual(
          socket.listenerCount('error'),
          baseErrorListenerCount + 1,
          'listener count must stay constant across keep-alive reuse'
        );
      }
    });

    it('should not accumulate socket error listeners when a pooled socket is reassigned before the previous request closes (regression #10780)', async () => {
      const noop = () => {};
      const socket = new EventEmitter();
      socket.setKeepAlive = noop;
      socket.on('error', noop);

      const baseErrorListenerCount = socket.listenerCount('error');

      // Each request defers its 'close' emission so that the socket is
      // reassigned to the next request before the previous one closes.
      // This reproduces the race condition described in #10780.
      const pendingRequests = [];

      const transport = {
        request(_, cb) {
          const req = new (class MockRequest extends EventEmitter {
            constructor() {
              super();
              this.destroyed = false;
            }

            setTimeout() {}
            write() {}

            end() {
              // Share the single pooled socket across every request.
              this.emit('socket', socket);

              setImmediate(() => {
                const response = stream.Readable.from(['ok']);
                response.statusCode = 200;
                response.headers = {};
                cb(response);
                // Intentionally do NOT emit 'close' yet. Collect the req
                // so close can be emitted later, after other reqs have
                // already claimed the socket.
                pendingRequests.push(this);
              });
            }

            destroy(err) {
              if (this.destroyed) return;
              this.destroyed = true;
              err && this.emit('error', err);
              this.emit('close');
            }
          })();

          return req;
        },
      };

      const results = await Promise.all(
        Array.from({ length: 20 }, (_, i) =>
          axios.get(`http://example.com/concurrent-${i}`, {
            transport,
            maxRedirects: 0,
          })
        )
      );

      assert.strictEqual(results.length, 20);

      // Critical assertion: despite 20 concurrent requests all claiming the
      // same pooled socket before any emitted 'close', only ONE axios listener
      // must be attached. This is the difference between the pre-fix
      // behaviour (20 listeners, MaxListenersExceededWarning) and the fix.
      assert.strictEqual(
        socket.listenerCount('error'),
        baseErrorListenerCount + 1,
        `expected a single axios socket error listener under concurrent reuse, got ${socket.listenerCount('error') - baseErrorListenerCount}`
      );

      // Now drain the queued close events. Listener count must still be 1.
      for (const req of pendingRequests) {
        req.emit('close');
      }
      await setTimeoutAsync(0);

      assert.strictEqual(
        socket.listenerCount('error'),
        baseErrorListenerCount + 1,
        'listener must persist on the socket after requests close (cleanup is per-request ownership, not per-listener removal)'
      );
    });

    it('should route a socket error to the currently-active request after the socket has been reassigned', async () => {
      const noop = () => {};
      const socket = new EventEmitter();
      socket.setKeepAlive = noop;
      socket.on('error', noop);

      const createdReqs = [];

      // First transport: completes cleanly (emits response then close).
      const cleanTransport = {
        request(_, cb) {
          const emitter = new (class MockRequest extends EventEmitter {
            constructor() {
              super();
              this.destroyed = false;
              createdReqs.push(this);
            }
            setTimeout() {}
            write() {}
            end() {
              this.emit('socket', socket);
              setImmediate(() => {
                const response = stream.Readable.from(['ok']);
                response.statusCode = 200;
                response.headers = {};
                cb(response);
                this.emit('close');
              });
            }
            destroy(err) {
              if (this.destroyed) return;
              this.destroyed = true;
              err && this.emit('error', err);
              this.emit('close');
            }
          })();
          return emitter;
        },
      };

      // Second transport: emits socket error instead of a response.
      const errorTransport = {
        request() {
          const emitter = new (class MockRequest extends EventEmitter {
            constructor() {
              super();
              this.destroyed = false;
              createdReqs.push(this);
            }
            setTimeout() {}
            write() {}
            end() {
              this.emit('socket', socket);
              setImmediate(() => {
                socket.emit('error', Object.assign(new Error('boom'), { code: 'EPIPE' }));
              });
            }
            destroy(err) {
              if (this.destroyed) return;
              this.destroyed = true;
              err && this.emit('error', err);
              this.emit('close');
            }
          })();
          return emitter;
        },
      };

      // First request completes successfully; socket is released.
      await axios.get('http://example.com/first', { transport: cleanTransport, maxRedirects: 0 });
      await setTimeoutAsync(0);

      const firstReq = createdReqs[0];
      assert.ok(
        firstReq && firstReq.destroyed === false,
        'first request must not have been destroyed by a socket error'
      );

      // Stray socket error after first req has closed: must not destroy firstReq.
      socket.emit('error', new Error('stray error after close'));
      assert.strictEqual(
        firstReq.destroyed,
        false,
        'socket error after close must not destroy the old request'
      );

      // Second request claims the socket, then its socket errors. It should reject.
      const err = await axios
        .get('http://example.com/second', { transport: errorTransport, maxRedirects: 0 })
        .catch((e) => e);

      assert.ok(err instanceof AxiosError, 'second request should reject with an AxiosError');
      assert.strictEqual(err.code, 'EPIPE');

      const secondReq = createdReqs[1];
      assert.strictEqual(
        secondReq.destroyed,
        true,
        'second request should be destroyed by its own active socket error'
      );
    });
  });

  describe('redirect listener accumulation', () => {
    it('should not emit MaxListenersExceededWarning when a single request follows >= 11 redirects', async () => {
      const REDIRECT_COUNT = 11;

      const server = await startHTTPServer(
        (req, res) => {
          const match = req.url.match(/^\/redirect\/(\d+)$/);
          if (match) {
            const n = Number(match[1]);
            if (n < REDIRECT_COUNT) {
              res.writeHead(302, { Location: `/redirect/${n + 1}` });
            } else {
              res.writeHead(200, { 'Content-Type': 'application/json' });
              res.end(JSON.stringify({ redirects: n }));
              return;
            }
            res.end();
            return;
          }
          res.writeHead(302, { Location: '/redirect/1' });
          res.end();
        },
        { port: SERVER_PORT }
      );

      const warnings = [];
      const warningHandler = (warning) => {
        if (warning && warning.name === 'MaxListenersExceededWarning') {
          warnings.push(warning);
        }
      };
      process.on('warning', warningHandler);

      try {
        const baseURL = `http://localhost:${server.address().port}`;
        const response = await axios.get('/start', {
          baseURL,
          maxRedirects: REDIRECT_COUNT + 5,
        });

        assert.strictEqual(response.status, 200);
        assert.deepStrictEqual(response.data, { redirects: REDIRECT_COUNT });

        // Allow any deferred process 'warning' emissions to flush.
        await setTimeoutAsync(50);

        assert.strictEqual(
          warnings.length,
          0,
          `expected no MaxListenersExceededWarning across ${REDIRECT_COUNT} redirects, got ${warnings.length}: ${warnings.map((w) => w.message).join('; ')}`
        );
      } finally {
        process.removeListener('warning', warningHandler);
        await stopHTTPServer(server);
      }
    }, 30000);

    it('should attach at most one close listener to the outer request across a long redirect chain', async () => {
      const REDIRECT_COUNT = 20;
      const maxObservedCloseListeners = { value: 0 };

      const server = await startHTTPServer(
        (req, res) => {
          const match = req.url.match(/^\/r\/(\d+)$/);
          if (match) {
            const n = Number(match[1]);
            if (n < REDIRECT_COUNT) {
              res.writeHead(302, { Location: `/r/${n + 1}` });
            } else {
              res.writeHead(200);
              res.end('done');
              return;
            }
            res.end();
            return;
          }
          res.writeHead(302, { Location: '/r/1' });
          res.end();
        },
        { port: SERVER_PORT }
      );

      try {
        const baseURL = `http://localhost:${server.address().port}`;

        // Patch EventEmitter.prototype.on briefly to observe the peak close-listener
        // count on any emitter. The outer RedirectableRequest is the only target
        // that would accumulate listeners under the bug. Other emitters in the
        // process (server sockets, etc.) will also be observed but are irrelevant
        // as long as the peak stays within a small bound.
        const originalOn = EventEmitter.prototype.on;
        const originalOnce = EventEmitter.prototype.once;
        function record(eventName) {
          if (eventName === 'close') {
            const count = this.listenerCount('close');
            if (count > maxObservedCloseListeners.value) {
              maxObservedCloseListeners.value = count;
            }
          }
        }
        EventEmitter.prototype.on = function patchedOn(eventName, listener) {
          const res = originalOn.call(this, eventName, listener);
          record.call(this, eventName);
          return res;
        };
        EventEmitter.prototype.once = function patchedOnce(eventName, listener) {
          const res = originalOnce.call(this, eventName, listener);
          record.call(this, eventName);
          return res;
        };

        try {
          const response = await axios.get('/start', {
            baseURL,
            maxRedirects: REDIRECT_COUNT + 5,
          });
          assert.strictEqual(response.status, 200);
        } finally {
          EventEmitter.prototype.on = originalOn;
          EventEmitter.prototype.once = originalOnce;
        }

        // Pre-fix: peak would be >= REDIRECT_COUNT (one axios close listener per hop
        // on the outer RedirectableRequest). Post-fix: axios attaches exactly one
        // close listener to the outer request; framework internals typically add
        // a couple more. A generous bound of 10 distinguishes the behaviours.
        assert.ok(
          maxObservedCloseListeners.value < 10,
          `close listener count should stay below 10 across ${REDIRECT_COUNT} redirects, peak was ${maxObservedCloseListeners.value}`
        );
      } finally {
        await stopHTTPServer(server);
      }
    }, 30000);
  });

  describe('socketPath security', () => {
    function makeSocketPath() {
      const pipe = `axios-socketpath-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}`;

      return os.platform() === 'win32'
        ? `\\\\.\\pipe\\${pipe}`
        : path.join(os.tmpdir(), `${pipe}.sock`);
    }

    function startUnixServer(socketPath) {
      return new Promise((resolveStart, rejectStart) => {
        const server = http.createServer((req, res) => {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ ok: true, url: req.url }));
        });
        try {
          fs.unlinkSync(socketPath);
        } catch (_) {
          /* noop */
        }
        server.once('error', rejectStart);
        server.listen(socketPath, () => resolveStart(server));
      });
    }

    function stopUnixServer(server, socketPath) {
      return new Promise((done) => {
        server.close(() => {
          try {
            fs.unlinkSync(socketPath);
          } catch (_) {
            /* noop */
          }
          done();
        });
      });
    }

    it('allows socketPath when no allowedSocketPaths is set (backwards compatible)', async () => {
      const socketPath = makeSocketPath();
      const server = await startUnixServer(socketPath);
      try {
        const res = await axios.get('http://localhost/echo', { socketPath });
        assert.strictEqual(res.status, 200);
        assert.strictEqual(res.data.ok, true);
      } finally {
        await stopUnixServer(server, socketPath);
      }
    });

    it('allows socketPath when it matches an allowedSocketPaths string', async () => {
      const socketPath = makeSocketPath();
      const server = await startUnixServer(socketPath);
      try {
        const res = await axios.get('http://localhost/echo', {
          socketPath,
          allowedSocketPaths: socketPath,
        });
        assert.strictEqual(res.status, 200);
      } finally {
        await stopUnixServer(server, socketPath);
      }
    });

    it('allows socketPath when it matches an entry in allowedSocketPaths array', async () => {
      const socketPath = makeSocketPath();
      const server = await startUnixServer(socketPath);
      try {
        const res = await axios.get('http://localhost/echo', {
          socketPath,
          allowedSocketPaths: ['/var/run/does-not-exist.sock', socketPath],
        });
        assert.strictEqual(res.status, 200);
      } finally {
        await stopUnixServer(server, socketPath);
      }
    });

    it('rejects socketPath not in allowedSocketPaths', async () => {
      await assert.rejects(
        axios.get('http://localhost/echo', {
          socketPath: '/var/run/docker.sock',
          allowedSocketPaths: ['/tmp/allowed.sock'],
        }),
        (err) => {
          assert.ok(err instanceof AxiosError);
          assert.strictEqual(err.code, AxiosError.ERR_BAD_OPTION_VALUE);
          assert.match(err.message, /allowedSocketPaths/);
          return true;
        }
      );
    });

    it('rejects socketPath attempting path traversal that escapes allowlist', async () => {
      const allowedDir = path.join(os.tmpdir(), 'axios-allowed');
      const allowed = path.join(allowedDir, 'app.sock');
      await assert.rejects(
        axios.get('http://localhost/echo', {
          socketPath: path.join(allowedDir, '..', 'other.sock'),
          allowedSocketPaths: [allowed],
        }),
        (err) => {
          assert.strictEqual(err.code, AxiosError.ERR_BAD_OPTION_VALUE);
          return true;
        }
      );
    });

    it('treats relative and absolute allowedSocketPaths entries equivalently', async () => {
      const socketPath = makeSocketPath();
      const server = await startUnixServer(socketPath);
      try {
        const relative = path.relative(process.cwd(), socketPath);
        const res = await axios.get('http://localhost/echo', {
          socketPath,
          allowedSocketPaths: [relative],
        });
        assert.strictEqual(res.status, 200);
      } finally {
        await stopUnixServer(server, socketPath);
      }
    });

    it('rejects non-string socketPath', async () => {
      await assert.rejects(axios.get('http://localhost/echo', { socketPath: 12345 }), (err) => {
        assert.ok(err instanceof AxiosError);
        assert.strictEqual(err.code, AxiosError.ERR_BAD_OPTION_VALUE);
        assert.match(err.message, /socketPath must be a string/);
        return true;
      });
    });

    it('empty allowedSocketPaths array blocks all socketPath values', async () => {
      await assert.rejects(
        axios.get('http://localhost/echo', {
          socketPath: '/tmp/anything.sock',
          allowedSocketPaths: [],
        }),
        (err) => {
          assert.strictEqual(err.code, AxiosError.ERR_BAD_OPTION_VALUE);
          return true;
        }
      );
    });
  });
});

import { beforeEach, describe, it } from 'vitest';
import assert from 'assert';
import adapters from '../../../lib/adapters/adapters.js';

describe('adapters', () => {
  const store = { ...adapters.adapters };

  beforeEach(() => {
    Object.keys(adapters.adapters).forEach((name) => {
      delete adapters.adapters[name];
    });

    Object.assign(adapters.adapters, store);
  });

  it('should support loading by fn handle', () => {
    const adapter = () => {};
    assert.strictEqual(adapters.getAdapter(adapter), adapter);
  });

  it('should support loading by name', () => {
    const adapter = () => {};
    adapters.adapters.testadapter = adapter;
    assert.strictEqual(adapters.getAdapter('testAdapter'), adapter);
  });

  it('should detect adapter unavailable status', () => {
    adapters.adapters.testadapter = null;
    assert.throws(() => adapters.getAdapter('testAdapter'), /is not available in the build/);
  });

  it('should detect adapter unsupported status', () => {
    adapters.adapters.testadapter = false;
    assert.throws(() => adapters.getAdapter('testAdapter'), /is not supported by the environment/);
  });

  it('should pick suitable adapter from the list', () => {
    const adapter = () => {};

    Object.assign(adapters.adapters, {
      foo: false,
      bar: null,
      baz: adapter,
    });

    assert.strictEqual(adapters.getAdapter(['foo', 'bar', 'baz']), adapter);
  });
});

import { describe, it, expect } from 'vitest';
import AxiosError from '../../../lib/core/AxiosError.js';
import validator from '../../../lib/helpers/validator.js';

describe('validator::assertOptions', () => {
  it('should throw only if unknown an option was passed', () => {
    let error;
    try {
      validator.assertOptions(
        {
          x: true,
        },
        {
          y: validator.validators.boolean,
        }
      );
    } catch (err) {
      error = err;
    }
    expect(error).toBeInstanceOf(AxiosError);
    expect(error.message).toBe('Unknown option x');
    expect(error.code).toBe(AxiosError.ERR_BAD_OPTION);

    expect(() => {
      validator.assertOptions(
        {
          x: true,
        },
        {
          x: validator.validators.boolean,
          y: validator.validators.boolean,
        }
      );
    }).not.toThrow(new Error('Unknown option x'));
  });

  it("should throw TypeError only if option type doesn't match", () => {
    let error;
    try {
      validator.assertOptions(
        {
          x: 123,
        },
        {
          x: validator.validators.boolean,
        }
      );
    } catch (err) {
      error = err;
    }
    expect(error).toBeInstanceOf(AxiosError);
    expect(error.message).toBe('option x must be a boolean');
    expect(error.code).toBe(AxiosError.ERR_BAD_OPTION_VALUE);

    expect(() => {
      validator.assertOptions(
        {
          x: true,
        },
        {
          x: validator.validators.boolean,
          y: validator.validators.boolean,
        }
      );
    }).not.toThrow();
  });
});

import { describe, it, expect, vi } from 'vitest';
import buildURL, { encode } from '../../../lib/helpers/buildURL.js';

describe('helpers::buildURL', () => {
  it('should support null params', () => {
    expect(buildURL('/foo')).toEqual('/foo');
  });

  it('should support params', () => {
    expect(
      buildURL('/foo', {
        foo: 'bar',
        isUndefined: undefined,
        isNull: null,
      })
    ).toEqual('/foo?foo=bar');
  });

  it('should support sending raw params to custom serializer func', () => {
    const serializer = vi.fn().mockReturnValue('foo=bar');
    const params = { foo: 'bar' };
    const options = {
      serialize: serializer,
    };
    expect(
      buildURL(
        '/foo',
        {
          foo: 'bar',
        },
        options
      )
    ).toEqual('/foo?foo=bar');
    expect(serializer).toHaveBeenCalledTimes(1);
    expect(serializer).toHaveBeenCalledWith(params, options);
  });

  it('should support object params', () => {
    expect(
      buildURL('/foo', {
        foo: {
          bar: 'baz',
        },
      })
    ).toEqual('/foo?foo%5Bbar%5D=baz');
  });

  it('should support date params', () => {
    const date = new Date();

    expect(
      buildURL('/foo', {
        date,
      })
    ).toEqual('/foo?date=' + date.toISOString());
  });

  it('should support array params with encode', () => {
    expect(
      buildURL('/foo', {
        foo: ['bar', 'baz'],
      })
    ).toEqual('/foo?foo%5B%5D=bar&foo%5B%5D=baz');
  });

  it('should support special char params', () => {
    expect(
      buildURL('/foo', {
        foo: ':$, ',
      })
    ).toEqual('/foo?foo=:$,+');
  });

  it('should support existing params', () => {
    expect(
      buildURL('/foo?foo=bar', {
        bar: 'baz',
      })
    ).toEqual('/foo?foo=bar&bar=baz');
  });

  it('should support "length" parameter', () => {
    expect(
      buildURL('/foo', {
        query: 'bar',
        start: 0,
        length: 5,
      })
    ).toEqual('/foo?query=bar&start=0&length=5');
  });

  it('should correct discard url hash mark', () => {
    expect(
      buildURL('/foo?foo=bar#hash', {
        query: 'baz',
      })
    ).toEqual('/foo?foo=bar&query=baz');
  });

  it('should support URLSearchParams', () => {
    expect(buildURL('/foo', new URLSearchParams('bar=baz'))).toEqual('/foo?bar=baz');
  });

  it('should support custom serialize function', () => {
    const params = {
      x: 1,
    };

    const options = {
      serialize: (thisParams, thisOptions) => {
        expect(thisParams).toEqual(params);
        expect(thisOptions).toEqual(options);
        return 'rendered';
      },
    };

    expect(buildURL('/foo', params, options)).toEqual('/foo?rendered');

    const customSerializer = (thisParams) => {
      expect(thisParams).toEqual(params);
      return 'rendered';
    };

    expect(buildURL('/foo', params, customSerializer)).toEqual('/foo?rendered');
  });

  it('should ignore inherited serializer options', () => {
    let serializeInvoked = false;
    let encodeInvoked = false;

    Object.defineProperty(Object.prototype, 'serialize', {
      value() {
        serializeInvoked = true;
        return 'inherited=1';
      },
      configurable: true,
    });
    Object.defineProperty(Object.prototype, 'encode', {
      value() {
        encodeInvoked = true;
        return 'inherited';
      },
      configurable: true,
    });

    try {
      expect(buildURL('/foo', { value: 'a b' }, {})).toEqual('/foo?value=a+b');
      expect(serializeInvoked).toBe(false);
      expect(encodeInvoked).toBe(false);
    } finally {
      delete Object.prototype.serialize;
      delete Object.prototype.encode;
    }
  });
});

describe('helpers::encode', () => {
  it('should be exported as a named export', () => {
    expect(typeof encode).toBe('function');
  });

  it('should leave plain ASCII unchanged', () => {
    expect(encode('foo')).toEqual('foo');
  });

  it('should preserve `:` rather than percent-encoding it', () => {
    expect(encode(':')).toEqual(':');
  });

  it('should preserve `$` rather than percent-encoding it', () => {
    expect(encode('$')).toEqual('$');
  });

  it('should preserve `,` rather than percent-encoding it', () => {
    expect(encode(',')).toEqual(',');
  });

  it('should encode space as `+` (form-style) rather than `%20`', () => {
    expect(encode(' ')).toEqual('+');
  });

  it('should still percent-encode characters outside the preserved set', () => {
    expect(encode('a/b')).toEqual('a%2Fb');
    expect(encode('a&b')).toEqual('a%26b');
    expect(encode('a=b')).toEqual('a%3Db');
  });

  it('should apply all substitutions together', () => {
    expect(encode('a:b$c,d e')).toEqual('a:b$c,d+e');
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import shouldBypassProxy from '../../../lib/helpers/shouldBypassProxy.js';

const originalNoProxy = process.env.no_proxy;
const originalNOProxy = process.env.NO_PROXY;

const setNoProxy = (value) => {
  process.env.no_proxy = value;
  process.env.NO_PROXY = value;
};

afterEach(() => {
  if (originalNoProxy === undefined) {
    delete process.env.no_proxy;
  } else {
    process.env.no_proxy = originalNoProxy;
  }

  if (originalNOProxy === undefined) {
    delete process.env.NO_PROXY;
  } else {
    process.env.NO_PROXY = originalNOProxy;
  }
});

describe('helpers::shouldBypassProxy', () => {
  it('should bypass proxy for localhost with a trailing dot', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://localhost.:8080/')).toBe(true);
  });

  it('should bypass proxy for bracketed ipv6 loopback', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should support bracketed ipv6 entries in no_proxy', () => {
    setNoProxy('[::1]');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should bypass proxy for 127.0.0.1 when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://127.0.0.1:7777/')).toBe(true);
  });

  it('should bypass proxy for [::1] when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://[::1]:7777/')).toBe(true);
  });

  it('should bypass proxy for localhost when no_proxy contains 127.0.0.1', () => {
    setNoProxy('127.0.0.1');

    expect(shouldBypassProxy('http://localhost:7777/')).toBe(true);
  });

  it('should bypass proxy for localhost when no_proxy contains ::1', () => {
    setNoProxy('::1');

    expect(shouldBypassProxy('http://localhost:7777/')).toBe(true);
  });

  it('should bypass proxy for 0.0.0.0 when no_proxy contains a local entry', () => {
    for (const entry of ['localhost', '127.0.0.1', '::1']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://0.0.0.0:7777/')).toBe(true);
    }
  });

  it('should respect explicit ports for 0.0.0.0 local matching', () => {
    setNoProxy('localhost:8080');

    expect(shouldBypassProxy('http://0.0.0.0:8080/')).toBe(true);
    expect(shouldBypassProxy('http://0.0.0.0:9090/')).toBe(false);
  });

  it('should bypass proxy for the IPv6 unspecified address symmetrically with 0.0.0.0', () => {
    for (const entry of ['localhost', '127.0.0.1', '::1']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://[::]:7777/')).toBe(true);
      expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:0]:7777/')).toBe(true);
    }
  });

  it('should bypass proxy for compressed IPv6 unspecified request forms', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    for (const host of ['0::', '::0', '0:0::', '::0:0', '0::0']) {
      expect(shouldBypassProxy(`http://[${host}]:7777/`)).toBe(true);
    }
  });

  it('should bypass proxy for compressed IPv6 unspecified no_proxy entries', () => {
    for (const entry of ['0::', '::0', '0:0::', '::0:0', '0::0']) {
      setNoProxy(entry);

      expect(shouldBypassProxy('http://[::]:7777/')).toBe(true);
      expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:0]:7777/')).toBe(true);
    }
  });

  it('should respect explicit ports on compressed IPv6 unspecified no_proxy entries', () => {
    setNoProxy('[0::]:8080');

    expect(shouldBypassProxy('http://[::]:8080/')).toBe(true);
    expect(shouldBypassProxy('http://[::]:9090/')).toBe(false);
  });

  it('should not treat nonzero compressed IPv6 addresses as unspecified', () => {
    setNoProxy('0::2');

    expect(shouldBypassProxy('http://[::]:7777/')).toBe(false);
  });

  it('should still route a real public IPv6 host through the proxy', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://[2001:db8::1]:7777/')).toBe(false);
  });

  it('should match wildcard and explicit ports', () => {
    setNoProxy('*.example.com,localhost:8080');

    expect(shouldBypassProxy('http://api.example.com/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:8080/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:8081/')).toBe(false);
  });

  it('should bypass proxy for any host when no_proxy is *', () => {
    setNoProxy('*');

    expect(shouldBypassProxy('http://example.com/')).toBe(true);
    expect(shouldBypassProxy('http://localhost:1234/')).toBe(true);
    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
  });

  it('should support bracketed ipv6 with explicit port in no_proxy', () => {
    setNoProxy('[::1]:8080');

    expect(shouldBypassProxy('http://[::1]:8080/')).toBe(true);
    expect(shouldBypassProxy('http://[::1]:8081/')).toBe(false);
  });

  it('should not bypass when no_proxy is empty', () => {
    setNoProxy('');

    expect(shouldBypassProxy('http://localhost:8080/')).toBe(false);
  });

  it('should not bypass for malformed URLs', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('not a url')).toBe(false);
  });

  it('should bypass proxy for 127.0.0.0/8 subnet when no_proxy contains 127.0.0.1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://127.0.0.2:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.0.0.100:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.1.2.3:9191/secret')).toBe(true);
    expect(shouldBypassProxy('http://127.255.255.254:9191/secret')).toBe(true);
  });

  it('should bypass proxy for 127.0.0.0/8 subnet when no_proxy contains localhost', () => {
    setNoProxy('localhost');

    expect(shouldBypassProxy('http://127.0.0.2:7777/')).toBe(true);
    expect(shouldBypassProxy('http://127.1.2.3:7777/')).toBe(true);
  });

  it('should NOT bypass for non-loopback IPv4 addresses', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://128.0.0.1:9191/')).toBe(false);
    expect(shouldBypassProxy('http://126.255.255.255:9191/')).toBe(false);
    expect(shouldBypassProxy('http://10.0.0.1:9191/')).toBe(false);
    expect(shouldBypassProxy('http://192.168.1.1:9191/')).toBe(false);
  });

  it('should NOT treat malformed 127-prefixed values as loopback', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    // bracketed IPv6 that happens to contain 127 dotted-form must not match IPv4 loopback
    expect(shouldBypassProxy('http://example.com/')).toBe(false);
  });

  it('should bypass proxy for full-form IPv6 loopback 0:0:0:0:0:0:0:1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[0:0:0:0:0:0:0:1]:8080/')).toBe(true);
  });

  it('should bypass proxy for IPv4-mapped IPv6 loopback ::ffff:127.0.0.1', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://[::ffff:127.0.0.1]:8080/')).toBe(true);
  });

  it('should treat 127.x.x.x as cross-equivalent to localhost and ::1', () => {
    setNoProxy('::1');

    expect(shouldBypassProxy('http://127.0.0.5:7777/')).toBe(true);
  });

  it('should still respect explicit port mismatch on no_proxy entries', () => {
    setNoProxy('127.0.0.1:8080');

    // same-port → bypass via cross-loopback equivalence
    expect(shouldBypassProxy('http://127.0.0.2:8080/')).toBe(true);
    // different port → no bypass
    expect(shouldBypassProxy('http://127.0.0.2:9090/')).toBe(false);
  });

  it('should not bypass for hosts that merely contain 127 in other octets', () => {
    setNoProxy('localhost,127.0.0.1,::1');

    expect(shouldBypassProxy('http://10.0.0.127:8080/')).toBe(false);
    expect(shouldBypassProxy('http://200.127.0.1:8080/')).toBe(false);
  });

  // IPv4-mapped IPv6 normalization: an attacker (or naive caller) can use the
  // IPv4-mapped IPv6 representation of an address (e.g. ::ffff:192.168.1.5)
  // to dodge a NO_PROXY policy expressed in IPv4 form, or vice-versa. After
  // canonicalising both sides, equivalent addresses compare equal.
  describe('IPv4-mapped IPv6 normalization', () => {
    it('should bypass via IPv4-mapped IPv6 request when NO_PROXY uses the IPv4 form', () => {
      setNoProxy('192.168.1.5');

      expect(shouldBypassProxy('http://[::ffff:192.168.1.5]/')).toBe(true);
    });

    it('should bypass via Node-normalised IPv4-mapped hex request against an IPv4 NO_PROXY', () => {
      // Node's URL parser canonicalises [::ffff:192.168.1.5] → [::ffff:c0a8:105].
      // The hex form must unmap to 192.168.1.5 to match the entry.
      setNoProxy('192.168.1.5');

      expect(shouldBypassProxy('http://[::ffff:c0a8:105]/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses the IPv4-mapped IPv6 dotted form', () => {
      setNoProxy('::ffff:192.168.1.5');

      expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses the IPv4-mapped IPv6 hex form', () => {
      setNoProxy('::ffff:a00:1');

      expect(shouldBypassProxy('http://10.0.0.1/')).toBe(true);
    });

    it('should bypass via plain IPv4 request when NO_PROXY uses a bracketed IPv4-mapped IPv6 entry', () => {
      setNoProxy('[::ffff:192.168.1.5]');

      expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
    });

    it('should treat the uncompressed 0:0:0:0:0:ffff:<v4> form as equivalent', () => {
      setNoProxy('0:0:0:0:0:ffff:10.0.0.1');

      expect(shouldBypassProxy('http://10.0.0.1/')).toBe(true);
      expect(shouldBypassProxy('http://[::ffff:10.0.0.1]/')).toBe(true);
    });

    it('should treat compressed zero-prefix IPv4-mapped IPv6 dotted forms as equivalent', () => {
      for (const entry of [
        '0::ffff:192.168.1.5',
        '0:0::ffff:192.168.1.5',
        '0:0:0::ffff:192.168.1.5',
        '0:0:0:0::ffff:192.168.1.5',
      ]) {
        setNoProxy(entry);

        expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
      }
    });

    it('should treat compressed zero-prefix IPv4-mapped IPv6 hex forms as equivalent', () => {
      for (const entry of [
        '0::ffff:c0a8:105',
        '0:0::ffff:c0a8:105',
        '0:0:0::ffff:c0a8:105',
        '0:0:0:0::ffff:c0a8:105',
      ]) {
        setNoProxy(entry);

        expect(shouldBypassProxy('http://192.168.1.5/')).toBe(true);
      }
    });

    it('should support compressed bracketed IPv4-mapped IPv6 entries with explicit ports', () => {
      setNoProxy('[0:0::ffff:192.168.1.5]:8080');

      expect(shouldBypassProxy('http://192.168.1.5:8080/')).toBe(true);
      expect(shouldBypassProxy('http://192.168.1.5:9090/')).toBe(false);
    });

    it('should NOT cross-match unrelated addresses', () => {
      setNoProxy('192.168.1.5');

      // Different IPv4 address inside an IPv4-mapped form must not bypass.
      expect(shouldBypassProxy('http://[::ffff:192.168.1.6]/')).toBe(false);
      // Non-mapped IPv6 must not be treated as IPv4.
      expect(shouldBypassProxy('http://[2001:db8::1]/')).toBe(false);
    });

    it('should leave non-mapped IPv6 addresses comparing as IPv6', () => {
      setNoProxy('2001:db8::1');

      expect(shouldBypassProxy('http://[2001:db8::1]/')).toBe(true);
      expect(shouldBypassProxy('http://[2001:db8::2]/')).toBe(false);
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { EventEmitter } from 'events';
import http2 from 'http2';
import Http2Sessions from '../../../lib/helpers/Http2Sessions.js';

function createFakeSession() {
  const session = new EventEmitter();
  session.destroyed = false;
  session.closed = false;
  session.close = vi.fn(() => {
    session.closed = true;
    session.emit('close');
  });
  const originalRequest = vi.fn(() => {
    const stream = new EventEmitter();
    stream.endStream = vi.fn();
    return stream;
  });
  session.request = originalRequest;
  session._originalRequest = originalRequest;
  return session;
}

describe('helpers::Http2Sessions', () => {
  let connectSpy;
  let pool;

  beforeEach(() => {
    connectSpy = vi.spyOn(http2, 'connect').mockImplementation(() => createFakeSession());
    pool = new Http2Sessions();
  });

  afterEach(() => {
    connectSpy.mockRestore();
    vi.useRealTimers();
  });

  it('reuses a cached session for the same authority and options', () => {
    const a = pool.getSession('https://example.test', { sessionTimeout: 1000 });
    const b = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    expect(a).toBe(b);
    expect(connectSpy).toHaveBeenCalledTimes(1);
  });

  it('creates a separate session for a different authority', () => {
    pool.getSession('https://example.test');
    pool.getSession('https://other.test');

    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('creates a new session when options differ for the same authority', () => {
    pool.getSession('https://example.test', { sessionTimeout: 1000 });
    pool.getSession('https://example.test', { sessionTimeout: 5000 });

    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('does not reuse a destroyed session', () => {
    const first = pool.getSession('https://example.test');
    first.destroyed = true;

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('does not reuse a closed session', () => {
    const first = pool.getSession('https://example.test');
    first.closed = true;

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('drops a session from the pool when its close event fires', () => {
    const first = pool.getSession('https://example.test');
    first.emit('close');

    const second = pool.getSession('https://example.test');

    expect(second).not.toBe(first);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('keeps unrelated authorities cached when one session closes', () => {
    const first = pool.getSession('https://example.test');
    const other = pool.getSession('https://other.test');
    first.emit('close');

    const otherAgain = pool.getSession('https://other.test');

    expect(otherAgain).toBe(other);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('closes and removes the session after sessionTimeout once the last stream ends', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const stream = session.request();
    stream.emit('close');

    expect(session.closed).toBe(false);

    vi.advanceTimersByTime(1000);

    expect(session.close).toHaveBeenCalledTimes(1);

    const next = pool.getSession('https://example.test', { sessionTimeout: 1000 });
    expect(next).not.toBe(session);
    expect(connectSpy).toHaveBeenCalledTimes(2);
  });

  it('cancels the pending sessionTimeout when a new stream opens', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const first = session.request();
    first.emit('close');

    session.request();
    vi.advanceTimersByTime(5000);

    expect(session.close).not.toHaveBeenCalled();
  });

  it('keeps the session alive while streams are still open', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const a = session.request();
    const b = session.request();
    a.emit('close');

    vi.advanceTimersByTime(5000);

    expect(session.close).not.toHaveBeenCalled();

    b.emit('close');
    vi.advanceTimersByTime(1000);

    expect(session.close).toHaveBeenCalledTimes(1);
  });

  it('defaults sessionTimeout to 1000ms when no options are passed', () => {
    vi.useFakeTimers();
    const session = pool.getSession('https://example.test');

    const stream = session.request();
    stream.emit('close');

    vi.advanceTimersByTime(999);
    expect(session.close).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1);
    expect(session.close).toHaveBeenCalledTimes(1);
  });

  it('installs a request wrapper when sessionTimeout is set', () => {
    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    expect(session.request).not.toBe(session._originalRequest);
  });

  it('does not install the request wrapper when sessionTimeout is null', () => {
    const session = pool.getSession('https://example.test', { sessionTimeout: null });

    expect(session.request).toBe(session._originalRequest);
  });

  it('cancels the pending idle timer when the session itself closes', () => {
    vi.useFakeTimers();
    const clearTimeoutSpy = vi.spyOn(globalThis, 'clearTimeout');

    const session = pool.getSession('https://example.test', { sessionTimeout: 1000 });

    const stream = session.request();
    stream.emit('close');
    // An idle-removal timer is now pending.

    clearTimeoutSpy.mockClear();
    session.emit('close');

    // Closing the session must cancel the pending idle timer; otherwise it
    // keeps Node's event loop refed for up to sessionTimeout ms past close.
    expect(clearTimeoutSpy).toHaveBeenCalled();
  });
});

import { describe, it, expect } from 'vitest';
import parseHeaders from '../../../lib/helpers/parseHeaders.js';

describe('helpers::parseHeaders', () => {
  it('should parse headers', () => {
    const date = new Date();
    const parsed = parseHeaders(
      'Date: ' +
        date.toISOString() +
        '\n' +
        'Content-Type: application/json\n' +
        'Connection: keep-alive\n' +
        'Transfer-Encoding: chunked'
    );

    expect(parsed.date).toEqual(date.toISOString());
    expect(parsed['content-type']).toEqual('application/json');
    expect(parsed.connection).toEqual('keep-alive');
    expect(parsed['transfer-encoding']).toEqual('chunked');
  });

  it('should use array for set-cookie', () => {
    const parsedZero = parseHeaders('');
    const parsedSingle = parseHeaders('Set-Cookie: key=val;');
    const parsedMulti = parseHeaders('Set-Cookie: key=val;\n' + 'Set-Cookie: key2=val2;\n');

    expect(parsedZero['set-cookie']).toBeUndefined();
    expect(parsedSingle['set-cookie']).toEqual(['key=val;']);
    expect(parsedMulti['set-cookie']).toEqual(['key=val;', 'key2=val2;']);
  });

  it('should handle duplicates', () => {
    const parsed = parseHeaders(
      'Age: age-a\n' +
        'Age: age-b\n' +
        'Foo: foo-a\n' +
        'Foo: foo-b\n'
    );

    expect(parsed.age).toEqual('age-a');
    expect(parsed.foo).toEqual('foo-a, foo-b');
  });
});

