    expect(result).toEqual([true, 123]);
  });

  it('should support spread', async () => {
    let fulfilled = false;
    const result = await axios.all([123, 456]).then(
      axios.spread((a, b) => {
        expect(a + b).toBe(123 + 456);
        fulfilled = true;
        return 'hello world';
      })
    );

    expect(fulfilled).toBe(true);
    expect(result).toBe('hello world');
  });
});

