let requests = [];
let OriginalXMLHttpRequest;

const sleep = (ms = 0) => new Promise((resolve) => setTimeout(resolve, ms));

const waitForRequest = async (timeoutMs = 1000) => {
  const start = Date.now();

  while (Date.now() - start < timeoutMs) {
    const request = requests.at(-1);
    if (request) {
      return request;
    }

    await sleep(0);
  }

  throw new Error('Expected an XHR request to be sent');
};

describe('adapter (vitest browser)', () => {
  beforeEach(() => {
    requests = [];
    OriginalXMLHttpRequest = window.XMLHttpRequest;
    window.XMLHttpRequest = MockXMLHttpRequest;
  });

  afterEach(() => {
    window.XMLHttpRequest = OriginalXMLHttpRequest;
    axios.interceptors.request.handlers = [];
    axios.interceptors.response.handlers = [];
  });

  it('should support custom adapter', async () => {
    const responsePromise = axios('/foo', {
      adapter(config) {
        return new Promise((resolve) => {
          const request = new XMLHttpRequest();
          request.open('GET', '/bar');

          request.onreadystatechange = function onReadyStateChange() {
            resolve({
              config,
              request,
            });
          };

          request.send(null);
        });
      },
    });

    const request = await waitForRequest();
    expect(request.url).toBe('/bar');

    request.respondWith();
    await responsePromise;
  });

  it('should execute adapter code synchronously', async () => {
    let asyncFlag = false;

    const responsePromise = axios('/foo', {
      adapter(config) {
        return new Promise((resolve) => {
          const request = new XMLHttpRequest();
          request.open('GET', '/bar');

          request.onreadystatechange = function onReadyStateChange() {
            resolve({
              config,
              request,
            });
          };

          expect(asyncFlag).toBe(false);
          request.send(null);
        });
      },
    });

    asyncFlag = true;

    const request = await waitForRequest();
    request.respondWith();
    await responsePromise;
  });

  it('should execute adapter code asynchronously when interceptor is present', async () => {
    let asyncFlag = false;

    axios.interceptors.request.use((config) => {
      config.headers.async = 'async it!';
      return config;
    });

    const responsePromise = axios('/foo', {
      adapter(config) {
        return new Promise((resolve) => {
          const request = new XMLHttpRequest();
          request.open('GET', '/bar');

          request.onreadystatechange = function onReadyStateChange() {
            resolve({
              config,
              request,
            });
          };

          expect(asyncFlag).toBe(true);
          request.send(null);
        });
      },
    });

    asyncFlag = true;

    const request = await waitForRequest();
    request.respondWith();
    await responsePromise;
  });

  it('should sanitize request headers containing CRLF characters', async () => {
    const responsePromise = axios('/foo', {
      headers: {
        'x-test': '\tok\r\nInjected: yes ',
      },
    });

    const request = await waitForRequest();

    expect(request.requestHeaders['x-test']).toBe('okInjected: yes');
    expect(request.requestHeaders.Injected).toBeUndefined();

    request.respondWith();
    await responsePromise;
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import axios from '../../index.js';

class MockXMLHttpRequest {
  constructor() {
    this.requestHeaders = {};
    this.responseHeaders = {};
    this.readyState = 0;
    this.status = 0;
    this.statusText = '';
    this.responseText = '';
    this.response = null;
    this.timeout = 0;
    this.withCredentials = false;
    this.onreadystatechange = null;
    this.onloadend = null;
    this.onabort = null;
    this.onerror = null;
    this.ontimeout = null;
    this._listeners = {};
    this._uploadListeners = {};
    this.upload = {
      addEventListener: (type, listener) => {
        this._uploadListeners[type] ||= [];
        this._uploadListeners[type].push(listener);
      },
    };
  }

  open(method, url, async = true) {
    this.method = method;
    this.url = url;
    this.async = async;
  }

  setRequestHeader(key, value) {
    this.requestHeaders[key] = value;
  }

  addEventListener(type, listener) {
    this._listeners[type] ||= [];
    this._listeners[type].push(listener);
  }

  getAllResponseHeaders() {
    return Object.entries(this.responseHeaders)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\n');
  }

  send(data) {
    this.params = data;
    this.readyState = 1;
    requests.push(this);
  }

  getListenerCount(type, target = 'request') {
    const listeners = target === 'upload' ? this._uploadListeners : this._listeners;
    return listeners[type]?.length || 0;
  }

  emit(type, target = 'request', event = {}) {
    const listeners = target === 'upload' ? this._uploadListeners : this._listeners;
    (listeners[type] || []).forEach((listener) => listener(event));
  }

  respondWith({
    status = 200,
    statusText = 'OK',
    responseText = '',
    response = null,
    headers = {},
  } = {}) {
    this.status = status;
    this.statusText = statusText;
    this.responseText = responseText;
    this.response = response;
    this.responseHeaders = headers;
    this.readyState = 4;

    this.emit('progress', 'request', {
      loaded: responseText.length,
      total: responseText.length,
      lengthComputable: true,
    });

    queueMicrotask(() => {
      if (this.onloadend) {
        this.onloadend();
      } else if (this.onreadystatechange) {
        this.onreadystatechange();
      }
    });
  }
}

let requests = [];
let OriginalXMLHttpRequest;

