let requests = [];
let OriginalXMLHttpRequest;

const waitForRequest = async (timeoutMs = 1000) => {
  const start = Date.now();

  while (Date.now() - start < timeoutMs) {
    const request = requests.at(-1);
    if (request) {
      return request;
    }

    await Promise.resolve();
  }

  throw new Error('Expected an XHR request to be sent');
};

describe('cancel (vitest browser)', () => {
  beforeEach(() => {
    requests = [];
    OriginalXMLHttpRequest = window.XMLHttpRequest;
    window.XMLHttpRequest = MockXMLHttpRequest;
  });

  afterEach(() => {
    window.XMLHttpRequest = OriginalXMLHttpRequest;
  });

  describe('when called before sending request', () => {
    it('rejects Promise with a CanceledError object', async () => {
      const source = axios.CancelToken.source();
      source.cancel('Operation has been canceled.');

      const error = await axios
        .get('/foo', {
          cancelToken: source.token,
        })
        .catch((thrown) => thrown);

      expect(axios.isCancel(error)).toBe(true);
      expect(error.message).toBe('Operation has been canceled.');
      expect(requests).toHaveLength(0);
    });
  });

  describe('when called after request has been sent', () => {
    it('rejects Promise with a CanceledError object', async () => {
      const source = axios.CancelToken.source();
      const promise = axios.get('/foo/bar', {
        cancelToken: source.token,
      });

      const request = await waitForRequest();

      // Call cancel() after the request has been sent, but before response is received.
      source.cancel('Operation has been canceled.');
      request.respondWith({
        status: 200,
        responseText: 'OK',
      });

      const error = await promise.catch((thrown) => thrown);

      expect(axios.isCancel(error)).toBe(true);
      expect(error.message).toBe('Operation has been canceled.');
    });

    it('calls abort on request object', async () => {
      const source = axios.CancelToken.source();
      const promise = axios.get('/foo/bar', {
        cancelToken: source.token,
      });

      const request = await waitForRequest();

      // Call cancel() after the request has been sent, but before response is received.
      source.cancel();

      await promise.catch(() => undefined);

      expect(request.statusText).toBe('abort');
    });
  });

  it('supports cancellation using AbortController signal', async () => {
    const controller = new AbortController();
    const promise = axios.get('/foo/bar', {
      signal: controller.signal,
    });

    const request = await waitForRequest();

    // Call abort() after the request has been sent, but before response is received.
    controller.abort();
    setTimeout(() => {
      request.respondWith({
        status: 200,
        responseText: 'OK',
      });
    }, 0);

    const error = await promise.catch((thrown) => thrown);
    expect(axios.isCancel(error)).toBe(true);
  });

  describe('listener cleanup on error paths', () => {
    for (const { label, trigger } of [
      { label: 'network error', trigger: (r) => r.onerror(new Error('Network Error')) },
      { label: 'timeout', trigger: (r) => r.ontimeout() },
      { label: 'browser abort', trigger: (r) => r.onabort() },
    ]) {
      it(`unsubscribes cancelToken listener after ${label}`, async () => {
        const source = axios.CancelToken.source();
        const promise = axios
          .get('/foo/bar', { cancelToken: source.token })
          .catch((thrown) => thrown);

        const request = await waitForRequest();
        trigger(request);
        await promise;

        expect(source.token._listeners || []).toEqual([]);
      });
    }

    it('removes AbortSignal listener after network error', async () => {
      const controller = new AbortController();
      let listenerCount = 0;
      const nativeAdd = controller.signal.addEventListener.bind(controller.signal);
      const nativeRemove = controller.signal.removeEventListener.bind(controller.signal);
      controller.signal.addEventListener = (type, fn, options) => {
        if (type === 'abort') listenerCount++;
        return nativeAdd(type, fn, options);
      };
      controller.signal.removeEventListener = (type, fn, options) => {
        if (type === 'abort') listenerCount--;
        return nativeRemove(type, fn, options);
      };

      const promise = axios
        .get('/foo/bar', { signal: controller.signal })
        .catch((thrown) => thrown);

      const request = await waitForRequest();
      request.onerror(new Error('Network Error'));
      await promise;

      expect(listenerCount).toBe(0);
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import axios from '../../index.js';

class MockXMLHttpRequest {
  constructor() {
    this.requestHeaders = {};
    this.responseHeaders = {};
    this.readyState = 0;
    this.status = 0;
    this.statusText = '';
    this.responseText = '';
    this.response = null;
    this.responseURL = '';
    this.timeout = 0;
    this.withCredentials = false;
    this.onreadystatechange = null;
    this.onloadend = null;
    this.onabort = null;
    this.onerror = null;
    this.ontimeout = null;
    this.upload = {
      addEventListener() {},
    };
  }

  open(method, url, async = true) {
    this.method = method;
    this.url = url;
    this.async = async;
  }

  setRequestHeader(key, value) {
    this.requestHeaders[key] = value;
  }

  addEventListener() {}

  getAllResponseHeaders() {
    if (typeof this.responseHeaders === 'string') {
      return this.responseHeaders;
    }

    return Object.entries(this.responseHeaders)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\n');
  }

  send(data) {
    this.params = data;
    requests.push(this);
    this.readyState = 1;
  }

  respondWith({
    status = 200,
    statusText = 'OK',
    responseText = '',
    response = null,
    responseHeaders = {},
    headers = {},
    responseURL = '',
  } = {}) {
    this.status = status;
    this.statusText = statusText;
    this.responseText = responseText;
    this.response = response === null ? responseText : response;
    this.responseHeaders = Object.keys(headers).length ? headers : responseHeaders;
    this.responseURL = responseURL;
    this.readyState = 4;
    this.finish();
  }

  responseTimeout() {
    if (this.ontimeout) {
      this.ontimeout();
    }
  }

  failNetworkError(message = 'Network Error') {
    if (this.onerror) {
      this.onerror({ message });
    }
  }

  abort() {
    if (this.onabort) {
      this.onabort();
    }
  }

  finish() {
    queueMicrotask(() => {
      if (this.onloadend) {
        this.onloadend();
      } else if (this.onreadystatechange) {
        this.onreadystatechange();
      }
    });
  }
}

let requests = [];
let OriginalXMLHttpRequest;

const sleep = (ms = 0) => new Promise((resolve) => setTimeout(resolve, ms));

const waitForRequest = async (timeoutMs = 1000) => {
  const start = Date.now();

  while (Date.now() - start < timeoutMs) {
    const request = requests.at(-1);
    if (request) {
      return request;
    }

    await sleep(0);
  }

  throw new Error('Expected an XHR request to be sent');
};

describe('interceptors (vitest browser)', () => {
  beforeEach(() => {
    requests = [];
    OriginalXMLHttpRequest = window.XMLHttpRequest;
    window.XMLHttpRequest = MockXMLHttpRequest;
  });

  afterEach(() => {
    window.XMLHttpRequest = OriginalXMLHttpRequest;
    axios.interceptors.request.handlers = [];
    axios.interceptors.response.handlers = [];
    vi.restoreAllMocks();
  });

  it('should add a request interceptor (asynchronous by default)', async () => {
    let asyncFlag = false;

    axios.interceptors.request.use((config) => {
      config.headers.test = 'added by interceptor';
      expect(asyncFlag).toBe(true);
      return config;
    });

    const responsePromise = axios('/foo');
    asyncFlag = true;

    const request = await waitForRequest();
    expect(request.requestHeaders.test).toBe('added by interceptor');
    request.respondWith();
    await responsePromise;
  });

  it('should add a request interceptor (explicitly flagged as asynchronous)', async () => {
    let asyncFlag = false;

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'added by interceptor';
        expect(asyncFlag).toBe(true);
        return config;
      },
      null,
      { synchronous: false }
    );

    const responsePromise = axios('/foo');
    asyncFlag = true;

    const request = await waitForRequest();
    expect(request.requestHeaders.test).toBe('added by interceptor');
    request.respondWith();
    await responsePromise;
  });

  it('should add a request interceptor that is executed synchronously when flag is provided', async () => {
    let asyncFlag = false;

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'added by synchronous interceptor';
        expect(asyncFlag).toBe(false);
        return config;
      },
      null,
      { synchronous: true }
    );

    const responsePromise = axios('/foo');
    asyncFlag = true;

    const request = await waitForRequest();
    expect(request.requestHeaders.test).toBe('added by synchronous interceptor');
    request.respondWith();
    await responsePromise;
  });

  it('should execute asynchronously when not all interceptors are explicitly flagged as synchronous', async () => {
    let asyncFlag = false;

    axios.interceptors.request.use((config) => {
      config.headers.foo = 'uh oh, async';
      expect(asyncFlag).toBe(true);
      return config;
    });

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'added by synchronous interceptor';
        expect(asyncFlag).toBe(true);
        return config;
      },
      null,
      { synchronous: true }
    );

    axios.interceptors.request.use((config) => {
      config.headers.test = 'added by the async interceptor';
      expect(asyncFlag).toBe(true);
      return config;
    });

    const responsePromise = axios('/foo');
    asyncFlag = true;

    const request = await waitForRequest();
    expect(request.requestHeaders.foo).toBe('uh oh, async');
    expect(request.requestHeaders.test).toBe('added by synchronous interceptor');
    request.respondWith();
    await responsePromise;
  });

  it('should execute request interceptor in legacy order', async () => {
    let sequence = '';

    axios.interceptors.request.use((config) => {
      sequence += '1';
      return config;
    });

    axios.interceptors.request.use((config) => {
      sequence += '2';
      return config;
    });

    axios.interceptors.request.use((config) => {
      sequence += '3';
      return config;
    });

    const responsePromise = axios({ url: '/foo' });
    const request = await waitForRequest();

    expect(sequence).toBe('321');
    request.respondWith();
    await responsePromise;
  });

  it('should execute request interceptor in order', async () => {
    let sequence = '';

    axios.interceptors.request.use((config) => {
      sequence += '1';
      return config;
    });

    axios.interceptors.request.use((config) => {
      sequence += '2';
      return config;
    });

    axios.interceptors.request.use((config) => {
      sequence += '3';
      return config;
    });

    const responsePromise = axios({
      url: '/foo',
      transitional: {
        legacyInterceptorReqResOrdering: false,
      },
    });
    const request = await waitForRequest();

    expect(sequence).toBe('123');
    request.respondWith();
    await responsePromise;
  });

  it('runs the interceptor if runWhen function is provided and resolves to true', async () => {
    const onGetCall = (config) => config.method === 'get';

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'special get headers';
        return config;
      },
      null,
      { runWhen: onGetCall }
    );

    const responsePromise = axios('/foo');
    const request = await waitForRequest();

    expect(request.requestHeaders.test).toBe('special get headers');
    request.respondWith();
    await responsePromise;
  });

  it('does not run the interceptor if runWhen function is provided and resolves to false', async () => {
    const onPostCall = (config) => config.method === 'post';

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'special get headers';
        return config;
      },
      null,
      { runWhen: onPostCall }
    );

    const responsePromise = axios('/foo');
    const request = await waitForRequest();

    expect(request.requestHeaders.test).toBeUndefined();
    request.respondWith();
    await responsePromise;
  });

  it('does not run async interceptor if runWhen resolves to false (and runs synchronously)', async () => {
    let asyncFlag = false;
    const onPostCall = (config) => config.method === 'post';

    axios.interceptors.request.use(
      (config) => {
        config.headers.test = 'special get headers';
        return config;
      },
      null,
      { synchronous: false, runWhen: onPostCall }
    );

    axios.interceptors.request.use(
      (config) => {
        config.headers.sync = 'hello world';
        expect(asyncFlag).toBe(false);
        return config;
      },
      null,
      { synchronous: true }
    );

    const responsePromise = axios('/foo');
    asyncFlag = true;

    const request = await waitForRequest();
    expect(request.requestHeaders.test).toBeUndefined();
    expect(request.requestHeaders.sync).toBe('hello world');
    request.respondWith();
    await responsePromise;
  });

  it('should call request onRejected when interceptor throws', async () => {
    const rejectedSpy = vi.fn();
    const error = new Error('deadly error');

    axios.interceptors.request.use(
      () => {
        throw error;
      },
      rejectedSpy,
      { synchronous: true }
    );

    const responsePromise = axios('/foo').catch(() => {});
    const request = await waitForRequest();
    request.respondWith();
    await responsePromise;

    expect(rejectedSpy).toHaveBeenCalledWith(error);
  });

  it('should add a request interceptor that returns a new config object', async () => {
    axios.interceptors.request.use(() => ({
      url: '/bar',
      method: 'post',
    }));

    const responsePromise = axios('/foo');
    const request = await waitForRequest();

    expect(request.method).toBe('POST');
    expect(request.url).toBe('/bar');
    request.respondWith();
    await responsePromise;
  });

  it('should add a request interceptor that returns a promise', async () => {
    axios.interceptors.request.use((config) =>
      new Promise((resolve) => {
        setTimeout(() => {
          config.headers.async = 'promise';
          resolve(config);
        }, 100);
      })
