import fs from 'node:fs';
import axios from 'axios';
import { printSuccessMessage, printErrorMessage, printInfoMessage } from './utils.js';

/**
 * Special configuration for processing sponsor data.
 */
const config = {
  legacyAgreements: {
    Stytch: 'gold',
    Airbnb: 'silver',
    Descope: 'gold',
    'Principal Financial Group': 'gold',
  },
  sponsorsToIgnore: ['axios'],
  additionalSponsors: [
    {
      name: 'superluxuryreps',
      imageUrl: 'https://images.opencollective.com/superluxuryreps/378b62f/avatar.png',
      description: 'super luxury reps',
      tier: 'silver',
      slug: 'superluxuryreps',
      website:
        'https://superluxuryreps.com/?utm_source=axios_docs_website&utm_medium=website&utm_campaign=axios_open_collective_sponsorship',
      twitter: null,
      active: true,
    },
  ],
};

/**
 * The GraphQL query to get all sponsors.
 *
 * @type {string}
 */
const getAllSponsorsQuery = `
query Account {
  account(githubHandle: "https://github.com/axios") {
    name
    slug
    members(role: BACKER) {
      totalCount
      nodes {
        account {
          name
          slug
          socialLinks {
            type
            url
            createdAt
            updatedAt
          }
          website
          imageUrl
          legalName
          description
        }
        tier {
          name
        }
        totalDonations {
          value
          currency
        }
        since
      }
    }
  }
}
`;

/**
 * The GraphQL query to get all active sponsors.
 *
 * @type {string}
 */
const getActiveSponsorsQuery = `
query Account {
  account(githubHandle: "https://github.com/axios") {
    orders(onlyActiveSubscriptions: true, onlySubscriptions: true, frequency: MONTHLY, status: ACTIVE) {
      totalCount
      nodes {
        tier {
          name
        }
        fromAccount {
          id
          name
          socialLinks {
            type
            url
          }
          imageUrl
          legalName
          description
          website
          slug
        }
        amount {
          currency
          value
        }
        totalDonations {
          value
          currency
        }
      }
    }
  }
}
`;

/**
 * Gets all sponsors.
 *
 * @returns {Promise<any>} The sponsors.
 */
const getAllSponsors = async () => {
  printInfoMessage('getting all sponsors...');
  const response = await axios.post('https://api.opencollective.com/graphql/v2', {
    query: getAllSponsorsQuery,
  });

  return response.data.data;
};

/**
 * Gets all active sponsors.
 *
 * @returns {Promise<any>} The active sponsors.
 */
const getActiveSponsors = async () => {
  printInfoMessage('getting active sponsors...');
  const response = await axios.post('https://api.opencollective.com/graphql/v2', {
    query: getActiveSponsorsQuery,
  });

  return response.data.data;
};

/**
 * Builds a URL with UTM parameters.
 *
 * @param {string} url - The URL to build.
 * @param {boolean} bypass - Whether to bypass UTM parameters.
 * @returns {string} The URL with UTM parameters.
 */
const buildLinks = (url, bypass = false) => {
  if (bypass) {
    return url;
  }

  try {
    const urlObject = new URL(url);

    const { searchParams } = urlObject;

    searchParams.set('utm_source', 'axios_docs_website');
    searchParams.set('utm_medium', 'website');
    searchParams.set('utm_campaign', 'axios_open_collective_sponsorship');

    return urlObject.toString();
  } catch {
    return url;
  }
};

/**
 * Formats all active sponsors.
 *
 * @param {any} sponsorsData - The sponsors data.
 * @returns {any} The formatted sponsor data.
 */
const formatActiveSponsorData = (sponsorsData) => {
  const getSponsorTier = (sponsor) => {
    if (config.legacyAgreements[sponsor.fromAccount.name]) {
      return config.legacyAgreements[sponsor.fromAccount.name];
    }

    if (sponsor.tier?.name.toLowerCase() === 'silver sponsor') {
      return 'silver';
    }

    return sponsor.tier?.name.toLowerCase() || 'backer';
  };

  const processedData = sponsorsData
    .map((sponsor) => ({
      name: sponsor.fromAccount.name ?? 'Backer',
      imageUrl: sponsor.fromAccount.imageUrl ?? null,
      description: sponsor.fromAccount.description ?? null,
      tier: getSponsorTier(sponsor),
      slug: sponsor.fromAccount.slug,
      website: sponsor.fromAccount.website
        ? buildLinks(sponsor.fromAccount.website)
        : (buildLinks(
            sponsor.fromAccount.socialLinks.find((link) => link.type === 'WEBSITE')?.url
          ) ?? null),
      twitter:
        buildLinks(sponsor.fromAccount.socialLinks.find((link) => link.type === 'TWITTER')?.url) ??
        null,
    }))
    .filter((sponsor) => !config.sponsorsToIgnore.includes(sponsor.name));

  return processedData;
};

/**
 * Formats all sponsors irrespective state.
 *
 * @param {any} sponsorsData - The sponsors data.
 * @returns {any} The formatted sponsor data.
 */
const formatAllSponsorData = (sponsorsData) => {
  const getSponsorTier = (sponsor) => {
    if (config.legacyAgreements[sponsor.account.name]) {
      return config.legacyAgreements[sponsor.account.name];
    }

    if (sponsor.tier?.name.toLowerCase() === 'silver sponsor') {
      return 'silver';
    }

    return sponsor.tier?.name.toLowerCase() || 'backer';
  };

  const processedData = sponsorsData
    .map((sponsor) => ({
      name: sponsor.account.name ?? 'Backer',
      imageUrl: sponsor.account.imageUrl ?? null,
      description: sponsor.account.description ?? null,
      tier: getSponsorTier(sponsor),
      slug: sponsor.account.slug,
      website: sponsor.account.website
        ? buildLinks(sponsor.account.website)
        : (buildLinks(sponsor.account.socialLinks.find((link) => link.type === 'WEBSITE')?.url) ??
          null),
      twitter:
        buildLinks(sponsor.account.socialLinks.find((link) => link.type === 'TWITTER')?.url) ??
        null,
    }))
    .filter((sponsor) => !config.sponsorsToIgnore.includes(sponsor.name));

  return processedData;
};

/**
 * The main process.
 */
const mainProcess = async () => {
  try {
    const allSponsors = await getAllSponsors();
    const activeSponsors = await getActiveSponsors();
    const allSponsorsProcessedData = formatAllSponsorData(allSponsors.account.members.nodes);
    const activeSponsorsProcessedData = formatActiveSponsorData(
      activeSponsors.account.orders.nodes
    );

    const sponsorsByTier = {};

    for (const sponsor of allSponsorsProcessedData) {
      sponsorsByTier[sponsor.tier] ||= [];

      const isActiveSponsor = activeSponsorsProcessedData.find(
        (activeSponsor) => activeSponsor.slug === sponsor.slug
      );

      if (isActiveSponsor) {
        sponsorsByTier[sponsor.tier].push({
          ...sponsor,
          active: true,
        });
      } else {
        sponsorsByTier[sponsor.tier].push({
          ...sponsor,
          active: false,
        });
      }
    }

    for (const sponsor of activeSponsorsProcessedData) {
      const isSponsorInAllSponsors = allSponsorsProcessedData.find(
        (allSponsor) => allSponsor.slug === sponsor.slug
      );

      if (!isSponsorInAllSponsors) {
        if (!sponsorsByTier[sponsor.tier]) {
          sponsorsByTier[sponsor.tier] ||= [];
        }

        sponsorsByTier[sponsor.tier].push({
          ...sponsor,
          active: true,
        });
      }
    }

    for (const additionalSponsor of config.additionalSponsors) {
      if (!sponsorsByTier[additionalSponsor.tier]) {
        sponsorsByTier[additionalSponsor.tier] ||= [];
      }

      sponsorsByTier[additionalSponsor.tier].push({
        ...additionalSponsor,
        active: true,
      });
    }

    fs.writeFileSync('./data/sponsors.json', JSON.stringify(sponsorsByTier, null, 2));

    printSuccessMessage('processed sponsors successfully!');
  } catch (_) {
    printErrorMessage('failed to process sponsors!');
    console.error(_);
  }
};

await mainProcess();

import chalk from 'chalk';

export const printSuccessMessage = (message) => {
  console.log(chalk.green('Success:'), `${message}`);
};

export const printInfoMessage = (message) => {
  console.log(chalk.blue('Info:'), `${message}`);
};

export const printErrorMessage = (message) => {
  console.log(chalk.red('Error:'), `${message}`);
};

import axios from '../index.js';

const URL = 'http://127.0.0.1:3000/api';
const BODY = {
  foo: 'bar',
  baz: 1234,
};

function handleSuccess(data) {
  console.log(data);
}
function handleFailure(data) {
  console.log('error', data);
}

// GET
axios.get(URL, { params: BODY }).then(handleSuccess).catch(handleFailure);

// POST
axios.post(URL, BODY).then(handleSuccess).catch(handleFailure);

import fs from 'fs';
import path from 'path';
import http from 'http';

let server;

/**
 * Pipes a file to the HTTP response.
 *
 * @param {http.ServerResponse} res - The HTTP response object.
 * @param {string} file - The relative path to the file to be served.
 * @param {string} [type] - Optional MIME type for the response.
 */
function pipeFileToResponse(res, file, type) {
  if (type) {
    res.writeHead(200, {
      'Content-Type': type,
    });
  }

  fs.createReadStream(path.join(path.resolve(), 'sandbox', file)).pipe(res);
}

/**
 * Handles API requests to /api.
 *
 * Collects request data, parses it as JSON, and returns a JSON response
 * containing the request URL, method, headers, and parsed data.
 *
 * @param {http.IncomingMessage} req - The HTTP request object.
 * @param {http.ServerResponse} res - The HTTP response object.
 */
function handleApiRequest(req, res) {
  let status;
  let result;
  let data = '';

  req.on('data', (chunk) => {
    data += chunk;
  });

  req.on('end', () => {
    try {
      status = 200;
      result = {
        url: req.url,
        data: data ? JSON.parse(data) : undefined,
        method: req.method,
        headers: req.headers,
      };
    } catch (e) {
      console.error('Error:', e.message);
      status = 400;
      result = {
        error: e.message,
      };
    }

    res.writeHead(status, {
      'Content-Type': 'application/json',
    });
    res.end(JSON.stringify(result));
  });
}

/**
 * Handles incoming HTTP requests.
 *
 * Serves static files like index.html and axios.js, or routes API requests to
 * handleApiRequest. Responds with 404 for unrecognized paths.
 *
 * @param {http.IncomingMessage} req - The HTTP request object.
 * @param {http.ServerResponse} res - The HTTP response object.
 */
function requestHandler(req, res) {
  req.setEncoding('utf8');

  const parsed = new URL(req.url, 'http://localhost');
  const pathname = parsed.pathname;

  console.log('[' + new Date() + ']', req.method, pathname);

  if (pathname === '/') {
    pathname = '/index.html';
  }

  switch (pathname) {
    case '/index.html':
      pipeFileToResponse(res, './client.html', 'text/html');
      break;

    case '/axios.js':
      pipeFileToResponse(res, '../dist/axios.js', 'text/javascript');
      break;

    case '/axios.js.map':
      pipeFileToResponse(res, '../dist/axios.js.map', 'text/javascript');
      break;

    case '/api':
      handleApiRequest(req, res);
      break;

    default:
      res.writeHead(404);
      res.end('<h1>404 Not Found</h1>');
      break;
  }
}

const PORT = 3000;

// Create and start the HTTP server
server = http.createServer(requestHandler);

server.listen(PORT, () => {
  console.log(`Listening on localhost:${PORT}...`);
});

/**
 * Handles server errors, e.g., port already in use.
 *
 * @param {NodeJS.ErrnoException} error - The server error object.
 */
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.log(`Address localhost:${PORT} in use. Please retry when the port is available!`);
    server.close();
  }
});

import axios from 'axios';

function enhanceNetworkError(error) {
  // when Offline (no internet)
  if (typeof navigator !== 'undefined' && !navigator.onLine) {
    error.code = 'ERR_NO_INTERNET';
    error.detailedMessage =
      'No internet connection detected. Please check your connection and try again.';
  }

  // when DNS failure occurs (invalid domain)
  else if (error.code === 'ENOTFOUND' || /dns/i.test(error.message)) {
    error.code = 'ERR_DNS_FAILURE';
    error.detailedMessage =
      'Unable to reach the requested domain. Please verify the URL or your network settings.';
  }

  // when Connection refused by server
  else if (error.code === 'ECONNREFUSED' || /refused/i.test(error.message)) {
    error.code = 'ERR_CONNECTION_REFUSED';
    error.detailedMessage =
      'Connection was refused by the server. It may be temporarily unavailable.';
  }

  // when Request timeout happens
  else if (error.code === 'ETIMEDOUT' || /timeout/i.test(error.message)) {
    error.code = 'ERR_TIMEOUT';
    error.detailedMessage = 'The request took too long to respond. Please try again later.';
  }

  // when CORS restriction happens (for browser only)
  else if (/CORS/i.test(error.message)) {
    error.code = 'ERR_CORS_BLOCKED';
    error.detailedMessage = 'The request was blocked due to cross-origin restrictions.';
  }

  // when Server-side error occurs
  else if (error.response && error.response.status >= 500) {
    error.code = 'ERR_SERVER';
    error.detailedMessage = 'A server-side issue occurred. Please try again later.';
  }

  // when Client-side error occurs
  else if (error.response && error.response.status >= 400) {
    error.code = 'ERR_CLIENT';
    error.detailedMessage = 'A client-side error occurred. Please check your request.';
  }

  //  when unknown network issue occurs
  else {
    error.code = 'ERR_NETWORK_GENERIC';
    error.detailedMessage =
      'A network issue occurred. Please check your connection or try again later.';
  }

  return error;
}

export function createEnhancedClient(config = {}) {
  const client = axios.create(config);

  client.interceptors.response.use(
    (response) => response,
    (error) => {
      throw enhanceNetworkError(error);
    }
  );

  return client;
}

export default enhanceNetworkError;

import fs from 'fs';
import path from 'path';
import http from 'http';
import minimist from 'minimist';
import url from 'url';

const argv = minimist(process.argv.slice(2));
let server;
let dirs;

const __filename = url.fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function listDirs(root) {
  const files = fs.readdirSync(root);
  const dirs = [];

  for (let i = 0, l = files.length; i < l; i++) {
    const file = files[i];
    if (file[0] !== '.') {
      const stat = fs.statSync(path.join(root, file));
      if (stat.isDirectory()) {
        dirs.push(file);
      }
    }
  }

  return dirs;
}

function getIndexTemplate() {
  const links = dirs.map(function (dir) {
    const url = '/' + dir;
    return (
      '<li onclick="document.location=\'' + url + '\'"><a href="' + url + '">' + url + '</a></li>'
    );
  });

  return (
    '<!doctype html>' +
    '<html>' +
    '<head>' +
    '<title>axios examples</title>' +
    '<style>' +
    'body {padding:25px;}' +
    'ul {margin:0; padding:0; list-style:none;}' +
    'li {padding:5px 10px;}' +
    'li:hover {background:#eee; cursor:pointer;}' +
    'a {text-decoration:none; color:#0080ff;}' +
    '</style>' +
    '<body>' +
    '<ul>' +
    links.join('') +
    '</ul>'
  );
}

function sendResponse(res, statusCode, body) {
  res.writeHead(statusCode);
  res.write(body);
  res.end();
}

function send200(res, body) {
  sendResponse(res, 200, body || '<h1>OK</h1>');
}

function send404(res, body) {
  sendResponse(res, 404, body || '<h1>Not Found</h1>');
}

function pipeFileToResponse(res, file, type) {
  try {
    // Validate file path - prevent directory traversal
    const safeBasePath = path.join(__dirname, 'examples');
    const resolvedPath = path.resolve(path.join(safeBasePath, file));

    // Ensure the resolved path is within intended directory
    if (!resolvedPath.startsWith(safeBasePath)) {
      res.writeHead(400);
      res.end('Invalid file path');
      return;
    }

    // Check if file exists
    if (!fs.existsSync(resolvedPath)) {
      res.writeHead(404);
      res.end('File not found');
      return;
    }

    if (type) {
      res.writeHead(200, {
        'Content-Type': type,
      });
    } else {
      res.writeHead(200);
    }

    const stream = fs.createReadStream(resolvedPath);

    stream.on('error', (err) => {
      console.error('Error while reading file:', err.message);
      if (!res.headersSent) {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
      }
      res.end('File read error');
    });

    stream.pipe(res);
  } catch (err) {
    console.error('Unexpected error:', err.message);
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
    }
    res.end('Internal server error');
  }
}

dirs = listDirs(__dirname);

server = http.createServer(function (req, res) {
  let url = req.url;

  // Process axios itself
  if (/axios\.min\.js$/.test(url)) {
    pipeFileToResponse(res, '../dist/axios.min.js', 'text/javascript');
    return;
  }
  if (/axios\.min\.map$/.test(url)) {
    pipeFileToResponse(res, '../dist/axios.min.map', 'text/javascript');
    return;
  }
  if (/axios\.amd\.min\.js$/.test(url)) {
    pipeFileToResponse(res, '../dist/axios.amd.min.js', 'text/javascript');
    return;
  }
  if (/axios\.amd\.min\.map$/.test(url)) {
    pipeFileToResponse(res, '../dist/axios.amd.min.map', 'text/javascript');
    return;
  }

  // Process /
  if (url === '/' || url === '/index.html') {
    send200(res, getIndexTemplate());
    return;
  }

  // Format request */ -> */index.html
  if (/\/$/.test(url)) {
    url += 'index.html';
  }

  // Format request /get -> /get/index.html
  const parts = url.split('/');
  if (dirs.indexOf(parts[parts.length - 1]) > -1) {
    url += '/index.html';
  }

  // Process index.html request
  if (/index\.html$/.test(url)) {
    if (fs.existsSync(path.join(__dirname, url))) {
      pipeFileToResponse(res, url, 'text/html');
    } else {
      send404(res);
    }
    return;
  }

  // Process server request
  else if (new RegExp('(' + dirs.join('|') + ')\/server').test(url)) {
    if (fs.existsSync(path.join(__dirname, url + '.js'))) {
      import('file://' + path.join(__dirname, url + '.js'))
        .then((server) => {
          server.default(req, res);
        })
        .catch((err) => {
          console.error('Error importing server:', err);
          send404(res);
        });
    } else {
      send404(res);
    }
    return;
  } else {
    send404(res);
  }
});

const PORT = argv.p || 3000;

server.listen(PORT, () => {
  console.log(`Examples running on ${PORT}`);
});

export default function (req, res) {
  let data = '';

  req.on('data', function (chunk) {
    data += chunk;
  });

  req.on('end', function () {
    console.log('POST data received');
    res.writeHead(200, {
      'Content-Type': 'application/json',
    });
    res.write(JSON.stringify(data));
    res.end();
  });
}

export default function (req, res) {
  let parsedUrl;
  try {
    parsedUrl = new URL(req.url, 'http://localhost');
  } catch {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end('Invalid URL');
    return;
  }
  const delay = parsedUrl.searchParams.get('delay') || 3000;

  setTimeout(() => {
    res.writeHead(200, {
      'Content-Type': 'text/json',
    });
    res.write(
      JSON.stringify({
        message: 'Response completed successfully after ' + delay + 'ms',
      })
    );
    res.end();
  }, delay);
}

